window.KITAB_MBCL_DATA["matius"] = {"edition":"MBCL","book":{"id":"matius","nameBn":"মথি","chapters":28},"contentSha256":"bdc63a8cdfb05f1931d30303620ae5787071698ff9a8d658543ead0b94ded64e","chapters":{"1":[{"heading":"হযরত ঈসা মসীহের বংশ-তালিকা","v":1,"ve":1,"vl":"1","bn":"ঈসা মসীহ্‌ দাউদের বংশের এবং দাউদ ইব্রাহিমের বংশের লোক। ঈসা মসীহের বংশের তালিকা এই:"},{"v":2,"ve":2,"vl":"2","bn":"ইব্রাহিমের ছেলে ইসহাক; ইসহাকের ছেলে ইয়াকুব; ইয়াকুবের ছেলে এহুদা ও তাঁর ভাইয়েরা;"},{"v":3,"ve":3,"vl":"3","bn":"এহুদার ছেলে পেরস ও সেরহ- তাঁদের মা ছিলেন তামর; পেরসের ছেলে হিষ্রোণ; হিষ্রোণের ছেলে রাম;"},{"v":4,"ve":4,"vl":"4","bn":"রামের ছেলে অম্মীনাদব; অম্মীনাদবের ছেলে নহশোন; নহশোনের ছেলে সল্‌মোন;"},{"v":5,"ve":5,"vl":"5","bn":"সল্‌মোনের ছেলে বোয়স- তাঁর মা ছিলেন রাহব; বোয়সের ছেলে ওবেদ- তাঁর মা ছিলেন রূত; ওবেদের ছেলে ইয়াসি;"},{"v":6,"ve":6,"vl":"6","bn":"ইয়াসির ছেলে বাদশাহ্‌ দাউদ। দাউদের ছেলে সোলায়মান্ত তাঁর মা ছিলেন উরিয়ার বিধবা স্ত্রী;"},{"v":7,"ve":7,"vl":"7","bn":"সোলায়মানের ছেলে রহবিয়াম; রহবিয়ামের ছেলে অবিয়; অবিয়ের ছেলে আসা;"},{"v":8,"ve":8,"vl":"8","bn":"আসার ছেলে যিহোশাফট; যিহোশাফটের ছেলে যোরাম; যোরামের ছেলে ঊষিয়;"},{"v":9,"ve":9,"vl":"9","bn":"ঊষিয়ের ছেলে যোথম; যোথমের ছেলে আহস; আহসের ছেলে হিষ্কিয়;"},{"v":10,"ve":10,"vl":"10","bn":"হিষ্কিয়ের ছেলে মানশা; মানশার ছেলে আমোন; আমোনের ছেলে যোশিয়;"},{"v":11,"ve":11,"vl":"11","bn":"যোশিয়ের ছেলে যিকনিয় ও তাঁর ভাইয়েরা- ইসরাইল জাতিকে ব্যাবিলন দেশে বন্দী হিসাবে নিয়ে যাবার সময় এঁরা ছিলেন।"},{"v":12,"ve":12,"vl":"12","bn":"যিকনিয়ের ছেলে শল্‌টিয়েল- ইসরাইল জাতিকে ব্যাবিলনে বন্দী করে নিয়ে যাবার পরে এঁর জন্ম হয়েছিল; শল্‌টিয়েলের ছেলে সরুব্বাবিল;"},{"v":13,"ve":13,"vl":"13","bn":"সরুব্বাবিলের ছেলে অবীহূদ; অবীহূদের ছেলে ইলীয়াকীম; ইলীয়াকীমের ছেলে আসোর;"},{"v":14,"ve":14,"vl":"14","bn":"আসোরের ছেলে সাদোক; সাদোকের ছেলে আখীম; আখীমের ছেলে ইলীহূদ;"},{"v":15,"ve":15,"vl":"15","bn":"ইলীহূদের ছেলে ইলিয়াসর; ইলিয়াসরের ছেলে মত্তন; মত্তনের ছেলে ইয়াকুব;"},{"v":16,"ve":16,"vl":"16","bn":"ইয়াকুবের ছেলে ইউসুফ- ইনি মরিয়মের স্বামী। এই মরিয়মের গর্ভে ঈসা, যাঁকে মসীহ্‌ বলা হয়, তাঁর জন্ম হয়েছিল।"},{"v":17,"ve":17,"vl":"17","bn":"এইভাবে ইব্রাহিম থেকে দাউদ পর্যন্ত চৌদ্দ পুরুষ; দাউদ থেকে ব্যাবিলনে বন্দী করে নিয়ে যাবার সময় পর্যন্ত চৌদ্দ পুরুষ; ব্যাবিলনে বন্দী হবার পর থেকে মসীহ্‌ পর্যন্ত চৌদ্দ পুরুষ।"},{"heading":"হযরত ঈসা মসীহের জন্ম","v":18,"ve":18,"vl":"18","bn":"ঈসা মসীহের জন্ম এইভাবে হয়েছিল। ইউসুফের সংগে ঈসার মা মরিয়মের বিয়ের ঠিক হয়েছিল, কিন্তু তাঁরা একসংগে বাস করবার আগেই পাক-রূহের শক্তিতে মরিয়ম গর্ভবতী হয়েছিলেন।"},{"v":19,"ve":19,"vl":"19","bn":"মরিয়মের স্বামী ইউসুফ সৎ লোক ছিলেন, কিন্তু তিনি লোকের সামনে মরিয়মকে লজ্জায় ফেলতে চাইলেন না; এইজন্য তিনি গোপনে তাঁকে তালাক দেবেন বলে ঠিক করলেন।"},{"v":20,"ve":20,"vl":"20","bn":"ইউসুফ যখন এই সব ভাবছিলেন তখন মাবুদের এক ফেরেশতা স্বপ্নে দেখা দিয়ে তাঁকে বললেন, “দাউদের বংশধর ইউসুফ, মরিয়মকে বিয়ে করতে ভয় কোরো না, কারণ তাঁর গর্ভে যিনি জন্মেছে তিনি পাক-রূহের শক্তিতেই জন্মেছেন। তাঁর একটি ছেলে হবে।"},{"v":21,"ve":21,"vl":"21","bn":"তুমি তাঁর নাম ঈসা রাখবে, কারণ তিনি তাঁর লোকদের তাদের গুনাহ্‌ থেকে নাজাত করবেন।”"},{"v":22,"ve":22,"vl":"22","bn":"এই সব হয়েছিল যেন নবীর মধ্য দিয়ে মাবুদ এই যে কথা বলেছিলেন তা পূর্ণ হয়:"},{"v":23,"ve":23,"vl":"23","bn":"“একজন অবিবাহিতা সতী মেয়ে গর্ভবতী হবে, আর তাঁর একটি ছেলে হবে; তাঁর নাম রাখা হবে ইম্মানূয়েল।” এই নামের মানে হল, আমাদের সংগে আল্লাহ্‌।"},{"v":24,"ve":24,"vl":"24","bn":"মাবুদের ফেরেশতা ইউসুফকে যেমন হুকুম দিয়েছিলেন, ঘুম থেকে উঠে তিনি তেমনই করলেন। তিনি মরিয়মকে বিয়ে করলেন,"},{"v":25,"ve":25,"vl":"25","bn":"কিন্তু ছেলের জন্ম না হওয়া পর্যন্ত তাঁর সংগে মিলিত হলেন না। পরে ইউসুফ ছেলেটির নাম ঈসা রাখলেন।"}],"2":[{"heading":"হযরত ঈসা মসীহের তালাশে পণ্ডিতেরা","v":1,"ve":1,"vl":"1","bn":"এহুদিয়া প্রদেশের বেথেলহেম গ্রামে ঈসার জন্ম হয়েছিল। তখন বাদশাহ্‌ ছিলেন হেরোদ। পূর্বদেশ থেকে কয়েকজন পণ্ডিত জেরুজালেমে এসে বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“ইহুদীদের যে বাদশাহ্‌ জন্মেছেন তিনি কোথায়? পূর্ব দিকের আসমানে আমরা তাঁর তারা দেখে মাটিতে উবুড় হয়ে তাঁকে সম্মান দেখাতে এসেছি।”"},{"v":3,"ve":3,"vl":"3","bn":"এই কথা শুনে বাদশাহ্‌ হেরোদ এবং তাঁর সংগে জেরুজালেমের অন্য সকলে অস্থির হয়ে উঠলেন।"},{"v":4,"ve":4,"vl":"4","bn":"হেরোদ সমস্ত প্রধান ইমাম ও আলেমদের ডেকে জিজ্ঞাসা করলেন মসীহ্‌ কোথায় জন্মগ্রহণ করবেন।"},{"v":5,"ve":5,"vl":"5","bn":"তাঁরা তাঁকে বললেন, “এহুদিয়ার বেথেলহেম গ্রামে তিনি জন্মগ্রহণ করবেন, কারণ নবী এই কথা লিখেছেন:"},{"v":6,"ve":6,"vl":"6","bn":"এহুদিয়া দেশের বেথেলহেম, এহুদিয়ার মধ্যে তুমি কোনমতেই ছোট নও, কারণ তোমার মধ্য থেকেই এমন একজন শাসনকর্তা আসবেন যিনি আমার ইসরাইল জাতিকে পরিচালনা করবেন।”"},{"v":7,"ve":7,"vl":"7","bn":"তখন হেরোদ সেই পণ্ডিতদের গোপনে ডাকলেন এবং জেনে নিলেন ঠিক কোন্‌ সময়ে তারাটা দেখা গিয়েছিল।"},{"v":8,"ve":8,"vl":"8","bn":"তিনি পণ্ডিতদের এই কথা বলে বেথেলহেমে পাঠিয়ে দিলেন, “আপনারা গিয়ে ভাল করে সেই শিশুটির খোঁজ করুন। তাঁকে খুঁজে পেলে পর আমাকে জানাবেন যেন আমিও গিয়ে মাটিতে উবুড় হয়ে তাঁকে সম্মান দেখাতে পারি।”"},{"v":9,"ve":9,"vl":"9","bn":"বাদশাহ্‌র কথা শুনে পণ্ডিতেরা চলে গেলেন। তাঁরা পূর্ব দিকে যে তারাটা দেখেছিলেন সেই তারাটা তাঁদের আগে আগে চলল। শিশুটি যেখানে ছিলেন সেই ঘরের উপরে এসে না থামা পর্যন্ত তারাটা চলতেই থাকল।"},{"v":10,"ve":11,"vl":"10-11","bn":"তারাটা দেখে পণ্ডিতেরা খুব আনন্দিত হয়ে ঘরের মধ্যে ঢুকলেন এবং সেই শিশুটিকে তাঁর মা মরিয়মের কাছে দেখতে পেলেন। তখন তাঁরা মাটিতে উবুড় হয়ে সেই শিশুটিকে সম্মান দেখালেন এবং তাদের বাক্স খুলে তাঁকে সোনা, লোবান ও গন্ধরস উপহার দিলেন।"},{"v":12,"ve":12,"vl":"12","bn":"পরে আল্লাহ্‌ স্বপ্নে তাঁদের সাবধান করে দিলেন যেন তাঁরা হেরোদের কাছে ফিরে না যান। তখন তাঁরা অন্য পথে নিজেদের দেশে ফিরে গেলেন।"},{"heading":"হযরত ঈসা মসীহের তালাশে হেরোদ","v":13,"ve":13,"vl":"13","bn":"পণ্ডিতেরা চলে যাবার পর মাবুদের এক ফেরেশতা স্বপ্নে ইউসুফকে দেখা দিয়ে বললেন, “ওঠো, ছেলেটি ও তাঁর মাকে নিয়ে মিসর দেশে পালিয়ে যাও আর আমি যতদিন না বলি ততদিন পর্যন্ত সেখানেই থাক, কারণ ছেলেটিকে মেরে ফেলবার জন্য হেরোদ তাঁর খোঁজ করবে।”"},{"v":14,"ve":15,"vl":"14-15","bn":"তখন ইউসুফ উঠে সেই ছেলে ও তাঁর মাকে নিয়ে সেই রাতেই মিসরে রওনা হলেন এবং হেরোদের মৃত্যু পর্যন্ত সেখানেই রইলেন। এটা ঘটল যাতে নবীর মধ্য দিয়ে মাবুদ এই যে কথা বলেছিলেন তা পূর্ণ হয়: আমি মিসর থেকে আমার পুত্রকে ডেকে এনেছিলাম।"},{"v":16,"ve":16,"vl":"16","bn":"পণ্ডিতেরা তাঁকে ঠকিয়েছেন দেখে হেরোদ ভীষণ রেগে গেলেন। সেই পণ্ডিতদের কাছ থেকে যে সময়ের কথা তিনি জেনে নিয়েছিলেন সেই সময়ের হিসাব মত দুই বছর ও তার কম বয়সের যত ছেলে বেথেলহেম ও তাঁর আশেপাশের জায়গাগুলোতে ছিল সকলকে হত্যা করবার হুকুম দিলেন।"},{"v":17,"ve":17,"vl":"17","bn":"তাতে নবী ইয়ারমিয়ার মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হল:"},{"v":18,"ve":18,"vl":"18","bn":"রামায় ভীষণ কান্নাকাটির শব্দ শোনা যাচ্ছে; রাহেলা তার সন্তানদের জন্য কাঁদছে, কিছুতেই শান্ত হচ্ছে না, কারণ তারা আর নেই।"},{"v":19,"ve":19,"vl":"19","bn":"হেরোদ মারা যাবার পর মাবুদের এক ফেরেশতা মিসর দেশে ইউসুফকে স্বপ্নে দেখা দিয়ে বললেন,"},{"v":20,"ve":20,"vl":"20","bn":"“ওঠো, ছেলেটি এবং তাঁর মাকে নিয়ে ইসরাইল দেশে ফিরে যাও। ছেলেটিকে যারা মেরে ফেলতে চেয়েছিল তারা মারা গেছে।”"},{"v":21,"ve":21,"vl":"21","bn":"তখন ইউসুফ উঠে সেই ছেলেটি ও তাঁর মাকে নিয়ে ইসরাইল দেশে গেলেন।"},{"v":22,"ve":22,"vl":"22","bn":"এহুদিয়া প্রদেশে সেই সময় হেরোদের পরে তাঁর ছেলে আর্খিলায় বাদশাহ্‌ হয়েছিলেন। এই কথা শুনে ইউসুফ সেখানে যেতে ভয় পেলেন। পরে স্বপ্নে হুকুম পেয়ে তিনি গালীল প্রদেশে চলে গেলেন,"},{"v":23,"ve":23,"vl":"23","bn":"আর নাসরত নামে একটা গ্রামে গিয়ে বাস করতে লাগলেন। এটা ঘটল যাতে নবীদের মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হয়: “তাঁকে নাসরতীয় বলে ডাকা হবে।”"}],"3":[{"heading":"হযরত ইয়াহিয়া (আঃ)-এর তবলিগ","v":1,"ve":1,"vl":"1","bn":"পরে তরিকাবন্দীদাতা ইয়াহিয়া এহুদিয়ার মরুভূমিতে এসে এই বলে তবলিগ করতে লাগলেন,"},{"v":2,"ve":2,"vl":"2","bn":"“তওবা কর, কারণ বেহেশতী রাজ্য কাছে এসে গেছে।”"},{"v":3,"ve":3,"vl":"3","bn":"এই ইয়াহিয়ার বিষয়েই নবী ইশাইয়া বলেছিলেন, মরুভূমিতে একজনের কণ্ঠস্বর চিৎকার করে জানাচ্ছে, “তোমরা মাবুদের পথ ঠিক কর; তাঁর রাস্তা সোজা কর।”"},{"v":4,"ve":4,"vl":"4","bn":"ইয়াহিয়া উটের লোমের কাপড় পরতেন এবং তাঁর কোমরে চামড়ার কোমর-বাঁধনি ছিল। তিনি পংগপাল ও বনমধু খেতেন।"},{"v":5,"ve":5,"vl":"5","bn":"জেরুজালেম, সমস্ত এহুদিয়া এবং জর্ডান নদীর চারপাশের লোকেরা সেই সময় তাঁর কাছে আসতে লাগল।"},{"v":6,"ve":6,"vl":"6","bn":"এই লোকেরা যখন নিজেদের গুনাহ্‌ স্বীকার করল তখন ইয়াহিয়া জর্ডান নদীতে তাদের তরিকাবন্দী দিলেন।"},{"v":7,"ve":7,"vl":"7","bn":"পরে ইয়াহিয়া দেখলেন অনেক ফরীশী ও সদ্দূকী তরিকাবন্দী নেবার জন্য তাঁর কাছে আসছেন। তিনি তাঁদের বললেন, “সাপের বংশধরেরা! আল্লাহ্‌র যে গজব নেমে আসছে তা থেকে পালিয়ে যাবার এই বুদ্ধি তোমাদের কে দিল?"},{"v":8,"ve":8,"vl":"8","bn":"ভাল, তোমরা যে তওবা করেছ তার উপযুক্ত ফল তোমাদের জীবনে দেখাও।"},{"v":9,"ve":9,"vl":"9","bn":"তোমরা ইব্রাহিমের বংশের লোক, এটা নিজেদের মনে বলতে পারবার কথা চিন্তাও কোরো না। আমি তোমাদের বলছি, আল্লাহ্‌ এই পাথরগুলো থেকে ইব্রাহিমের বংশধর তৈরী করতে পারেন।"},{"v":10,"ve":10,"vl":"10","bn":"গাছের গোড়াতে কুড়াল লাগানোই আছে। যে গাছে ভাল ফল ধরে না তা কেটে আগুনে ফেলে দেওয়া হবে।"},{"v":11,"ve":11,"vl":"11","bn":"তওবা করেছ বলে আমি তোমাদের পানিতে তরিকাবন্দী দিচ্ছি, কিন্তু আমার পরে যিনি আসছেন তিনি আমার চেয়ে শক্তিশালী। আমি তাঁর জুতা বইবারও যোগ্য নই। তিনি পাক-রূহ্‌ ও আগুনে তোমাদের তরিকাবন্দী দেবেন।"},{"v":12,"ve":12,"vl":"12","bn":"কুলা তাঁর হাতেই আছে এবং তাঁর ফসল মাড়াবার জায়গা তিনি ভাল করেই পরিষ্কার করবেন। তিনি তাঁর ফসল গোলাতে জমা করবেন, কিন্তু যে আগুন কখনও নেভে না সেই আগুনে তুষ পুড়িয়ে ফেলবেন।”"},{"heading":"হযরত ঈসা মসীহের তরিকাবন্দী","v":13,"ve":13,"vl":"13","bn":"সেই সময় ঈসা তরিকাবন্দী নেবার জন্য গালীল থেকে জর্ডান নদীর ধারে ইয়াহিয়ার কাছে আসলেন।"},{"v":14,"ve":14,"vl":"14","bn":"ইয়াহিয়া কিন্তু তাঁকে এই কথা বলে বাধা দিতে চেষ্টা করলেন, “আমারই বরং আপনার কাছে তরিকাবন্দী নেওয়া দরকার; আর আপনি কিনা আসছেন আমার কাছে!”"},{"v":15,"ve":15,"vl":"15","bn":"তখন ঈসা তাঁকে বললেন, “কিন্তু এবার এই রকমই হোক, কারণ আল্লাহ্‌র ইচ্ছা এইভাবেই আমাদের পূর্ণ করা উচিত।” তখন ইয়াহিয়া রাজী হলেন।"},{"v":16,"ve":16,"vl":"16","bn":"তরিকাবন্দী নেবার পর ঈসা পানি থেকে উঠে আসবার সংগে সংগেই তাঁর সামনে আসমান খুলে গেল। তিনি আল্লাহ্‌র রূহ্‌কে কবুতরের মত হয়ে তাঁর উপরে নেমে আসতে দেখলেন।"},{"v":17,"ve":17,"vl":"17","bn":"তখন বেহেশত থেকে বলা হল, “ইনিই আমার প্রিয় পুত্র, এঁর উপর আমি খুবই সন্তুষ্ট।”"}],"4":[{"heading":"হযরত ঈসা মসীহ্‌কে গুনাহে ফেলবার চেষ্টা","v":1,"ve":1,"vl":"1","bn":"এর পরে পাক-রূহ্‌ ঈসাকে মরুভূমিতে নিয়ে গেলেন যেন ইবলিস ঈসাকে লোভ দেখিয়ে গুনাহে ফেলবার চেষ্টা করতে পারে।"},{"v":2,"ve":2,"vl":"2","bn":"সেখানে চল্লিশ দিন ও চল্লিশ রাত রোজা রাখবার পর ঈসার খিদে পেল।"},{"v":3,"ve":3,"vl":"3","bn":"তখন শয়তান এসে তাঁকে বলল, “তুমি যদি ইব্‌নুল্লাহ্‌ হও তবে এই পাথরগুলোকে রুটি হয়ে যেতে বল।”"},{"v":4,"ve":4,"vl":"4","bn":"ঈসা জবাবে বললেন, “পাক-কিতাবে লেখা আছে, মানুষ কেবল রুটিতেই বাঁচে না, কিন্তু আল্লাহ্‌র মুখের প্রত্যেকটি কালামেই বাঁচে।”"},{"v":5,"ve":5,"vl":"5","bn":"তখন ইবলিস ঈসাকে পবিত্র শহর জেরুজালেমে নিয়ে গেল এবং বায়তুল-মোকাদ্দসের চূড়ার উপর তাঁকে দাঁড় করিয়ে বলল,"},{"v":6,"ve":6,"vl":"6","bn":"“তুমি যদি ইব্‌নুল্লাহ্‌ হও তবে লাফ দিয়ে নীচে পড়, কারণ পাক-কিতাবে লেখা আছে, আল্লাহ্‌ তাঁর ফেরেশতাদের তোমার বিষয়ে হুকুম দেবেন; তাঁরা তোমাকে হাত দিয়ে ধরে ফেলবেন যাতে তোমার পায়ে পাথরের আঘাত না লাগে।”"},{"v":7,"ve":7,"vl":"7","bn":"ঈসা ইবলিসকে বললেন, “আবার এই কথাও লেখা আছে, তোমার মাবুদ আল্লাহ্‌কে তুমি পরীক্ষা করতে যেয়ো না।”"},{"v":8,"ve":8,"vl":"8","bn":"তখন ইবলিস আবার তাঁকে খুব উঁচু একটা পাহাড়ে নিয়ে গেল এবং দুনিয়ার সমস্ত রাজ্য ও তাঁদের জাঁকজমক দেখিয়ে বলল,"},{"v":9,"ve":9,"vl":"9","bn":"“তুমি যদি মাটিতে পড়ে আমাকে সেজদা কর তবে এই সবই আমি তোমাকে দেব।”"},{"v":10,"ve":10,"vl":"10","bn":"তখন ঈসা তাকে বললেন, “দূর হও, শয়তান। পাক-কিতাবে লেখা আছে, তুমি তোমার মাবুদ আল্লাহ্‌কেই ভয় করবে, কেবল তাঁরই এবাদত করবে।”"},{"v":11,"ve":11,"vl":"11","bn":"তখন ইবলিস তাঁকে ছেড়ে চলে গেল, আর ফেরেশতারা এসে তাঁর সেবা করতে লাগলেন।"},{"heading":"হযরত ঈসা মসীহের কাজের শুরু","v":12,"ve":13,"vl":"12-13","bn":"পরে ঈসা শুনলেন ইয়াহিয়াকে জেলখানায় বন্দী করে রাখা হয়েছে। তখন তিনি গালীলে চলে গেলেন এবং নাসরত গ্রাম ছেড়ে সবূলূন ও নপ্তালি এলাকার মধ্যে সাগর পারের কফরনাহূম শহরে গিয়ে রইলেন।"},{"v":14,"ve":14,"vl":"14","bn":"এটা হল যাতে নবী ইশাইয়ার মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হয়:"},{"v":15,"ve":15,"vl":"15","bn":"সবূলূন ও নপ্তালি এলাকার, সমুদ্রের দিকের, জর্ডানের অন্য পারের এবং অ-ইহুদীদের গালীলের"},{"v":16,"ve":16,"vl":"16","bn":"যে লোকেরা অন্ধকারে বাস করে, তারা মহানূর দেখতে পাবে। যারা ঘন অন্ধকারের দেশে বাস করে, তাদের কাছে আলো প্রকাশিত হবে।"},{"v":17,"ve":17,"vl":"17","bn":"সেই সময় থেকে ঈসা এই বলে তবলিগ করতে লাগলেন, “তওবা কর, কারণ বেহেশতী রাজ্য কাছে এসে গেছে।”"},{"heading":"সাহাবী গ্রহণ","v":18,"ve":18,"vl":"18","bn":"ঈসা গালীল সাগরের পার দিয়ে যাবার সময় শিমোন, যাঁকে পিতর বলা হয় আর তাঁর ভাই আন্দ্রিয়কে দেখতে পেলেন। তাঁরা সাগরে জাল ফেলছিলেন, কারণ তাঁরা ছিলেন জেলে।"},{"v":19,"ve":19,"vl":"19","bn":"ঈসা তাঁদের বললেন, “আমার সংগে চল, আমি তোমাদের মানুষ-ধরা জেলে করব।”"},{"v":20,"ve":20,"vl":"20","bn":"তখনই তাঁরা জাল ফেলে রেখে ঈসার সংগে গেলেন।"},{"v":21,"ve":21,"vl":"21","bn":"সেখান থেকে এগিয়ে গিয়ে তিনি ইয়াকুব ও ইউহোন্না নামে অন্য দুই ভাইকে দেখতে পেলেন। তাঁরা ছিলেন সিবদিয়ের ছেলে। তাঁদের বাবা সিবদিয়ের সংগে নৌকায় বসে তাঁরা জাল ঠিক করছিলেন। ঈসা সেই দুই ভাইকেও ডাকলেন।"},{"v":22,"ve":22,"vl":"22","bn":"তাঁরা তখনই তাঁদের নৌকা ও বাবাকে ছেড়ে ঈসার সংগে গেলেন।"},{"heading":"অনেকে সুস্থ হল","v":23,"ve":23,"vl":"23","bn":"গালীল প্রদেশের সমস্ত জায়গায় ঘুরে ঘুরে ইহুদীদের ভিন্ন ভিন্ন মজলিস-খানায় ঈসা শিক্ষা দিতে লাগলেন। এছাড়া তিনি বেহেশতী রাজ্যের সুসংবাদ তবলিগ করতে এবং লোকদের সব রকম রোগ ভাল করতে লাগলেন।"},{"v":24,"ve":24,"vl":"24","bn":"সমস্ত সিরিয়া দেশে তাঁর কথা ছড়িয়ে পড়ল। যে সব লোকেরা নানা রকম রোগে ও ভীষণ যন্ত্রণায় কষ্ট পাচ্ছিল, যাদের ভূতে ধরেছিল এবং যারা মৃগী ও অবশ-রোগে ভুগছিল, লোকেরা তাদের ঈসার কাছে আনল। তিনি তাদের সবাইকে সুস্থ করলেন।"},{"v":25,"ve":25,"vl":"25","bn":"গালীল, দেকাপলি, জেরুজালেম, এহুদিয়া এবং জর্ডানের অন্য পার থেকে অনেক লোক ঈসার পিছনে পিছনে চলল।"}],"5":[{"heading":"পাহাড়ের উপর শিক্ষাদান","v":1,"ve":1,"vl":"1","bn":"ঈসা অনেক লোক দেখে পাহাড়ের উপর উঠলেন। তিনি বসলে পর তাঁর সাহাবীরা তাঁর কাছে আসলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন তিনি সাহাবীদের এই বলে শিক্ষা দিতে লাগলেন:"},{"v":3,"ve":3,"vl":"3","bn":"“ধন্য তারা, যারা দিলে নিজেদের গরীব মনে করে, কারণ বেহেশতী রাজ্য তাদেরই।"},{"v":4,"ve":4,"vl":"4","bn":"ধন্য তারা, যারা দুঃখ করে, কারণ তারা সান্ত্বনা পাবে।"},{"v":5,"ve":5,"vl":"5","bn":"ধন্য তারা, যাদের স্বভাব নম্র, কারণ দুনিয়া তাদেরই হবে।"},{"v":6,"ve":6,"vl":"6","bn":"ধন্য তারা, যারা মনেপ্রাণে আল্লাহ্‌র ইচ্ছামত চলতে চায়, কারণ তাদের সেই ইচ্ছা পূর্ণ হবে।"},{"v":7,"ve":7,"vl":"7","bn":"ধন্য তারা, যারা দয়ালু, কারণ তারা দয়া পাবে।"},{"v":8,"ve":8,"vl":"8","bn":"ধন্য তারা, যাদের দিল খাঁটি, কারণ তারা আল্লাহ্‌কে দেখতে পাবে।"},{"v":9,"ve":9,"vl":"9","bn":"ধন্য তারা, যারা লোকদের জীবনে শান্তি আনবার জন্য পরিশ্রম করে, কারণ আল্লাহ্‌ তাদের নিজের সন্তান বলে ডাকবেন।"},{"v":10,"ve":10,"vl":"10","bn":"ধন্য তারা, যারা আল্লাহ্‌র ইচ্ছামত চলতে গিয়ে জুলুম সহ্য করে, কারণ বেহেশতী রাজ্য তাদেরই।"},{"v":11,"ve":11,"vl":"11","bn":"“ধন্য তোমরা, যখন লোকে আমার জন্য তোমাদের অপমান করে ও জুলুম করে এবং মিথ্যা করে তোমাদের নামে সব রকম খারাপ কথা বলে।"},{"v":12,"ve":12,"vl":"12","bn":"তোমরা আনন্দ কোরো ও খুশী হোয়ো, কারণ বেহেশতে তোমাদের জন্য মহা পুরস্কার আছে। তোমাদের আগে যে নবীরা ছিলেন লোকে তাঁদেরও এইভাবে জুলুম করত।"},{"heading":"ঈমানদারেরা লবণ ও আলোর মত","v":13,"ve":13,"vl":"13","bn":"“তোমরা দুনিয়ার লবণ, কিন্তু যদি লবণের স্বাদ নষ্ট হয়ে যায় তবে কেমন করে তা আবার নোন্‌তা করা যাবে? সেই লবণ আর কোন কাজে লাগে না। তা কেবল বাইরে ফেলে দেবার ও লোকের পায়ে মাড়াবার উপযুক্ত হয়।"},{"v":14,"ve":14,"vl":"14","bn":"“তোমরা দুনিয়ার আলো। পাহাড়ের উপরের শহর লুকানো থাকতে পারে না।"},{"v":15,"ve":15,"vl":"15","bn":"কেউ বাতি জ্বেলে ঝুড়ির নীচে রাখে না কিন্তু বাতিদানের উপরেই রাখে। এতে ঘরের সমস্ত লোকই আলো পায়।"},{"v":16,"ve":16,"vl":"16","bn":"সেইভাবে তোমাদের আলো লোকদের সামনে জ্বলুক, যেন তারা তোমাদের ভাল কাজ দেখে তোমাদের বেহেশতী পিতার প্রশংসা করে।"},{"heading":"তৌরাত শরীফের বিষয়ে হযরত ঈসার শিক্ষা","v":17,"ve":17,"vl":"17","bn":"“এই কথা মনে কোরো না, আমি তৌরাত কিতাব আর নবীদের কিতাব বাতিল করতে এসেছি। আমি সেগুলো বাতিল করতে আসি নি বরং পূর্ণ করতে এসেছি।"},{"v":18,"ve":18,"vl":"18","bn":"আমি তোমাদের সত্যিই বলছি, আসমান ও জমীন শেষ না হওয়া পর্যন্ত, যতদিন না তৌরাত কিতাবের সমস্ত কথা সফল হয় ততদিন সেই তৌরাতের এক বিন্দু কি এক মাত্রা মুছে যাবে না।"},{"v":19,"ve":19,"vl":"19","bn":"তাই মূসার শরীয়তের মধ্যে ছোট একটা হুকুমও যে কেউ অমান্য করে এবং লোককে তা অমান্য করতে শিক্ষা দেয় তাকে বেহেশতী রাজ্যে সবচেয়ে ছোট বলা হবে। কিন্তু যে কেউ শরীয়তের হুকুমগুলো পালন করে ও শিক্ষা দেয় তাকে বেহেশতী রাজ্যে বড় বলা হবে।"},{"v":20,"ve":20,"vl":"20","bn":"আমি তোমাদের বলছি, আলেম ও ফরীশীদের ধার্মিকতার চেয়ে তোমাদের যদি বেশী কিছু না থাকে তবে তোমরা কোনমতেই বেহেশতী রাজ্যে ঢুকতে পারবে না।"},{"heading":"রাগের বিষয়ে শিক্ষা","v":21,"ve":21,"vl":"21","bn":"“তোমরা শুনেছ, আগেকার লোকদের কাছে এই কথা বলা হয়েছে, ‘খুন কোরো না; যে খুন করে সে বিচারের দায়ে পড়বে।’"},{"v":22,"ve":22,"vl":"22","bn":"কিন্তু আমি তোমাদের বলছি, যে কেউ তার ভাইয়ের উপর রাগ করে সে বিচারের দায়ে পড়বে। যে কেউ তার ভাইকে বলে, ‘তুমি অপদার্থ,’ সে মহাসভার বিচারের দায়ে পড়বে। আর যে তার ভাইকে বলে, ‘তুমি বিবেকহীন,’ সে জাহান্নামের আগুনের দায়ে পড়বে।"},{"v":23,"ve":23,"vl":"23","bn":"“সেইজন্য আল্লাহ্‌র উদ্দেশে কোরবানগাহের উপরে তোমার দান কোরবানী দেবার সময় যদি মনে পড়ে যে, তোমার বিরুদ্ধে তোমার ভাইয়ের কিছু বলবার আছে,"},{"v":24,"ve":24,"vl":"24","bn":"তবে তোমার দান সেই কোরবানগাহের সামনে রেখে চলে যাও। আগে তোমার ভাইয়ের সংগে আবার মিলিত হও এবং পরে এসে তোমার দান কোরবানী দাও।"},{"v":25,"ve":25,"vl":"25","bn":"“কেউ তোমার বিরুদ্ধে মকদ্দমা করলে আদালতে যাবার আগেই তার সংগে তাড়াতাড়ি মীমাংসা করে ফেল। তা না হলে সে তোমাকে বিচারকের হাতে দেবে, আর বিচারক তোমাকে পুলিশের হাতে দেবে, আর পুলিশ তোমাকে জেলে দেবে।"},{"v":26,"ve":26,"vl":"26","bn":"আমি তোমাকে সত্যি বলছি, শেষ পয়সাটা না দেওয়া পর্যন্ত তুমি সেখান থেকে কিছুতেই ছাড়া পাবে না।"},{"heading":"জেনার বিষয়ে শিক্ষা","v":27,"ve":27,"vl":"27","bn":"“তোমরা শুনেছ, এই কথা বলা হয়েছে, ‘জেনা কোরো না।’"},{"v":28,"ve":28,"vl":"28","bn":"কিন্তু আমি তোমাদের বলছি, যে কেউ কোন স্ত্রীলোকের দিকে কামনার চোখে তাকায় সে তখনই মনে মনে তার সংগে জেনা করল।”"},{"v":29,"ve":29,"vl":"29","bn":"“তোমার ডান চোখ যদি তোমাকে গুনাহের পথে টানে তবে তা উপ্‌ড়ে দূরে ফেলে দাও। তোমার সমস্ত শরীর জাহান্নামে যাওয়ার চেয়ে বরং তার একটা অংশ নষ্ট হওয়া তোমার পক্ষে ভাল।"},{"v":30,"ve":30,"vl":"30","bn":"যদি তোমার ডান হাত তোমাকে গুনাহের পথে টানে তবে তা কেটে ফেলে দাও। তোমার সমস্ত শরীর জাহান্নামে যাওয়ার চেয়ে বরং একটা অংশ নষ্ট হওয়া তোমার পক্ষে ভাল।"},{"v":31,"ve":31,"vl":"31","bn":"“আবার বলা হয়েছে, ‘যে কেউ তার স্ত্রীকে তালাক দেয় সে তাকে তালাক-নামা দিক।’"},{"v":32,"ve":32,"vl":"32","bn":"কিন্তু আমি তোমাদের বলছি, যে কেউ জেনার দোষ ছাড়া অন্য কোন কারণে স্ত্রীকে তালাক দেয় সে তাকে জেনাকারিনী করে তোলে। আর যাকে তালাক দেওয়া হয়েছে সেই স্ত্রীকে যে বিয়ে করে সেও জেনা করে।"},{"heading":"কসমের বিষয়ে শিক্ষা","v":33,"ve":33,"vl":"33","bn":"“আবার তোমরা শুনেছ, আগেকার লোকদের কাছে বলা হয়েছে, ‘মিথ্যা কসম খেয়ো না, বরং মাবুদের উদ্দেশে তোমার সমস্ত কসম পালন কোরো।’"},{"v":34,"ve":34,"vl":"34","bn":"কিন্তু আমি তোমাদের বলছি, একেবারেই কসম খেয়ো না। বেহেশতের নামে খেয়ো না, কারণ তা আল্লাহ্‌র সিংহাসন।"},{"v":35,"ve":35,"vl":"35","bn":"দুনিয়ার নামে খেয়ো না, কারণ তা তাঁর পা রাখবার জায়গা। জেরুজালেমের নামে খেয়ো না, কারণ তা মহান বাদশাহ্‌র শহর।"},{"v":36,"ve":36,"vl":"36","bn":"তোমার মাথার নামে খেয়ো না, কারণ তার একটা চুল সাদা কি কালো করবার ক্ষমতা তোমার নেই।"},{"v":37,"ve":37,"vl":"37","bn":"তোমাদের কথার ‘হ্যাঁ’ যেন ‘হ্যাঁ’ আর ‘না’ যেন ‘না’ হয়; এর বেশী যা, তা ইবলিসের কাছ থেকে আসে।"},{"heading":"প্রতিশোধের বিষয়ে শিক্ষা","v":38,"ve":38,"vl":"38","bn":"“তোমরা শুনেছ, বলা হয়েছে, ‘চোখের বদলে চোখ এবং দাঁতের বদলে দাঁত।’"},{"v":39,"ve":39,"vl":"39","bn":"কিন্তু আমি তোমাদের বলছি, তোমাদের সংগে যে কেউ খারাপ ব্যবহার করে তার বিরুদ্ধে কিছুই কোরো না; বরং যে কেউ তোমার ডান গালে চড় মারে তাকে অন্য গালেও চড় মারতে দিয়ো।"},{"v":40,"ve":40,"vl":"40","bn":"যে কেউ তোমার কোর্তা নেবার জন্য মামলা করতে চায় তাকে তোমার চাদরও নিতে দিয়ো।"},{"v":41,"ve":41,"vl":"41","bn":"যে কেউ তোমাকে তার বোঝা নিয়ে এক মাইল যেতে বাধ্য করে তার সংগে দুই মাইল যেয়ো।"},{"v":42,"ve":42,"vl":"42","bn":"যে তোমার কাছে কিছু চায় তাকে দিয়ো, আর যে তোমার কাছে ধার চায় তাকে দিতে অস্বীকার কোরো না।"},{"heading":"শত্রুকে মহব্বত করবার বিষয়ে শিক্ষা","v":43,"ve":43,"vl":"43","bn":"“তোমরা শুনেছ, বলা হয়েছে, ‘তোমার প্রতিবেশীকে মহব্বত কোরো এবং শত্রুকে ঘৃণা কোরো।’"},{"v":44,"ve":44,"vl":"44","bn":"কিন্তু আমি তোমাদের বলছি, তোমাদের শত্রুদেরও মহব্বত কোরো। যারা তোমাদের জুলুম করে তাদের জন্য মুনাজাত কোরো,"},{"v":45,"ve":45,"vl":"45","bn":"যেন লোকে দেখতে পায় তোমরা সত্যিই তোমাদের বেহেশতী পিতার সন্তান। তিনি তো ভাল-মন্দ সকলের উপরে তাঁর সূর্য উঠান এবং সৎ ও অসৎ লোকদের উপরে বৃষ্টি দেন।"},{"v":46,"ve":46,"vl":"46","bn":"যারা তোমাদের মহব্বত করে কেবল তাদেরই যদি তোমরা মহব্বত কর তবে তোমরা কি পুরস্কার পাবে? খাজনা-আদায়কারীরাও কি তা-ই করে না?"},{"v":47,"ve":47,"vl":"47","bn":"আর যদি তোমরা কেবল তোমাদের নিজেদের লোকদেরই সালাম জানাও তবে অন্যদের চেয়ে বেশী আর কি করছ? অ-ইহুদীরাও কি তা-ই করে না?"},{"v":48,"ve":48,"vl":"48","bn":"এইজন্য বলি, তোমাদের বেহেশতী পিতা যেমন খাঁটি তোমরাও তেমনি খাঁটি হও।"}],"6":[{"heading":"দানের বিষয়ে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"“সাবধান, লোককে দেখাবার জন্য ধর্মকর্ম কোরো না; যদি কর তবে তোমাদের বেহেশতী পিতার কাছ থেকে কোন পুরস্কার পাবে না।"},{"v":2,"ve":2,"vl":"2","bn":"“এইজন্য যখন তুমি গরীবদের কিছু দাও তখন ভণ্ডদের মত কোরো না। তারা তো লোকদের প্রশংসা পাবার জন্য মজলিস-খানায় এবং পথে পথে ঢাক-ঢোল বাজিয়ে ভিক্ষা দেয়। আমি তোমাদের সত্যিই বলছি, তারা তাদের পুরস্কার পেয়ে গেছে।"},{"v":3,"ve":3,"vl":"3","bn":"কিন্তু তুমি যখন গরীবদের কিছু দাও তখন তোমার ডান হাত কি করছে তা তোমার বাঁ হাতকে জানতে দিয়ো না,"},{"v":4,"ve":4,"vl":"4","bn":"যেন তোমার দান করা গোপনে হয়। তাহলে তোমার পিতা, যিনি গোপনে সব কিছু দেখেন, তিনিই তোমাকে পুরস্কার দেবেন।"},{"heading":"মুনাজাতের বিষয়ে শিক্ষা","v":5,"ve":5,"vl":"5","bn":"“তোমরা যখন মুনাজাত কর তখন ভণ্ডদের মত কোরো না, কারণ তারা লোকদের কাছে নিজেদের দেখাবার জন্য মজলিস-খানায় ও রাস্তার মোড়ে দাঁড়িয়ে মুনাজাত করতে ভালবাসে। আমি তোমাদের সত্যিই বলছি, তারা তাদের পুরস্কার পেয়ে গেছে।"},{"v":6,"ve":6,"vl":"6","bn":"কিন্তু তুমি যখন মুনাজাত কর তখন ভিতরের ঘরে গিয়ে দরজা বন্ধ কোরো এবং তোমার পিতা, যাঁকে দেখা না গেলেও উপস্থিত আছেন, তাঁর কাছে মুনাজাত কোরো। তোমার পিতা, যিনি গোপন সব কিছু দেখেন, তিনিই তোমাকে পুরস্কার দেবেন।"},{"v":7,"ve":7,"vl":"7","bn":"“যখন তোমরা মুনাজাত কর তখন অ-ইহুদীদের মত অর্থহীন কথা বার বার বোলো না। অ-ইহুদীরা মনে করে, বেশী কথা বললেই আল্লাহ্‌ তাদের মুনাজাত শুনবেন।"},{"v":8,"ve":8,"vl":"8","bn":"তাদের মত কোরো না, কারণ তোমাদের পিতার কাছে চাইবার আগেই তিনি জানেন তোমাদের কি দরকার।"},{"v":9,"ve":9,"vl":"9","bn":"এইজন্য তোমরা এইভাবে মুনাজাত কোরো: হে আমাদের বেহেশতী পিতা, তোমার নাম পবিত্র বলে মান্য হোক।"},{"v":10,"ve":10,"vl":"10","bn":"তোমার রাজ্য আসুক। তোমার ইচ্ছা যেমন বেহেশতে তেমনি দুনিয়াতেও পূর্ণ হোক।"},{"v":11,"ve":11,"vl":"11","bn":"যে খাবার আমাদের দরকার তা আজ আমাদের দাও।"},{"v":12,"ve":12,"vl":"12","bn":"যারা আমাদের উপর অন্যায় করে, আমরা যেমন তাদের মাফ করেছি তেমনি তুমিও আমাদের সমস্ত অন্যায় মাফ কর।"},{"v":13,"ve":13,"vl":"13","bn":"আমাদের তুমি পরীক্ষায় পড়তে দিয়ো না, বরং শয়তানের হাত থেকে রক্ষা কর।"},{"v":14,"ve":14,"vl":"14","bn":"তোমরা যদি অন্যদের দোষ মাফ কর তবে তোমাদের বেহেশতী পিতা তোমাদেরও মাফ করবেন।"},{"v":15,"ve":15,"vl":"15","bn":"কিন্তু তোমরা যদি অন্যদের দোষ মাফ না কর তবে তোমাদের পিতা তোমাদেরও মাফ করবেন না।"},{"heading":"রোজার বিষয়ে শিক্ষা","v":16,"ve":16,"vl":"16","bn":"“তোমরা যখন রোজা রাখ তখন ভণ্ডদের মত মুখ কালো করে রেখো না। তারা যে রোজা রাখছে তা লোকদের দেখাবার জন্য তারা মাথায় ও মুখে ছাই মেখে বেড়ায়। আমি তোমাদের সত্যিই বলছি, তারা তাদের পুরস্কার পেয়ে গেছে।"},{"v":17,"ve":17,"vl":"17","bn":"কিন্তু তুমি যখন রোজা রাখ তখন মাথায় তেল দিয়ো ও মুখ ধুয়ো,"},{"v":18,"ve":18,"vl":"18","bn":"যেন অন্যেরা জানতে না পারে যে, তুমি রোজা রাখছ। তাহলে তোমার পিতা, যিনি দেখা না গেলেও উপস্থিত আছেন, কেবল তিনিই তা দেখতে পাবেন। তোমার পিতা, যিনি গোপন সব কিছু দেখেন, তিনিই তোমাকে পুরস্কার দেবেন।"},{"heading":"জীবনের সবচেয়ে দরকারী বিষয়ে শিক্ষা","v":19,"ve":19,"vl":"19","bn":"“এই দুনিয়াতে তোমরা নিজেদের জন্য ধন-সম্পদ জমা কোরো না। এখানে মরচে ধরে ও পোকায় নষ্ট করে এবং চোর সিঁদ কেটে চুরি করে।"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু বেহেশতে মরচেও ধরে না, পোকায় নষ্টও করে না এবং চোর সিঁদ কেটে চুরিও করে না। তাই বেহেশতে নিজেদের জন্য ধন জমা কর,"},{"v":21,"ve":21,"vl":"21","bn":"কারণ তোমার ধন যেখানে থাকবে তোমার মনও সেখানে থাকবে।"},{"v":22,"ve":22,"vl":"22","bn":"“চোখ শরীরের বাতি। সেইজন্য তোমার চোখ যদি ভাল হয় তবে তোমার সমস্ত শরীরই আলোতে পূর্ণ হবে।"},{"v":23,"ve":23,"vl":"23","bn":"কিন্তু তোমার চোখ যদি খারাপ হয় তবে তোমার সমস্ত শরীর অন্ধকারে পূর্ণ হবে। তোমার মধ্যে যে আলো আছে তা যদি আসলে অন্ধকারই হয় তবে সেই অন্ধকার কি ভীষণ!"},{"v":24,"ve":24,"vl":"24","bn":"“কেউই দুই কর্তার সেবা করতে পারে না, কারণ সে একজনকে ঘৃণা করবে ও অন্যজনকে ভালবাসবে। সে একজনের উপরে মনোযোগ দেবে ও অন্যজনকে তুচ্ছ করবে। আল্লাহ্‌ এবং ধন-সম্পত্তি এই দু’য়ের সেবা তোমরা একসংগে করতে পার না।"},{"v":25,"ve":25,"vl":"25","bn":"“এইজন্য আমি তোমাদের বলছি, কি খাবে বলে বেঁচে থাকবার বিষয়ে কিংবা কি পরবে বলে শরীরের বিষয়ে চিন্তা কোরো না। প্রাণটা কেবল খাওয়া-দাওয়ার ব্যাপার নয়, আর শরীরটা কেবল কাপড়-চোপড়ের ব্যাপার নয়।"},{"v":26,"ve":26,"vl":"26","bn":"“আকাশের পাখীদের দিকে তাকিয়ে দেখ; তারা বীজ বোনে না, কাটেও না, গোলাঘরে জমাও করে না, আর তবুও তোমাদের বেহেশতী পিতা তাদের খাইয়ে থাকেন। তোমরা কি তাদের থেকে আরও মূল্যবান নও?"},{"v":27,"ve":27,"vl":"27","bn":"তোমাদের মধ্যে কে চিন্তা-ভাবনা করে নিজের আয়ু এক ঘণ্টা বাড়াতে পারে?"},{"v":28,"ve":28,"vl":"28","bn":"“কাপড়-চোপড়ের জন্য কেন চিন্তা কর? মাঠের ফুলগুলোর কথা ভেবে দেখ সেগুলো কেমন করে বেড়ে ওঠে। তারা পরিশ্রম করে না, সুতাও কাটে না।"},{"v":29,"ve":29,"vl":"29","bn":"কিন্তু আমি তোমাদের বলছি, বাদশাহ্‌ সোলায়মান এত জাঁকজমকের মধ্যে থেকেও এগুলোর একটারও মত তিনি নিজেকে সাজাতে পারেন নি।"},{"v":30,"ve":30,"vl":"30","bn":"মাঠের যে ঘাস আজ আছে আর কাল চুলায় ফেলে দেওয়া হবে, তা যখন আল্লাহ্‌ এইভাবে সাজান তখন ওহে অল্প বিশ্বাসীরা, তিনি যে তোমাদের নিশ্চয়ই সাজাবেন তাতে কোন সন্দেহ নেই।"},{"v":31,"ve":31,"vl":"31","bn":"এইজন্য ‘কি খাব’ বা ‘কি পরব’ বলে চিন্তা কোরো না। অ-ইহুদীরাই এই সব বিষয়ের জন্য ব্যস্ত হয়;"},{"v":32,"ve":32,"vl":"32","bn":"তা ছাড়া তোমাদের বেহেশতী পিতা তো জানেন যে, এই সব জিনিস তোমাদের দরকার আছে।"},{"v":33,"ve":33,"vl":"33","bn":"কিন্তু তোমরা প্রথমে আল্লাহ্‌র রাজ্যের বিষয়ে ও তাঁর ইচ্ছামত চলবার জন্য ব্যস্ত হও। তাহলে ঐ সব জিনিসও তোমরা পাবে। কালকের বিষয় চিন্তা কোরো না;"},{"v":34,"ve":34,"vl":"34","bn":"কালকের চিন্তা কালকের উপর ছেড়ে দাও। দিনের কষ্ট দিনের জন্য যথেষ্ট।"}],"7":[{"heading":"দোষ ধরবার বিষয়ে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"“তোমরা অন্যের দোষ ধরে বেড়িয়ো না যেন তোমাদেরও দোষ ধরা না হয়,"},{"v":2,"ve":2,"vl":"2","bn":"কারণ যেভাবে তোমরা অন্যের দোষ ধর সেইভাবে তোমাদেরও দোষ ধরা হবে, আর যেভাবে তোমরা মেপে দাও সেইভাবে তোমাদের জন্যও মাপা হবে।"},{"v":3,"ve":3,"vl":"3","bn":"“তোমার ভাইয়ের চোখে যে কুটা আছে কেবল তা-ই দেখছ, অথচ তোমার নিজের চোখের মধ্যে যে কড়িকাঠ আছে তা লক্ষ্য করছ না কেন?"},{"v":4,"ve":4,"vl":"4","bn":"যখন তোমার নিজের চোখেই কড়িকাঠ রয়েছে তখন কি করে তোমার ভাইকে এই কথা বলছ, ‘এস, তোমার চোখ থেকে কুটাটা বের করে দিই’?"},{"v":5,"ve":5,"vl":"5","bn":"ভণ্ড! প্রথমে তোমার নিজের চোখ থেকে কড়িকাঠটা বের করে ফেল, তাতে তোমার ভাইয়ের চোখ থেকে কুটাটা বের করবার জন্য স্পষ্ট দেখতে পাবে।"},{"v":6,"ve":6,"vl":"6","bn":"“যা পবিত্র তা কুকুরকে দিয়ো না। শূকরের সামনে তোমাদের মুক্তা ছড়ায়ো না। হয়তো তারা সেগুলো তাদের পায়ের তলায় মাড়াবে এবং ফিরে তোমাদের টুকরা টুকরা করে ছিঁড়ে ফেলবে।"},{"heading":"মুনাজাতের বিষয়ে ওয়াদা","v":7,"ve":7,"vl":"7","bn":"“চাও, তোমাদের দেওয়া হবে; খোঁজ কর, পাবে; দরজায় আঘাত দাও, তোমাদের জন্য খোলা হবে।"},{"v":8,"ve":8,"vl":"8","bn":"যারা চায় তারা প্রত্যেকে পায়; যে খোঁজ করে সে পায়; আর যে দরজায় আঘাত দেয় তার জন্য দরজা খোলা হয়।"},{"v":9,"ve":9,"vl":"9","bn":"তোমাদের মধ্যে কি এমন কেউ আছে যে, তার ছেলে রুটি চাইলে তাকে পাথর দেবে?"},{"v":10,"ve":10,"vl":"10","bn":"কিংবা মাছ চাইলে সাপ দেবে?"},{"v":11,"ve":11,"vl":"11","bn":"তোমরা খারাপ হয়েও যদি নিজেদের ছেলেমেয়েদের ভাল ভাল জিনিস দিতে জান, তবে যারা তোমাদের বেহেশতী পিতার কাছে চায় তিনি যে তাদের ভাল ভাল জিনিস দেবেন এটা কত না নিশ্চয়!"},{"v":12,"ve":12,"vl":"12","bn":"তোমরা অন্য লোকদের কাছ থেকে যে রকম ব্যবহার পেতে চাও তোমরাও তাদের সংগে সেই রকম ব্যবহার কোরো। এটাই হল তৌরাত কিতাব ও নবীদের কিতাবের শিক্ষার মূল কথা।"},{"heading":"সরু ও চওড়া দরজা","v":13,"ve":13,"vl":"13","bn":"“সরু দরজা দিয়ে ঢোকো, কারণ যে পথ ধ্বংসের দিকে নিয়ে যায় তার দরজাও বড় এবং রাস্তাও চওড়া। অনেকেই তার মধ্য দিয়ে ঢোকে।"},{"v":14,"ve":14,"vl":"14","bn":"কিন্তু যে পথ জীবনের দিকে নিয়ে যায় তার দরজাও সরু, পথও সরু। খুব কম লোকই তা খুঁজে পায়।"},{"heading":"ভণ্ড নবীদের চিনবার উপায়","v":15,"ve":15,"vl":"15","bn":"“ভণ্ড নবীদের বিষয়ে সাবধান হও। তারা তোমাদের কাছে ভেড়ার চেহারায় আসে, অথচ ভিতরে তারা রাক্ষুসে নেকড়ে বাঘের মত।"},{"v":16,"ve":16,"vl":"16","bn":"তাদের জীবনে যে ফল দেখা যায় তা দিয়েই তোমরা তাদের চিনতে পারবে। কাঁটাঝোপে কি আংগুর ফল কিংবা শিয়ালকাঁটায় কি ডুমুর ফল ধরে?"},{"v":17,"ve":17,"vl":"17","bn":"ঠিক সেইভাবে প্রত্যেক ভাল গাছে ভাল ফলই ধরে আর খারাপ গাছে খারাপ ফলই ধরে।"},{"v":18,"ve":18,"vl":"18","bn":"ভাল গাছে খারাপ ফল এবং খারাপ গাছে ভাল ফল ধরতে পারে না।"},{"v":19,"ve":19,"vl":"19","bn":"যে গাছে ভাল ফল ধরে না তা কেটে আগুনে ফেলে দেওয়া হয়।"},{"v":20,"ve":20,"vl":"20","bn":"এইজন্য বলি, ভণ্ড নবীদের জীবনে যে ফল দেখা যায় তা দিয়েই তোমরা তাদের চিনতে পারবে।"},{"heading":"বেহেশতী রাজ্যে কে ঢুকতে পারবে?","v":21,"ve":21,"vl":"21","bn":"“যারা আমাকে ‘প্রভু, প্রভু’ বলে তারা প্রত্যেকে যে বেহেশতী রাজ্যে ঢুকতে পারবে তা নয়, কিন্তু আমার বেহেশতী পিতার ইচ্ছা যে পালন করে সে-ই ঢুকতে পারবে।"},{"v":22,"ve":22,"vl":"22","bn":"সেই দিন অনেকে আমাকে বলবে, ‘প্রভু, প্রভু, তোমার নামে কি আমরা নবী হিসাবে কথা বলি নি? তোমার নামে কি ভূত ছাড়াই নি? তোমার নামে কি অনেক অলৌকিক চিহ্ন-কাজ করি নি?’"},{"v":23,"ve":23,"vl":"23","bn":"তখন আমি সোজাসুজিই তাদের বলব, ‘আমি তোমাদের চিনি না। দুষ্টের দল! আমার কাছ থেকে তোমরা দূর হও।’"},{"heading":"দুই রকম লোক","v":24,"ve":24,"vl":"24","bn":"“সেইজন্য বলি, যে কেউ আমার এই সমস্ত কথা শুনে তা পালন করে সে এমন একজন বুদ্ধিমান লোকের মত, যে পাথরের উপরে তার ঘর তৈরী করল।"},{"v":25,"ve":25,"vl":"25","bn":"পরে বৃষ্টি নামল, বন্যা আসল, ঝড় বইল এবং সেই ঘরের উপরে আঘাত করল; কিন্তু সেই ঘরটা পড়ল না কারণ তা পাথরের উপরে তৈরী করা হয়েছিল।"},{"v":26,"ve":26,"vl":"26","bn":"যে কেউ আমার এই সমস্ত কথা শুনে তা পালন না করে সে এমন একজন মূর্খ লোকের মত, যে বালির উপরে তার ঘর তৈরী করল।"},{"v":27,"ve":27,"vl":"27","bn":"পরে বৃষ্টি নামল, বন্যা আসল, ঝড় বইল এবং সেই ঘরের উপরে আঘাত করল; তাতে ঘরটা পড়ে গেল। কি ভীষণ ভাবেই না সেই ঘরটা পড়ে গেল!”"},{"v":28,"ve":28,"vl":"28","bn":"ঈসা যখন কথা বলা শেষ করলেন তখন লোকেরা তাঁর শিক্ষায় আশ্চর্য হয়ে গেল,"},{"v":29,"ve":29,"vl":"29","bn":"কারণ তিনি আলেমদের মত শিক্ষা দিচ্ছিলেন না, বরং যাঁর অধিকার আছে সেই রকম লোকের মতই শিক্ষা দিচ্ছিলেন।"}],"8":[{"heading":"একজন চর্মরোগী সুস্থ হল","v":1,"ve":1,"vl":"1","bn":"ঈসা যখন পাহাড় থেকে নেমে আসলেন তখন অনেক লোক তাঁর পিছনে পিছনে চলল।"},{"v":2,"ve":2,"vl":"2","bn":"সেই সময় একজন চর্মরোগী এসে তাঁর সামনে উবুড় হয়ে বলল, “হুজুর, আপনি ইচ্ছা করলেই আমাকে ভাল করতে পারেন।”"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা হাত বাড়িয়ে তাকে ছুঁয়ে বললেন, “আমি তা-ই চাই, তুমি পাক-সাফ হও।” তখনই লোকটির চর্মরোগ ভাল হয়ে গেল।"},{"v":4,"ve":4,"vl":"4","bn":"ঈসা তাকে বললেন, “দেখ, কাউকে এই কথা বোলো না, বরং ইমামের কাছে গিয়ে নিজেকে দেখাও, আর নবী মূসা যা হুকুম দিয়েছেন সেই মত দান কোরবানী দাও। এতে লোকদের কাছে প্রমাণ হবে তুমি ভাল হয়েছ।”"},{"heading":"সেনাপতির গোলাম সুস্থ হল","v":5,"ve":5,"vl":"5","bn":"পরে ঈসা কফরনাহূম শহরে ঢুকলেন। তখন একজন রোমীয় শত-সেনাপতি তাঁর কাছে এসে অনুরোধ করে বললেন,"},{"v":6,"ve":6,"vl":"6","bn":"“হুজুর, আমার গোলাম ঘরে বিছানায় পড়ে আছে। সে অবশ-রোগে ভীষণ কষ্ট পাচ্ছে।”"},{"v":7,"ve":7,"vl":"7","bn":"ঈসা তাঁকে বললেন, “আমি গিয়ে তাকে ভাল করব।”"},{"v":8,"ve":8,"vl":"8","bn":"সেই সেনাপতি তাঁকে বললেন, “হুজুর, আপনি যে আমার বাড়ীতে ঢোকেন এমন যোগ্য আমি নই। কেবল মুুখে বলুন, তাতেই আমার গোলাম ভাল হয়ে যাবে।"},{"v":9,"ve":9,"vl":"9","bn":"আমি এই কথা জানি কারণ আমাকেও অন্যের কথামত চলতে হয় এবং সৈন্যেরা আমার কথামত চলে। আমি একজনকে ‘যাও’ বললে সে যায়, অন্যজনকে ‘এস’ বললে সে আসে। আমার গোলামকে ‘এটা কর’ বললে সে তা করে।”"},{"v":10,"ve":10,"vl":"10","bn":"ঈসা এই কথা শুনে আশ্চর্য হলেন এবং যারা তাঁর পিছনে পিছনে যাচ্ছিল তাদের বললেন, “আমি আপনাদের সত্যিই বলছি, বনি-ইসরাইলদের মধ্যেও এত বড় ঈমান কারও মধ্যে আমি দেখি নি।"},{"v":11,"ve":11,"vl":"11","bn":"আমি আপনাদের বলছি যে, পূর্ব ও পশ্চিম থেকে অনেকে আসবে এবং ইব্রাহিম, ইসহাক ও ইয়াকুবের সংগে বেহেশতী রাজ্যে খেতে বসবে।"},{"v":12,"ve":12,"vl":"12","bn":"কিন্তু যাদের বেহেশতী রাজ্যে থাকবার কথা তাদের বাইরের অন্ধকারে ফেলে দেওয়া হবে। সেখানে লোকেরা কান্নাকাটি করবে ও যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবে।”"},{"v":13,"ve":13,"vl":"13","bn":"পরে ঈসা সেই সেনাপতিকে বললেন, “আপনি যান। আপনি যেমন বিশ্বাস করেছেন তেমনই হোক।” ঠিক তখনই তাঁর গোলাম ভাল হয়ে গেল।"},{"heading":"আরও অনেকে সুস্থ হল","v":14,"ve":14,"vl":"14","bn":"এর পরে ঈসা পিতরের বাড়ীতে গিয়ে দেখলেন, পিতরের শাশুড়ীর জ্বর হয়েছে এবং তিনি শুয়ে আছেন।"},{"v":15,"ve":15,"vl":"15","bn":"ঈসা তাঁর হাত ছুঁলেন আর তাতে তাঁর জ্বর ছেড়ে গেল। তখন তিনি উঠে ঈসার খাওয়া-দাওয়ার ব্যবস্থা করতে লাগলেন।"},{"v":16,"ve":16,"vl":"16","bn":"সন্ধ্যা হলে পর লোকেরা ভূতে পাওয়া অনেককে ঈসার কাছে নিয়ে আসল। তিনি মুখের কথাতেই সেই ভূতদের ছাড়ালেন আর যারা অসুস্থ ছিল তাদের সবাইকে সুস্থ করলেন।"},{"v":17,"ve":17,"vl":"17","bn":"এই সব ঘটল যাতে নবী ইশাইয়ার মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হয়: তিনি আমাদের সমস্ত দুর্বলতা তুলে নিলেন, আর আমাদের রোগ দূর করলেন।"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা নিজের চারদিকে অনেক লোকের ভিড় দেখে সাহাবীদের সাগরের অন্য পারে যাবার হুকুম দিলেন।"},{"v":19,"ve":19,"vl":"19","bn":"একজন আলেম তখন ঈসার কাছে এসে বললেন, “হুজুর, আপনি যেখানে যাবেন আমিও আপনার সংগে সেখানে যাব।”"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা তাঁকে বললেন, “শিয়ালের গর্ত আছে এবং পাখীর বাসা আছে, কিন্তু ইব্‌ন্তেআদমের মাথা রাখবার জায়গা কোথাও নেই।”"},{"v":21,"ve":21,"vl":"21","bn":"সাহাবীদের মধ্যে আর একজন এসে তাঁকে বললেন, “হুজুর, আগে আমার বাবাকে দাফন করে আসতে দিন।”"},{"v":22,"ve":22,"vl":"22","bn":"ঈসা তাঁকে বললেন, “মৃতেরাই তাদের মৃতদের দাফন করুক, কিন্তু তুমি আমার সংগে এস।”"},{"heading":"ঝড় থামানো","v":23,"ve":23,"vl":"23","bn":"পরে ঈসা একটা নৌকাতে উঠলেন এবং তাঁর সাহাবীরা তাঁর সংগে গেলেন।"},{"v":24,"ve":24,"vl":"24","bn":"হঠাৎ সাগরে ভীষণ ঝড় উঠল, আর তাতে নৌকার উপর ঢেউ আছড়ে পড়তে লাগল। ঈসা কিন্তু ঘুমাচ্ছিলেন।"},{"v":25,"ve":25,"vl":"25","bn":"তখন সাহাবীরা তাঁর কাছে গিয়ে তাঁকে জাগিয়ে বললেন, “হুজুর, বাঁচান; আমরা যে মরলাম!”"},{"v":26,"ve":26,"vl":"26","bn":"তখন তিনি তাঁদের বললেন, “অল্প বিশ্বাসীরা, কেন তোমরা ভয় পাচ্ছ?” এর পরে তিনি উঠে বাতাস ও সাগরকে ধমক দিলেন। তখন সব কিছু খুব শান্ত হয়ে গেল।"},{"v":27,"ve":27,"vl":"27","bn":"এতে সাহাবীরা আশ্চর্য হয়ে বললেন, “ইনি কি রকম লোক যে, বাতাস এবং সাগরও তাঁর কথা শোনে!”"},{"heading":"ভূতে পাওয়া লোকেরা সুস্থ হল","v":28,"ve":28,"vl":"28","bn":"পরে ঈসা সাগরের অন্য পারে গাদারীয়দের এলাকায় গেলেন। তখন ভূতে পাওয়া দু’জন লোক কবরস্থান থেকে বের হয়ে তাঁর কাছে আসল।"},{"v":29,"ve":29,"vl":"29","bn":"তারা এমন ভয়ঙ্কর ছিল যে, কেউই সেই পথ দিয়ে যেতে পারত না। তারা চিৎকার করে বলল, “হে ইব্‌নুল্লাহ্‌, আমাদের সংগে আপনার কি দরকার? সময় না হতেই কি আপনি আমাদের যন্ত্রণা দিতে এখানে এসেছেন?”"},{"v":30,"ve":30,"vl":"30","bn":"তাদের কাছ থেকে বেশ কিছু দূরে খুব বড় এক পাল শূকর চরে বেড়াচ্ছিল।"},{"v":31,"ve":31,"vl":"31","bn":"ভূতেরা ঈসাকে অনুরোধ করে বলল, “আপনি যদি আমাদের দূর করেই দিতে চান তবে ঐ শূকরের পালের মধ্যেই পাঠিয়ে দিন।”"},{"v":32,"ve":32,"vl":"32","bn":"ঈসা তাদের বললেন, “তা-ই যাও।” তখন তারা বের হয়ে শূকরগুলোর মধ্যে গেল। তাতে সেই শূকরের পাল ঢালু পার দিয়ে জোরে দৌড়ে গেল এবং সাগরের পানিতে ডুবে মরল।"},{"v":33,"ve":33,"vl":"33","bn":"যারা সেই পাল চরাচ্ছিল তারা তখন দৌড়ে গ্রামে গিয়ে সব খবর জানাল। বিশেষ করে সেই ভূতে পাওয়া লোকদের বিষয়ে তারা সবাইকে বলল।"},{"v":34,"ve":34,"vl":"34","bn":"তখন গ্রামের সব লোক বের হয়ে ঈসার সংগে দেখা করতে গেল। তাঁর সংগে দেখা হলে পর তারা তাঁকে অনুরোধ করল যেন তিনি তাদের এলাকা ছেড়ে চলে যান।"}],"9":[{"heading":"অবশ-রোগী সুস্থ হল","v":1,"ve":1,"vl":"1","bn":"পরে ঈসা নৌকায় উঠে সাগর পার হয়ে নিজের শহরে আসলেন।"},{"v":2,"ve":2,"vl":"2","bn":"লোকেরা তখন বিছানায় পড়ে থাকা একজন অবশ-রোগীকে তাঁর কাছে আনল। সেই লোকদের বিশ্বাস দেখে ঈসা সেই রোগীকে বললেন, “সাহস কর। তোমার গুনাহ্‌ মাফ করা হল।”"},{"v":3,"ve":3,"vl":"3","bn":"এতে কয়েকজন আলেম মনে মনে বলতে লাগলেন, “এই লোকটা কুফরী করছে।”"},{"v":4,"ve":4,"vl":"4","bn":"ঈসা তাঁদের মনের চিন্তা জেনে বললেন, “আপনারা মনে মনে খারাপ চিন্তা করছেন কেন?"},{"v":5,"ve":5,"vl":"5","bn":"কোন্‌টা বলা সহজ, ‘তোমার গুনাহ্‌ মাফ করা হল,’ না ‘তুমি উঠে হেঁটে বেড়াও’?"},{"v":6,"ve":6,"vl":"6","bn":"আপনারা যেন জানতে পারেন এই দুনিয়াতে গুনাহ্‌ মাফ করবার ক্ষমতা ইব্‌ন্তেআদমের আছে”- এই পর্যন্ত বলে তিনি সেই অবশ-রোগীকে বললেন, “ওঠো, তোমার বিছানা তুলে নিয়ে বাড়ী যাও।”"},{"v":7,"ve":7,"vl":"7","bn":"তখন সে উঠে তার বাড়ীতে চলে গেল।"},{"v":8,"ve":8,"vl":"8","bn":"লোকে এই ঘটনা দেখে ভয় পেল, আর আল্লাহ্‌ মানুষকে এমন ক্ষমতা দিয়েছেন বলে আল্লাহ্‌র প্রশংসা করতে লাগল।"},{"heading":"হযরত মথিকে আহ্বান","v":9,"ve":9,"vl":"9","bn":"ঈসা যখন সেখান থেকে চলে যাচ্ছিলেন তখন পথে মথি নামে একজন লোককে খাজনা আদায় করবার ঘরে বসে থাকতে দেখলেন। ঈসা তাঁকে বললেন, “এস, আমার উম্মত হও।” মথি তখনই উঠে তাঁর সংগে গেলেন।"},{"v":10,"ve":10,"vl":"10","bn":"এর পরে ঈসা মথির বাড়ীতে খেতে বসলেন। তখন অনেক খাজনা-আদায়কারী ও খারাপ লোক এসে ঈসা ও তাঁর সাহাবীদের সংগে খেতে বসল।"},{"v":11,"ve":11,"vl":"11","bn":"তা দেখে ফরীশীরা ঈসার সাহাবীদের বললেন, “তোমাদের ওস্তাদ খাজনা-আদায়কারী ও খারাপ লোকদের সংগে খাওয়া-দাওয়া করেন কেন?”"},{"v":12,"ve":12,"vl":"12","bn":"এই কথা শুনে ঈসা বললেন, “যারা সুস্থ আছে তাদের জন্য ডাক্তারের দরকার নেই, বরং অসুস্থদের জন্যই দরকার আছে।"},{"v":13,"ve":13,"vl":"13","bn":"‘আমি দয়া দেখতে চাই, পশু-কোরবানী নয়’- পাক-কিতাবের এই কথার মানে কি, তা গিয়ে খুঁজে বের করুন। যারা ধার্মিক তাদের আমি ডাকতে আসি নি, বরং গুনাহ্‌গারদেরই ডাকতে এসেছি।”"},{"heading":"রোজার বিষয়ে আরও শিক্ষা","v":14,"ve":14,"vl":"14","bn":"পরে ইয়াহিয়ার সাহাবীরা ঈসার কাছে এসে বললেন, “আমরা ও ফরীশীরা এত রোজা রাখি, কিন্তু আপনার সাহাবীরা রোজা রাখেন না কেন?”"},{"v":15,"ve":15,"vl":"15","bn":"ঈসা তাঁদের বললেন, “বর সংগে থাকতে কি বরের সংগের লোকেরা দুঃখ প্রকাশ করতে পারে? কিন্তু সময় আসছে যখন বরকে তাদের কাছ থেকে নিয়ে যাওয়া হবে। সেই সময় তারা রোজা রাখবে।"},{"v":16,"ve":16,"vl":"16","bn":"“কেউ পুরানো কোর্তাতে নতুন কাপড়ের তালি দেয় না, কারণ পরে সেই পুরানো কাপড় থেকে নতুন তালিটা ছিঁড়ে আসে আর তাতে সেই ছেঁড়াটা আরও বড় হয়।"},{"v":17,"ve":17,"vl":"17","bn":"পুরানো চামড়ার থলিতে কেউ টাটকা আংগুর-রস রাখে না। রাখলে থলিগুলো ফেটে গিয়ে সেই রস পড়ে যায় আর থলিগুলোও নষ্ট হয়। লোকে নতুন চামড়ার থলিতেই টাটকা আংগুর-রস রাখে; তাতে দু’টাই রক্ষা পায়।”"},{"heading":"একটি মৃত বালিকা ও একজন অসুস্থ স্ত্রীলোক","v":18,"ve":18,"vl":"18","bn":"ঈসা লোকদের যখন এই সব কথা বলছিলেন তখন একজন ইহুদী নেতা তাঁর কাছে আসলেন এবং তাঁর সামনে উবুড় হয়ে বললেন, “আমার মেয়েটা এইমাত্র মারা গেছে। কিন্তু আপনি এসে তার উপর হাত রাখুন, তাতে সে বেঁচে উঠবে।”"},{"v":19,"ve":19,"vl":"19","bn":"তখন ঈসা ও তাঁর সাহাবীরা উঠে তাঁর সংগে গেলেন।"},{"v":20,"ve":20,"vl":"20","bn":"সেই সময় একজন স্ত্রীলোক পিছন থেকে ঈসার কাছে এসে তাঁর চাদরের কিনারা ছুঁলো। স্ত্রীলোকটি বারো বছর ধরে রক্তস্রাব রোগে ভুগছিল।"},{"v":21,"ve":21,"vl":"21","bn":"সে মনে মনে ভাবছিল, যদি সে কেবল তাঁর কাপড়টা ছুঁতে পারে তাহলেই ভাল হয়ে যাবে।"},{"v":22,"ve":22,"vl":"22","bn":"ঈসা ফিরে তাকে দেখতে পেয়ে বললেন, “সাহস কর। তুমি বিশ্বাস করেছ বলে ভাল হয়েছ।” সেই সময় থেকেই স্ত্রীলোকটি সুস্থ হল।"},{"v":23,"ve":23,"vl":"23","bn":"এর পরে ঈসা সেই ইহুদী নেতার বাড়ীতে গেলেন। সেখানে তিনি দেখলেন, যারা বাঁশী বাজায় তারা রয়েছে এবং লোকেরা হৈচৈ করছে।"},{"v":24,"ve":24,"vl":"24","bn":"এতে ঈসা বললেন, “তোমরা বাইরে যাও। মেয়েটি মারা যায় নি, ঘুমাচ্ছে।” এই কথা শুনে তারা হাসাহাসি করতে লাগল।"},{"v":25,"ve":25,"vl":"25","bn":"লোকদের বের করে দেওয়া হলে পর তিনি ভিতরে গিয়ে মেয়েটির হাত ধরলেন। তাতে সে উঠে বসল।"},{"v":26,"ve":26,"vl":"26","bn":"এই ঘটনার কথা সেই এলাকার সব জায়গায় ছড়িয়ে পড়ল।"},{"heading":"অন্ধ ও বোবা সুস্থ হল","v":27,"ve":27,"vl":"27","bn":"ঈসা সেই জায়গা ছেড়ে চলে যাবার সময় দু’জন অন্ধ লোক তাঁর পিছনে পিছনে চলল। তারা চিৎকার করে বলতে লাগল, “দাউদের বংশধর, আমাদের দয়া করুন।”"},{"v":28,"ve":28,"vl":"28","bn":"ঈসা ঘরে ঢুকলে পর সেই অন্ধ লোকেরা তাঁর কাছে আসল। তখন তিনি তাদের বললেন, “তোমরা কি বিশ্বাস কর যে, আমি এই কাজ করতে পারি?” তারা বলল, “জ্বী হুজুর, করি।”"},{"v":29,"ve":29,"vl":"29","bn":"তিনি তাদের চোখ ছুঁয়ে বললেন, “তোমরা যেমন বিশ্বাস করেছ তোমাদের প্রতি তেমনই হোক।”"},{"v":30,"ve":30,"vl":"30","bn":"আর তখনই তাদের চোখ খুলে গেল। ঈসা খুব কঠোরভাবে তাদের বললেন, “দেখো, কেউ যেন জানতে না পারে।”"},{"v":31,"ve":31,"vl":"31","bn":"কিন্তু তারা বাইরে গিয়ে সেই এলাকার সমস্ত জায়গায় ঈসার খবর ছড়িয়ে দিল।"},{"v":32,"ve":32,"vl":"32","bn":"সেই দু’জন লোক যখন চলে যাচ্ছিল তখন লোকেরা ভূতে পাওয়া একজন বোবা লোককে ঈসার কাছে আনল।"},{"v":33,"ve":33,"vl":"33","bn":"ঈসা সেই ভূতকে ছাড়াবার পর লোকটা কথা বলতে লাগল। তাতে সবাই আশ্চর্য হয়ে বলল, “ইসরাইল দেশে আর কখনও এই রকম দেখা যায় নি।”"},{"v":34,"ve":34,"vl":"34","bn":"তখন ফরীশীরা বললেন, “সে ভূতদের বাদশাহ্‌র সাহায্যে ভূত ছাড়ায়।”"},{"heading":"লোকদের প্রতি হযরত ঈসা মসীহের মমতা","v":35,"ve":35,"vl":"35","bn":"ঈসা শহরে শহরে ও গ্রামে গ্রামে গিয়ে ইহুদীদের মজলিস-খানায় শিক্ষা দিতে ও বেহেশতী রাজ্যের সুসংবাদ তবলিগ করতে লাগলেন। এছাড়া তিনি লোকদের সব রকম রোগও ভাল করলেন।"},{"v":36,"ve":36,"vl":"36","bn":"লোকদের ভিড় দেখে তাদের জন্য ঈসার মমতা হল, কারণ তারা রাখালহীন ভেড়ার মত ক্লান্ত ও অসহায় ছিল।"},{"v":37,"ve":37,"vl":"37","bn":"তখন ঈসা তাঁর সাহাবীদের বললেন, “ফসল সত্যিই অনেক কিন্তু কাজ করবার লোক কম।"},{"v":38,"ve":38,"vl":"38","bn":"সেইজন্য ফসলের মালিকের কাছে অনুরোধ কর যেন তিনি তাঁর ফসল কাটবার জন্য লোক পাঠিয়ে দেন।”"}],"10":[{"heading":"বারোজন সাহাবীকে পাঠানো","v":1,"ve":1,"vl":"1","bn":"ঈসা তাঁর বারোজন সাহাবীকে ডাকলেন এবং ভূত ছাড়াবার ও সব রকম রোগ ভাল করবার ক্ষমতা দিয়ে তাঁদের পাঠিয়ে দিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"সেই বারোজন প্রেরিতের নাম এই: প্রথম, শিমোন যাঁকে পিতর বলা হয়, তারপর তাঁর ভাই আন্দ্রিয়; সিবদিয়ের ছেলে ইয়াকুব ও তাঁর ভাই ইউহোন্না; ফিলিপ ও বর্‌থলময়;"},{"v":3,"ve":3,"vl":"3","bn":"থোমা ও খাজনা-আদায়কারী মথি; আল্‌ফেয়ের ছেলে ইয়াকুব ও থদ্দেয়;"},{"v":4,"ve":4,"vl":"4","bn":"মৌলবাদী শিমোন এবং ঈসাকে যে শত্রুদের হাতে ধরিয়ে দিয়েছিল সেই এহুদা ইষ্কারিয়োৎ।"},{"v":5,"ve":5,"vl":"5","bn":"ঈসা সেই বারোজনকে এই সব হুকুম দিয়ে পাঠালেন, “তোমরা অ-ইহুদীদের কাছে বা সামেরীয়দের কোন গ্রামে যেয়ো না,"},{"v":6,"ve":6,"vl":"6","bn":"বরং ইসরাইল জাতির হারানো ভেড়াদের কাছে যেয়ো।"},{"v":7,"ve":7,"vl":"7","bn":"তোমরা যেতে যেতে এই কথা তবলিগ কোরো যে, বেহেশতী রাজ্য কাছে এসে গেছে।"},{"v":8,"ve":8,"vl":"8","bn":"এছাড়া তোমরা অসুস্থদের সুস্থ কোরো, মৃতদের জীবন দিয়ো, চর্মরোগীদের ভালো কোরো ও ভূতদের ছাড়ায়ো। তোমরা বিনামূল্যে পেয়েছ, বিনামূল্যেই দিয়ো।"},{"v":9,"ve":9,"vl":"9","bn":"তোমাদের কোমর-বাঁধনিতে তোমরা সোনা, রূপা কিংবা তামার পয়সাও নিয়ো না।"},{"v":10,"ve":10,"vl":"10","bn":"পথের জন্য কোন রকম থলি, দু’টা কোর্তা, জুতা বা লাঠিও নিয়ো না, কারণ যে কাজ করে সে খাওয়া-পরা পাবার যোগ্য।"},{"v":11,"ve":11,"vl":"11","bn":"“তোমরা যে কোন শহরে বা গ্রামে যাবে সেখানে একজন উপযুক্ত লোক খুঁজে নিয়ো এবং অন্য কোথাও চলে না যাওয়া পর্যন্ত তার বাড়ীতে থেকো।"},{"v":12,"ve":12,"vl":"12","bn":"সেই বাড়ীর ভিতরে ঢুকবার সময় তাদের সালাম জানায়ো।"},{"v":13,"ve":13,"vl":"13","bn":"যদি সেই বাড়ী উপযুক্ত হয় তবে তোমাদের শান্তি সেই বাড়ীর উপরে নেমে আসুক। কিন্তু যদি সেই বাড়ী উপযুক্ত না হয় তবে তোমাদের শান্তি তোমাদের কাছেই ফিরে আসুক।"},{"v":14,"ve":14,"vl":"14","bn":"যদি কেউ তোমাদের গ্রহণ না করে বা তোমাদের কথা না শোনে তবে সেই বাড়ী বা গ্রাম থেকে চলে যাবার সময়ে তোমাদের পায়ের ধুলা ঝেড়ে ফেলো।"},{"v":15,"ve":15,"vl":"15","bn":"আমি তোমাদের সত্যি বলছি, রোজ হাশরে সেই গ্রামের চেয়ে বরং সাদুম ও আমুরা শহরের অবস্থা অনেকখানি সহ্য করবার মত হবে।"},{"heading":"সাহাবীদের প্রতি উপদেশ","v":16,"ve":16,"vl":"16","bn":"“দেখ, আমি নেকড়ে বাঘের মধ্যে ভেড়ার মত তোমাদের পাঠাচ্ছি। এইজন্য সাপের মত সতর্ক এবং কবুতরের মত সরল হও।"},{"v":17,"ve":17,"vl":"17","bn":"সাবধান থেকো, কারণ মানুষ বিচার-সভার লোকদের হাতে তোমাদের ধরিয়ে দেবে এবং তাদের মজলিস-খানায় তোমাদের বেত মারবে।"},{"v":18,"ve":18,"vl":"18","bn":"আমার জন্যই শাসনকর্তা ও বাদশাহ্‌দের সামনে তোমাদের নিয়ে যাওয়া হবে যেন তাদের কাছে ও অ-ইহুদীদের কাছে তোমরা সাক্ষ্য দিতে পার।"},{"v":19,"ve":19,"vl":"19","bn":"লোকেরা যখন তোমাদের ধরিয়ে দেবে তখন কিভাবে এবং কি বলতে হবে তা ভেবো না। কি বলতে হবে তা তোমাদের সেই সময়েই বলে দেওয়া হবে।"},{"v":20,"ve":20,"vl":"20","bn":"তোমরাই যে বলবে তা নয়, বরং তোমাদের পিতার রূহ্‌ তোমাদের মধ্য দিয়ে কথা বলবেন।"},{"v":21,"ve":21,"vl":"21","bn":"“ভাই ভাইকে এবং বাবা ছেলেকে হত্যা করবার জন্য ধরিয়ে দেবে। ছেলেমেয়েরা মা-বাবার বিরুদ্ধে দাঁড়িয়ে তাদের খুন করাবে।"},{"v":22,"ve":22,"vl":"22","bn":"আমার জন্য সবাই তোমাদের ঘৃণা করবে, কিন্তু যে শেষ পর্যন্ত স্থির থাকবে সে উদ্ধার পাবে।"},{"v":23,"ve":23,"vl":"23","bn":"কোন গ্রামের লোকেরা যখন তোমাদের উপর জুলুম করবে তখন অন্য গ্রামে পালিয়ে যেয়ো। আমি তোমাদের সত্যিই বলছি, ইসরাইল দেশের সমস্ত শহর ও গ্রামে তোমাদের কাজ শেষ হবার আগেই ইব্‌ন্তেআদম আসবেন।"},{"v":24,"ve":24,"vl":"24","bn":"“শিক্ষক থেকে ছাত্র বড় নয় এবং মালিক থেকে গোলাম বড় নয়।"},{"v":25,"ve":25,"vl":"25","bn":"ছাত্রের পক্ষে শিক্ষকের মত হওয়া আর গোলামের পক্ষে মালিকের মত হওয়াই যথেষ্ট। ঘরের কর্তাকেই যখন তারা বেল্‌সবূল বলেছে তখন ঘরের অন্য সবাইকে আরও কত বেশী করেই না বেল্‌সবূল বলবে।"},{"v":26,"ve":26,"vl":"26","bn":"“তবে তোমরা তাদের ভয় কোরো না, কারণ লুকানো সব কিছুই প্রকাশ পাবে এবং গোপন সব কিছুই জানানো হবে।"},{"v":27,"ve":27,"vl":"27","bn":"আমি তোমাদের কাছে যা অন্ধকারে বলছি তা তোমরা আলোতে বোলো। তোমরা যা কান্তেকানে শুনছ তা ছাদের উপর থেকে প্রচার কোরো।"},{"v":28,"ve":28,"vl":"28","bn":"যারা কেবল শরীরটা মেরে ফেলতে পারে কিন্তু রূহ্‌কে মারতে পারে না তাদের ভয় কোরো না। যিনি শরীর ও রূহ্‌ দু’টাই জাহান্নামে ধ্বংস করতে পারেন বরং তাঁকেই ভয় কর।"},{"v":29,"ve":29,"vl":"29","bn":"দু’টা চড়াই পাখী কি সামান্য দামে বিক্রি হয় না? তবুও তোমাদের পিতার অনুমতি ছাড়া তাদের একটাও মাটিতে পড়ে না;"},{"v":30,"ve":30,"vl":"30","bn":"এমন কি, তোমাদের মাথার চুলগুলোও গোণা আছে।"},{"v":31,"ve":31,"vl":"31","bn":"কাজেই তোমরা ভয় পেয়ো না। অনেক অনেক চড়াই পাখীর চেয়েও তোমাদের মূল্য অনেক বেশী।"},{"v":32,"ve":32,"vl":"32","bn":"“যে কেউ মানুষের সামনে আমাকে স্বীকার করে আমিও আমার বেহেশতী পিতার সামনে তাকে স্বীকার করব।"},{"v":33,"ve":33,"vl":"33","bn":"কিন্তু যে কেউ মানুষের সামনে আমাকে অস্বীকার করে আমিও আমার বেহেশতী পিতার সামনে তাকে অস্বীকার করব।"},{"v":34,"ve":34,"vl":"34","bn":"“আমি দুনিয়াতে শান্তি দিতে এসেছি এই কথা মনে কোরো না। আমি শান্তি দিতে আসি নি বরং মানুষকে মানুষের বিরুদ্ধে দাঁড় করাতে এসেছি;"},{"v":35,"ve":35,"vl":"35","bn":"ছেলেকে বাবার বিরুদ্ধে, মেয়েকে মায়ের বিরুদ্ধে, স্ত্রীকে শাশুড়ীর বিরুদ্ধে দাঁড় করাতে এসেছি।"},{"v":36,"ve":36,"vl":"36","bn":"একজন মানুষের নিজের পরিবারের লোকেরাই তার শত্রু হবে।"},{"v":37,"ve":37,"vl":"37","bn":"“যে কেউ আমার চেয়ে পিতা-মাতাকে বেশী ভালবাসে সে আমার উপযুক্ত নয়। আর যে কেউ ছেলে বা মেয়েকে আমার চেয়ে বেশী ভালবাসে সে আমার উপযুক্ত নয়।"},{"v":38,"ve":38,"vl":"38","bn":"যে নিজের ক্রুশ নিয়ে আমার পথে না চলে সে-ও আমার উপযুক্ত নয়।"},{"v":39,"ve":39,"vl":"39","bn":"যে কেউ নিজের জীবন রক্ষা করতে চায় সে তার সত্যিকারের জীবন হারাবে; কিন্তু যে কেউ আমার জন্য তার প্রাণ হারায় সে তার সত্যিকারের জীবন রক্ষা করবে।"},{"v":40,"ve":40,"vl":"40","bn":"“যে তোমাদের গ্রহণ করে সে আমাকেই গ্রহণ করে; আর যে আমাকে গ্রহণ করে আমাকে যিনি পাঠিয়েছেন সে তাঁকেই গ্রহণ করে।"},{"v":41,"ve":41,"vl":"41","bn":"কোন নবীকে যদি কেউ নবী বলে গ্রহণ করে তবে নবী যে পুরস্কার পাবে সে-ও সেই পুরস্কার পাবে। একজন আল্লাহ্‌ভক্ত লোককে যদি কেউ আল্লাহ্‌ভক্ত লোক বলে গ্রহণ করে তবে আল্লাহ্‌ভক্ত লোক যে পুরস্কার পাবে সে-ও সেই পুরস্কার পাবে।"},{"v":42,"ve":42,"vl":"42","bn":"যে কেউ এই সামান্য লোকদের মধ্যে একজনকে আমার উম্মত বলে এক পেয়ালা ঠাণ্ডা পানি দেয়, আমি তোমাদের সত্যিই বলছি, সে কোনমতে তার পুরস্কার হারাবে না।”"}],"11":[{"heading":"হযরত ঈসা মসীহের কাছে হযরত ইয়াহিয়ার সাহাবীরা","v":1,"ve":1,"vl":"1","bn":"ঈসা তাঁর বারোজন সাহাবীকে হুকুম দেওয়া শেষ করলেন। তারপর তিনি গ্রামে গ্রামে শিক্ষা দেবার ও তবলিগ করবার জন্য সেখান থেকে চলে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"ইয়াহিয়া জেলখানায় থেকে যখন মসীহের কাজের কথা শুনলেন তখন তাঁর সাহাবীদের দিয়ে ঈসাকে জিজ্ঞাসা করে পাঠালেন,"},{"v":3,"ve":3,"vl":"3","bn":"“যাঁর আসবার কথা আছে আপনি কি তিনি, না আমরা আর কারও জন্য অপেক্ষা করব?”"},{"v":4,"ve":4,"vl":"4","bn":"জবাবে ঈসা তাদের বললেন, “তোমরা যা শুনছ এবং দেখছ তা গিয়ে ইয়াহিয়াকে বল।"},{"v":5,"ve":5,"vl":"5","bn":"তাঁকে জানাও যে, অন্ধেরা দেখছে, খোঁড়ারা হাঁটছে, চর্মরোগীরা পাক-সাফ হচ্ছে, বধির লোকেরা শুনছে, মৃতেরা বেঁচে উঠছে আর গরীব লোকদের কাছে সুসংবাদ তবলিগ করা হচ্ছে।"},{"v":6,"ve":6,"vl":"6","bn":"আর ধন্য সে-ই যে আমাকে নিয়ে মনে কোন বাধা না পায়।”"},{"heading":"হযরত ইয়াহিয়ার বিষয়ে হযরত ঈসা মসীহের কথা","v":7,"ve":7,"vl":"7","bn":"ইয়াহিয়ার সাহাবীরা চলে যাচ্ছে, এমন সময় ঈসা লোকদের কাছে ইয়াহিয়ার বিষয়ে বলতে শুরু করলেন, “আপনারা মরুভূমিতে কি দেখতে গিয়েছিলেন? বাতাসে দোলা নল-খাগড়া?"},{"v":8,"ve":8,"vl":"8","bn":"তা না হলে কি দেখতে গিয়েছিলেন? সুন্দর কাপড় পরা কোন লোককে দেখতে কি? আসলে যারা সুন্দর কাপড় পরে তারা বাদশাহ্‌র বাড়ীতে থাকে।"},{"v":9,"ve":9,"vl":"9","bn":"তা না হলে কি দেখতে গিয়েছিলেন? কোন নবীকে কি? জ্বী, আমি আপনাদের বলছি, তিনি নবীর চেয়েও বড়।"},{"v":10,"ve":10,"vl":"10","bn":"ইয়াহিয়াই সেই লোক যাঁর বিষয়ে কিতাবে লেখা আছে: দেখ, আমি তোমার আগে আমার সংবাদদাতাকে পাঠাচ্ছি। সে তোমার আগে গিয়ে তোমার পথ প্রস্তুত করবে।"},{"v":11,"ve":11,"vl":"11","bn":"আমি আপনাদের সত্যিই বলছি, মানুষের মধ্যে তরিকাবন্দীদাতা ইয়াহিয়ার চেয়ে বড় আর কেউ নেই। কিন্তু বেহেশতী রাজ্যের মধ্যে যে সকলের চেয়ে ছোট সে-ও ইয়াহিয়ার চেয়ে মহান।"},{"v":12,"ve":12,"vl":"12","bn":"ইয়াহিয়ার সময় থেকে এখন পর্যন্ত বেহেশতী রাজ্য খুব জোরের সংগে এগিয়ে আসছে, আর যারা শক্তিশালী তারা তা আঁকড়ে ধরছে।"},{"v":13,"ve":13,"vl":"13","bn":"ইয়াহিয়ার সময় পর্যন্ত নবীদের সমস্ত কিতাব, এমন কি, তৌরাত কিতাবও ভবিষ্যতের কথা বলেছে।"},{"v":14,"ve":14,"vl":"14","bn":"যদি আপনারা এই কথা বিশ্বাস করতে রাজী থাকেন তবে শুনুন্ত যাঁর আসবার কথা ছিল এই ইয়াহিয়াই সেই নবী ইলিয়াস।"},{"v":15,"ve":15,"vl":"15","bn":"যার শুনবার কান আছে সে শুনুক।”"},{"v":16,"ve":16,"vl":"16","bn":"“এই কালের লোকদের আমি কাদের সংগে তুলনা করব? এরা এমন ছেলেমেয়েদের মত যারা বাজারে বসে অন্য ছেলেমেয়েদের ডেকে বলে,"},{"v":17,"ve":17,"vl":"17","bn":"‘আমরা তোমাদের জন্য বাঁশী বাজালাম, তোমরা নাচলে না; বিলাপের গান গাইলাম, তোমরা বুক চাপড়ালে না।’"},{"v":18,"ve":18,"vl":"18","bn":"ইয়াহিয়া এসে খাওয়া-দাওয়া করলেন না বলে লোকে বলছে, ‘তাকে ভূতে পেয়েছে।’"},{"v":19,"ve":19,"vl":"19","bn":"আর ইব্‌ন্তেআদম এসে খাওয়া-দাওয়া করলেন বলে লোকে বলছে, ‘ঐ দেখ, একজন পেটুক ও মদখোর, খাজনা-আদায়কারী ও খারাপ লোকদের বন্ধু।’ কিন্তু জ্ঞান যে খাঁটি তার প্রমাণ তার কাজের মধ্যেই রয়েছে।”"},{"heading":"বেঈমান গ্রাম ও শহরগুলো","v":20,"ve":20,"vl":"20","bn":"ঈসা যে সব গ্রামে ও শহরে বেশীর ভাগ অলৌকিক চিহ্ন-কাজ করেছিলেন সেই সব জায়গার লোকেরা তওবা করে নি। এইজন্য সেই জায়গাগুলোকে তিনি ধিক্কার দিয়ে বলতে লাগলেন,"},{"v":21,"ve":21,"vl":"21","bn":"“ঘৃণ্য কোরাসীন, ঘৃণ্য বৈৎসৈদা! তোমাদের মধ্যে যে সব অলৌকিক চিহ্ন-কাজ করা হয়েছে সেগুলো যদি টায়ার ও সিডন শহরে করা হত তবে অনেক দিন আগেই তারা চট পরে ছাই মেখে তওবা করত।"},{"v":22,"ve":22,"vl":"22","bn":"আমি তোমাদের সত্যিই বলছি, রোজ হাশরে টায়ার ও সিডনের অবস্থা বরং তোমাদের চেয়ে অনেকখানি সহ্য করবার মত হবে।"},{"v":23,"ve":23,"vl":"23","bn":"আর তুমি কফরনাহূম! তুমি নাকি বেহেশত পর্যন্ত উঁচুতে উঠবে? কখনও না, তোমাকে নীচে কবরে ফেলে দেওয়া হবে। যে সব অলৌকিক চিহ্ন-কাজ তোমার মধ্যে করা হয়েছে তা যদি সাদুম শহরে করা হত তবে সাদুম আজও টিকে থাকত।"},{"v":24,"ve":24,"vl":"24","bn":"আমি তোমাদের সত্যিই বলছি, রোজ হাশরে সাদুমের অবস্থা বরং তোমাদের চেয়ে অনেকখানি সহ্য করবার মত হবে।”"},{"heading":"হযরত ঈসা মসীহের আহ্বান","v":25,"ve":25,"vl":"25","bn":"তারপর ঈসা বললেন, “হে পিতা, তুমি বেহেশত ও দুনিয়ার মালিক। আমি তোমার প্রশংসা করি, কারণ তুমি এই সব বিষয় জ্ঞানী ও বুদ্ধিমানদের কাছ থেকে লুকিয়ে রেখেছ, কিন্তু শিশুর মত লোকদের কাছে প্রকাশ করেছ।"},{"v":26,"ve":26,"vl":"26","bn":"জ্বী পিতা, তোমার ইচ্ছামতই এটা হয়েছে।"},{"v":27,"ve":27,"vl":"27","bn":"“আমার পিতা সব কিছুই আমার হাতে দিয়েছেন। পিতা ছাড়া পুত্রকে কেউ জানে না এবং পুত্র ছাড়া পিতাকে কেউ জানে না, আর পুত্র যার কাছে পিতাকে প্রকাশ করতে ইচ্ছা করেন সে-ই তাঁকে জানে।"},{"v":28,"ve":28,"vl":"28","bn":"“তোমরা যারা ক্লান্ত ও বোঝা বয়ে বেড়া\"ছ, তোমরা সবাই আমার কাছে এস; আমি তোমাদের বিশ্রাম দেব।"},{"v":29,"ve":29,"vl":"29","bn":"আমার জোয়াল তোমাদের উপর তুলে নাও ও আমার কাছ থেকে শেখো, কারণ আমার স্বভাব নরম ও নম্র।"},{"v":30,"ve":30,"vl":"30","bn":"এতে তোমরা দিলে বিশ্রাম পাবে, কারণ আমার জোয়াল বয়ে নেওয়া সহজ ও আমার বোঝা হালকা।”"}],"12":[{"heading":"ইব্‌ন্তেআদমই বিশ্রামবারের মালিক","v":1,"ve":1,"vl":"1","bn":"একদিন ঈসা একটা শস্যক্ষেতের মধ্য দিয়ে যাচ্ছিলেন। সেই দিনটা বিশ্রামবার ছিল। তাঁর সাহাবীদের খিদে পেয়েছিল বলে তাঁরা শীষ ছিঁড়ে ছিঁড়ে খেতে লাগলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তা দেখে ফরীশীরা তাঁকে বললেন, “শরীয়ত মতে বিশ্রামবারে যা করা উচিত নয়, দেখুন, আপনার সাহাবীরা তা-ই করছে।”"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা তাঁদের বললেন, “দাউদ ও তাঁর সংগীদের যখন খিদে পেয়েছিল তখন তিনি কি করেছিলেন তা কি আপনারা পড়েন নি? তিনি তো আল্লাহ্‌র ঘরে ঢুকে পবিত্র-রুটি খেয়েছিলেন।"},{"v":4,"ve":4,"vl":"4","bn":"নবী দাউদ ও তাঁর সংগীদের অবশ্য তা খাওয়া উচিত ছিল না, কেবল ইমামেরাই তা খেতে পারতেন।"},{"v":5,"ve":5,"vl":"5","bn":"এছাড়া আপনারা কি তৌরাত শরীফে পড়েন নি যে, বিশ্রামবারে বায়তুল-মোকাদ্দসের ইমামেরা বিশ্রামবারের নিয়ম ভাংলেও তাঁদের দোষ হয় না?"},{"v":6,"ve":6,"vl":"6","bn":"আমি আপনাদের বলছি, বায়তুল-মোকাদ্দস থেকেও বড় একজন এখানে আছেন।"},{"v":7,"ve":7,"vl":"7","bn":"‘আমি দয়া দেখতে চাই, পশু-কোরবানী নয়’- কিতাবের এই কথার অর্থ যদি আপনারা জানতেন তবে নির্দোষীদের দোষী করতেন না।"},{"v":8,"ve":8,"vl":"8","bn":"জেনে রাখুন, ইব্‌ন্তেআদমই বিশ্রামবারের মালিক।”"},{"heading":"শুকনা-হাত লোকটি সুস্থ হল","v":9,"ve":9,"vl":"9","bn":"পরে সেই জায়গা ছেড়ে ঈসা সেই ফরীশীদের মজলিস-খানায় গেলেন।"},{"v":10,"ve":10,"vl":"10","bn":"সেখানে একজন লোক ছিল যার একটা হাত শুকিয়ে গিয়েছিল। ঈসাকে দোষী করবার উদ্দেশ্যে ফরীশীরা তাঁকে জিজ্ঞাসা করলেন, “শরীয়ত মতে বিশ্রামবারে কি কাউকে সুস্থ করা উচিত?”"},{"v":11,"ve":11,"vl":"11","bn":"ঈসা তাঁদের বললেন, “ধরুন, আপনাদের মধ্যে কারও একটা ভেড়া আছে। সেই ভেড়াটা যদি বিশ্রামবারে গর্তে পড়ে যায় তবে কি তিনি তাকে ধরে তুলবেন না?"},{"v":12,"ve":12,"vl":"12","bn":"আর ভেড়ার চেয়ে মানুষের দাম তো অনেক বেশী। তাহলে দেখা যায়, বিশ্রামবারে ভাল কাজ করা উচিত।”"},{"v":13,"ve":13,"vl":"13","bn":"তারপর তিনি লোকটিকে বললেন, “তোমার হাত বাড়িয়ে দাও।” সে তার হাতটা বাড়িয়ে দিলে পর সেটা ভাল হয়ে অন্য হাতটার মত হয়ে গেল।"},{"v":14,"ve":14,"vl":"14","bn":"তখন ফরীশীরা বাইরে গেলেন এবং ঈসাকে হত্যা করবার জন্য তাঁর বিরুদ্ধে পরামর্শ করতে লাগলেন।"},{"heading":"আল্লাহ্‌র বাছাই করা বান্দা","v":15,"ve":15,"vl":"15","bn":"সেই পরামর্শের বিষয় জানতে পেরে ঈসা সেখান থেকে চলে গেলেন। তখন অনেক লোক তাঁর পিছনে পিছনে গেল।"},{"v":16,"ve":16,"vl":"16","bn":"তাদের মধ্যে যারা অসুস্থ ছিল তিনি তাদের সবাইকে সুস্থ করলেন এবং সাবধান করে দিলেন যেন তাঁর বিষয়ে তারা বলাবলি না করে।"},{"v":17,"ve":17,"vl":"17","bn":"এটা হল যাতে নবী ইশাইয়ার মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হয়:"},{"v":18,"ve":18,"vl":"18","bn":"দেখ, আমার গোলাম যাঁকে আমি বেছে নিয়েছি। ইনিই আমার প্রিয়জন যাঁর উপর আমি সন্তুষ্ট। আমি তাঁর উপরে আমার রূহ্‌ দেব, আর তিনি অ-ইহুদীদের কাছে ন্যায়বিচার প্রচার করবেন।"},{"v":19,"ve":19,"vl":"19","bn":"তিনি ঝগড়া বা চিৎকার করবেন না; তিনি রাস্তায় রাস্তায় তাঁর গলার আওয়াজ শোনাবেন না।"},{"v":20,"ve":20,"vl":"20","bn":"ন্যায়বিচারকে জয়ী না করা পর্যন্ত তিনি থেঁৎলে যাওয়া নল ভাংবেন না আর মিট মিট করে জ্বলতে থাকা সল্‌তে নিভাবেন না।"},{"v":21,"ve":21,"vl":"21","bn":"তাঁরই উপর অ-ইহুদীরা আশা রাখবে।"},{"heading":"হযরত ঈসা মসীহ্‌ ও ভূতদের বাদশাহ্‌","v":22,"ve":22,"vl":"22","bn":"পরে লোকেরা ভূতে পাওয়া একজন লোককে ঈসার কাছে আনল। লোকটি অন্ধ এবং বোবা ছিল। ঈসা তাকে ভাল করলেন।"},{"v":23,"ve":23,"vl":"23","bn":"তাতে লোকটি কথা বলতে লাগল ও দেখতে পেল। তখন সব লোকেরা আশ্চর্য হয়ে বলল, “ইনি কি দাউদের সেই বংশধর?”"},{"v":24,"ve":24,"vl":"24","bn":"ফরীশীরা এই কথা শুনে বললেন, “ও তো কেবল ভূতদের বাদশাহ্‌ বেল্‌সবূলের সাহায্যে ভূত ছাড়ায়।”"},{"v":25,"ve":25,"vl":"25","bn":"ফরীশীদের মনের চিন্তা বুঝতে পেরে ঈসা তাঁদের বললেন, “যে রাজ্য নিজের মধ্যে ভাগ হয়ে যায় সেই রাজ্য ধ্বংস হয়। আর যে শহর বা পরিবার নিজের মধ্যে ভাগ হয়ে যায় সেই শহর বা পরিবার টেকে না।"},{"v":26,"ve":26,"vl":"26","bn":"শয়তান যদি শয়তানকেই বের করে দেয় তবে সে তো নিজের মধ্যেই ভাগ হয়ে গেল। তাহলে তার রাজ্য কি করে টিকবে?"},{"v":27,"ve":27,"vl":"27","bn":"আমি যদি বেল্‌সবূলের সাহায্যেই ভূত ছাড়াই তবে আপনাদের লোকেরা কার সাহায্যে তাদের ছাড়ায়? আপনারা ঠিক কথা বলছেন কি না, আপনাদের লোকেরাই তা বিচার করবে।"},{"v":28,"ve":28,"vl":"28","bn":"কিন্তু আমি যদি আল্লাহ্‌র রূহের সাহায্যে ভূত ছাড়াই তবে আল্লাহ্‌র রাজ্য তো আপনাদের কাছে এসে গেছে।"},{"v":29,"ve":29,"vl":"29","bn":"“যে লোকের গায়ে বল আছে তাঁকে প্রথমে বেঁধে না রাখলে কেউ কি তার ঘরে ঢুকে জিনিসপত্র লুট করতে পারে? বাঁধলে পরেই সে তা পারবে।"},{"v":30,"ve":30,"vl":"30","bn":"“যদি কেউ আমার পক্ষে না থাকে তবে সে আমার বিপক্ষে আছে। যে আমার সংগে কুড়ায় না সে ছড়ায়।"},{"v":31,"ve":31,"vl":"31","bn":"এইজন্য আমি আপনাদের বলছি, মানুষের সমস্ত গুনাহ্‌ এবং কুফরী মাফ করা হবে, কিন্তু পাক-রূহের বিরুদ্ধে কুফরী মাফ করা হবে না।"},{"v":32,"ve":32,"vl":"32","bn":"ইব্‌ন্তেআদমের বিরুদ্ধে কেউ কোন কথা বললে তাকে মাফ করা হবে, কিন্তু পাক-রূহের বিরুদ্ধে কথা বললে তাঁকে মাফ করা হবে না- এই যুগেও না, আগামী যুগেও না।"},{"heading":"ফল দ্বারাই গাছ চেনা যায়","v":33,"ve":33,"vl":"33","bn":"“এই কথা স্বীকার করুন যে, গাছ ভাল হলে তার ফলও ভাল হবে, আবার গাছ খারাপ হলে তার ফলও খারাপ হবে; কারণ ফল দিয়েই গাছ চেনা যায়।"},{"v":34,"ve":34,"vl":"34","bn":"সাপের বংশধরেরা! নিজেরা খারাপ হয়ে কেমন করে আপনারা ভাল কথা বলতে পারেন? মানুষের দিল যা দিয়ে পূর্ণ থাকে মুখ তো সেই কথাই বলে।"},{"v":35,"ve":35,"vl":"35","bn":"ভাল লোক তার দিল-ভরা ভাল থেকে ভাল কথা বের করে, আর খারাপ লোক তার দিল-ভরা খারাপী থেকে খারাপ কথা বের করে।"},{"v":36,"ve":36,"vl":"36","bn":"কিন্তু আমি আপনাদের বলছি, লোকে যে সব বাজে কথা বলে, রোজ হাশরে তার প্রত্যেকটি কথার হিসাব তাদের দিতে হবে।"},{"v":37,"ve":37,"vl":"37","bn":"আপনার কথার দ্বারাই আপনাকে নির্দোষ বলা হবে এবং আপনার কথার দ্বারাই আপনাকে দোষী বলা হবে।”"},{"heading":"ফরীশীরা চিহ্নের তালাশ করেন","v":38,"ve":38,"vl":"38","bn":"এর পরে কয়েকজন আলেম ও ফরীশী ঈসাকে বললেন, “হুজুর, আমরা আপনার কাছ থেকে একটা চিহ্ন দেখতে চাই।”"},{"v":39,"ve":39,"vl":"39","bn":"ঈসা তাঁদের বললেন, “এই কালের দুষ্ট ও বেঈমান লোকেরা চিহ্নের খোঁজ করে, কিন্তু ইউনুস নবীর চিহ্ন ছাড়া আর কোন চিহ্নই তাদের দেখানো হবে না।"},{"v":40,"ve":40,"vl":"40","bn":"ইউনুস যেমন সেই মাছের পেটে তিন দিন ও তিন রাত ছিলেন ইব্‌ন্তেআদমও তেমনি তিন দিন ও তিন রাত মাটির নীচে থাকবেন।"},{"v":41,"ve":41,"vl":"41","bn":"রোজ হাশরে নিনেভে শহরের লোকেরা উঠে এই কালের লোকদের দোষ দেখিয়ে দেবে, কারণ নিনেভের লোকেরা ইউনুসের তবলিগের ফলে তওবা করেছিল। আর দেখুন, এখানে ইউনুসের চেয়ে আরও মহান একজন আছেন।"},{"v":42,"ve":42,"vl":"42","bn":"রোজ হাশরে সাবা দেশের রাণী উঠে এই কালের লোকদের দোষ দেখিয়ে দেবেন, কারণ বাদশাহ্‌ সোলায়মানের জ্ঞানের কথাবার্তা শুনবার জন্য তিনি দুনিয়ার শেষ সীমা থেকে এসেছিলেন। আর দেখুন, এখানে সোলায়মানের চেয়ে আরও মহান একজন আছেন।"},{"v":43,"ve":43,"vl":"43","bn":"“যখন কোন ভূত কোন মানুষের মধ্য থেকে বের হয়ে যায় তখন সে বিশ্রামের খোঁজে শুকনা জায়গার মধ্য দিয়ে ঘোরাফেরা করতে থাকে।"},{"v":44,"ve":44,"vl":"44","bn":"কিন্তু তা না পেয়ে সে বলে, ‘যেখান থেকে বের হয়ে এসেছি আমার সেই ঘরেই আমি ফিরে যাব।’ সে ফিরে এসে সেই ঘর খালি, পরিষ্কার ও সাজানো দেখতে পায়।"},{"v":45,"ve":45,"vl":"45","bn":"পরে সেই ভূত গিয়ে নিজের চেয়েও খারাপ আরও সাতটা ভূত সংগে নিয়ে আসে এবং সেখানে ঢুকে বাস করতে থাকে। তাতে সেই লোকটার প্রথম দশা থেকে শেষ দশা আরও খারাপ হয়ে ওঠে। এই কালের দুষ্ট লোকদের অবস্থাও তেমনি হবে।”"},{"heading":"হযরত ঈসা মসীহের মা ও ভাই কারা?","v":46,"ve":46,"vl":"46","bn":"ঈসা যখন লোকদের সংগে কথা বলছিলেন তখন তাঁর মা ও ভাইয়েরা তাঁর সংগে কথা বলবার জন্য বাইরে দাঁড়িয়ে ছিলেন।"},{"v":47,"ve":47,"vl":"47","bn":"কোন একজন লোক তাঁকে বলল, “দেখুন, আপনার মা ও ভাইয়েরা আপনার সংগে কথা বলবার জন্য বাইরে দাঁড়িয়ে আছেন।”"},{"v":48,"ve":48,"vl":"48","bn":"তখন ঈসা তাকে বললেন, “কে আমার মা, আর আমার ভাইয়েরাই বা কারা?”"},{"v":49,"ve":49,"vl":"49","bn":"পরে তিনি তাঁর সাহাবীদের দেখিয়ে বললেন, “এই দেখ, আমার মা ও আমার ভাইয়েরা;"},{"v":50,"ve":50,"vl":"50","bn":"কারণ যারা আমার বেহেশতী পিতার ইচ্ছা পালন করে তারা-ই আমার ভাই, বোন আর মা।”"}],"13":[{"heading":"একজন চাষীর গল্প","v":1,"ve":1,"vl":"1","bn":"সেই দিনই ঈসা ঘর থেকে বের হয়ে সাগরের ধারে গিয়ে বসলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁর কাছে এত লোক এসে জমায়েত হল যে, তিনি একটা নৌকায় উঠে বসলেন, আর সমস্ত লোক সাগরের ধারে দাঁড়িয়ে রইল।"},{"v":3,"ve":3,"vl":"3","bn":"তখন তিনি গল্পের মধ্য দিয়ে অনেক বিষয় তাদের শিক্ষা দিতে লাগলেন।"},{"v":4,"ve":4,"vl":"4","bn":"তিনি বললেন, “একজন চাষী বীজ বুনতে গেল। বুনবার সময় কতগুলো বীজ পথের পাশে পড়ল আর পাখীরা এসে তা খেয়ে ফেলল।"},{"v":5,"ve":5,"vl":"5","bn":"কতগুলো বীজ পাথুরে জমিতে পড়ল। সেখানে বেশী মাটি ছিল না। মাটি গভীর ছিল না বলে তাড়াতাড়ি চারা গজিয়ে উঠল,"},{"v":6,"ve":6,"vl":"6","bn":"কিন্তু সূর্য উঠলে পর তা পুড়ে গেল এবং শিকড় ভাল করে বসে নি বলে শুকিয়ে গেল।"},{"v":7,"ve":7,"vl":"7","bn":"আবার কতগুলো বীজ কাঁটাবনের মধ্যে পড়ল। তাতে কাঁটাগাছ বেড়ে উঠে চারাগুলো চেপে রাখল।"},{"v":8,"ve":8,"vl":"8","bn":"আর কতগুলো বীজ ভাল জমিতে পড়ে কোনটাতে একশো গুণ, কোনটাতে ষাট গুণ আর কোনটাতে ত্রিশ গুণ ফসল জন্মাল।”"},{"v":9,"ve":9,"vl":"9","bn":"গল্পের শেষে ঈসা বললেন, “যার শুনবার কান আছে সে শুনুক।”"},{"heading":"গল্প বলবার উদ্দেশ্য","v":10,"ve":10,"vl":"10","bn":"পরে সাহাবীরা ঈসার কাছে এসে তাঁকে বললেন, “আপনি গল্পের মধ্য দিয়ে লোকদের শিক্ষা দিচ্ছেন কেন?”"},{"v":11,"ve":11,"vl":"11","bn":"জবাবে তিনি সাহাবীদের বললেন, “বেহেশতী রাজ্যের গোপন সত্যগুলো তোমাদের জানতে দেওয়া হয়েছে কিন্তু ওদের জানতে দেওয়া হয় নি,"},{"v":12,"ve":12,"vl":"12","bn":"কারণ যার আছে তাকে আরও দেওয়া হবে, আর তাতে তার অনেক হবে। কিন্তু যার নেই তার যা আছে তা-ও তার কাছে থেকে নিয়ে নেওয়া হবে।"},{"v":13,"ve":13,"vl":"13","bn":"সেইজন্য আমি গল্পের মধ্য দিয়ে ওদের শিক্ষা দিই, কারণ ওরা দেখেও দেখে না, শুনেও শোনে না এবং বোঝে না।"},{"v":14,"ve":14,"vl":"14","bn":"এদের মধ্য দিয়ে ইশাইয়া নবীর এই কথা পূর্ণ হচ্ছে: তোমরা শুনতে থাকবে কিন্তু কোনমতেই বুঝবে না; দেখতে থাকবে কিন্তু কোনমতেই জানবে না।"},{"v":15,"ve":15,"vl":"15","bn":"এই সব লোকদের দিল অসাড় এবং কান বন্ধ হয়ে গেছে, আর তারা তাদের চোখও বন্ধ করে রেখেছে, যেন তারা চোখ দিয়ে না দেখে, কান দিয়ে না শোনে এবং দিল নিয়ে না বোঝে, আর ভাল হবার জন্য আমার কাছে ফিরে না আসে।"},{"v":16,"ve":16,"vl":"16","bn":"“কিন্তু ধন্য তোমরা, কারণ তোমাদের চোখ দেখতে পায় এবং তোমাদের কান শুনতে পায়।"},{"v":17,"ve":17,"vl":"17","bn":"আমি তোমাদের সত্যি বলছি, তোমরা যা যা দেখছ তা অনেক নবী ও আল্লাহ্‌ভক্ত লোকেরা দেখতে চেয়েও দেখতে পান নি, আর তোমরা যা যা শুনছ তা তাঁরা শুনতে চেয়েও শুনতে পান নি।"},{"heading":"চাষীর গল্পের অর্থ","v":18,"ve":19,"vl":"18-19","bn":"“এখন তোমরা চাষীর গল্পের অর্থ শোন। যখন কেউ বেহেশতী রাজ্যের কথা শুনেও বোঝে না তখন শয়তান এসে তার দিলে যে কথা বোনা হয়েছিল তা কেড়ে নেয়। সেই পথের পাশে পড়া বীজের মধ্য দিয়ে এই রকম লোকদের সম্বন্ধে বলা হয়েছে।"},{"v":20,"ve":20,"vl":"20","bn":"আর পাথুরে জমিতে বোনা বীজের মধ্য দিয়ে তাদের সম্বন্ধে বলা হয়েছে যারা বেহেশতী রাজ্যের কথা শুনে তখনই আনন্দের সংগে তা গ্রহণ করে,"},{"v":21,"ve":21,"vl":"21","bn":"কিন্তু তাদের মধ্যে শিকড় ভাল করে বসে না বলে তারা অল্প সময়ের জন্য স্থির থাকে। যখন সেই কথার জন্য কষ্ট এবং জুলুম আসে তখনই তারা পিছিয়ে যায়।"},{"v":22,"ve":22,"vl":"22","bn":"কাঁটার মধ্যে বোনা বীজের মধ্য দিয়ে তাদের সম্বন্ধে বলা হয়েছে যারা সেই কথা শোনে, কিন্তু সংসারের চিন্তা-ভাবনা এবং ধন-সম্পত্তির মায়া সেই কথাকে চেপে রাখে। সেইজন্য তাতে কোন ফল হয় না।"},{"v":23,"ve":23,"vl":"23","bn":"ভাল জমিতে বোনা বীজের মধ্য দিয়ে তাদের সম্বন্ধে বলা হয়েছে যারা সেই কথা শুনে বোঝে এবং ফল দেয়। কেউ দেয় একশো গুণ, কেউ দেয় ষাট গুণ আর কেউ দেয় ত্রিশ গুণ।”"},{"heading":"গমের মধ্যে শ্যামাঘাস","v":24,"ve":24,"vl":"24","bn":"পরে ঈসা লোকদের শিক্ষা দেবার জন্য আর একটা গল্প বললেন। গল্পটা এই: “বেহেশতী রাজ্য এমন একজন লোকের মত যিনি নিজের জমিতে ভাল বীজ বুনলেন।"},{"v":25,"ve":25,"vl":"25","bn":"পরে যখন সবাই ঘুমিয়ে পড়ল তখন সেই লোকের শত্রু এসে গমের মধ্যে শ্যামাঘাসের বীজ বুনে চলে গেল।"},{"v":26,"ve":26,"vl":"26","bn":"শেষে গমের চারা যখন বেড়ে উঠে ফল ধরল তখন তার মধ্যে শ্যামাঘাসও দেখা গেল।"},{"v":27,"ve":27,"vl":"27","bn":"তা দেখে বাড়ীর গোলামেরা এসে মালিককে বলল, ‘আপনি কি জমিতে ভাল বীজ বোনেন নি? তবে শ্যামাঘাস কোথা থেকে আসল?’"},{"v":28,"ve":28,"vl":"28","bn":"“তিনি তাদের বললেন, ‘কোন শত্রু এটা করেছে।’ “গোলামেরা তাঁকে বলল, ‘তবে আমরা গিয়ে সেগুলো তুলে ফেলব কি?’"},{"v":29,"ve":29,"vl":"29","bn":"“তিনি বললেন, ‘না, শ্যামাঘাস তুলতে গিয়ে তোমরা হয়তো ঘাসের সংগে গমও তুলে ফেলবে।"},{"v":30,"ve":30,"vl":"30","bn":"ফসল কাটবার সময় পর্যন্ত ওগুলো একসংগে বাড়তে দাও। যারা ফসল কাটে, আমি তখন তাদের বলব যেন তারা প্রথমে শ্যামাঘাসগুলো জড়ো করে পোড়াবার জন্য আঁটি আঁটি করে বাঁধে, আর তার পরে গম আমার গোলায় জমা করে।’ ”"},{"heading":"সরিষা-দানা ও খামির গল্প","v":31,"ve":31,"vl":"31","bn":"ঈসা তাদের আর একটা গল্প বললেন। গল্পটা এই: “বেহেশতী রাজ্য এমন একটা সরিষা-দানার মত যা একজন লোক নিয়ে নিজের জমিতে লাগাল।"},{"v":32,"ve":32,"vl":"32","bn":"সমস্ত বীজের মধ্যে ওটা সত্যিই সবচেয়ে ছোট, কিন্তু গাছ হয়ে বেড়ে উঠলে পর তা সমস্ত শাক-সবজীর মধ্যে সবচেয়ে বড় হয়। ওটা এমন একটা বড় গাছ হয়ে ওঠে যে, পাখীরা এসে তার ডালপালায় বাসা বাঁধে।”"},{"v":33,"ve":33,"vl":"33","bn":"তিনি তাদের আর একটা গল্প বললেন। গল্পটা এই: “বেহেশতী রাজ্য খামির মত। একজন স্ত্রীলোক তা নিয়ে আঠারো কেজি ময়দার মধ্যে মিশাল। ফলে সমস্ত ময়দাই ফেঁপে উঠল।”"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা গল্পের মধ্য দিয়ে লোকদের এই সব শিক্ষা দিলেন। তিনি গল্প ছাড়া কোন শিক্ষাই তাদের দিতেন না।"},{"v":35,"ve":35,"vl":"35","bn":"এটা হল যাতে নবীর মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হয়: শিক্ষা-ভরা উদাহরণের মধ্য দিয়ে আমি মুখ খুলব; দুনিয়ার শুরু থেকে যা যা লুকানো ছিল, তা বলব।"},{"heading":"শ্যামাঘাসের গল্পটার অর্থ","v":36,"ve":36,"vl":"36","bn":"পরে ঈসা লোকদের ছেড়ে ঘরে ঢুকলেন। তখন তাঁর সাহাবীরা এসে তাঁকে বললেন, “জমির ঐ শ্যামাঘাসের গল্পটা আমাদের বুঝিয়ে দিন।”"},{"v":37,"ve":37,"vl":"37","bn":"জবাবে ঈসা তাঁদের বললেন, “যিনি ভাল বীজ বোনেন তিনি ইব্‌ন্তেআদম।"},{"v":38,"ve":38,"vl":"38","bn":"জমি এই দুনিয়া, আর বেহেশতী রাজ্যের লোকেরা ভাল বীজ। শয়তানের লোকেরা হল সেই শ্যামাঘাস।"},{"v":39,"ve":39,"vl":"39","bn":"যে শত্রু তা বুনেছিল সে হল ইবলিস, আর ফসল কাটবার সময় হল এই যুগের শেষ সময়। যাঁরা শস্য কাটবেন তাঁরা হলেন ফেরেশতা।"},{"v":40,"ve":40,"vl":"40","bn":"শ্যামাঘাস জড়ো করে যেমন আগুনে পুড়িয়ে দেওয়া হয়, যুগের শেষের সময়ও ঠিক তেমনি হবে। ইব্‌ন্তেআদম তাঁর ফেরেশতাদের পাঠিয়ে দেবেন।"},{"v":41,"ve":41,"vl":"41","bn":"যারা অন্যদের গুনাহ্‌ করায় এবং যারা নিজেরা গুনাহ্‌ করে তাদের সবাইকে সেই ফেরেশতারা ইব্‌ন্তেআদমের রাজ্যের মধ্য থেকে একসংগে জমায়েত করবেন ও জ্বলন্ত আগুনের মধ্যে ফেলে দেবেন।"},{"v":42,"ve":42,"vl":"42","bn":"সেখানে লোকে কান্নাকাটি করবে ও যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবে।"},{"v":43,"ve":43,"vl":"43","bn":"সেই সময়ে আল্লাহ্‌ভক্ত লোকেরা তাদের বেহেশতী পিতার রাজ্যে সূর্যের মত উজ্জ্বল হয়ে দেখা দেবে। যার শুনবার কান আছে সে শুনুক।"},{"heading":"আরও তিনটি গল্প","v":44,"ve":44,"vl":"44","bn":"“বেহেশতী রাজ্য জমির মধ্যে লুকিয়ে রাখা ধনের মত। একজন লোক তা খুঁজে পেয়ে আবার লুকিয়ে রাখল। তারপর সে খুশী মনে চলে গেল এবং তার যা কিছু ছিল সব বিক্রি করে সেই জমিটা কিনল।"},{"v":45,"ve":45,"vl":"45","bn":"“আবার, বেহেশতী রাজ্য এমন একজন সওদাগরের মত যে ভাল মুক্তা খুঁজছিল।"},{"v":46,"ve":46,"vl":"46","bn":"একটা দামী মুক্তার খোঁজ পেয়ে সে গিয়ে তার যা কিছু ছিল সব বিক্রি করে সেই মুক্তাটা কিনল।"},{"v":47,"ve":47,"vl":"47","bn":"“আবার, বেহেশতী রাজ্য এমন একটা বড় জালের মত যা সাগরে ফেলা হল আর তাতে সব রকম মাছ ধরা পড়ল।"},{"v":48,"ve":48,"vl":"48","bn":"জাল পূর্ণ হলে পর লোকেরা সেটা পারে টেনে তুলল। পরে তারা বসে ভাল মাছগুলো বেছে ঝুড়িতে রাখল এবং খারাপগুলো ফেলে দিল।"},{"v":49,"ve":49,"vl":"49","bn":"যুগের শেষের সময়ে এই রকমই হবে। ফেরেশতারা এসে আল্লাহ্‌ভক্ত লোকদের মধ্য থেকে দুষ্টদের আলাদা করবেন এবং জ্বলন্ত আগুনের মধ্যে তাদের ফেলে দেবেন।"},{"v":50,"ve":50,"vl":"50","bn":"সেখানে লোকে কান্নাকাটি করবে ও যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবে।”"},{"v":51,"ve":51,"vl":"51","bn":"এর পর ঈসা তাঁর সাহাবীদের জিজ্ঞাসা করলেন, “তোমরা কি এই সব বুঝতে পেরেছ?” তাঁরা তাঁকে বললেন, “জ্বী, পেরেছি।”"},{"v":52,"ve":52,"vl":"52","bn":"তখন ঈসা তাদের বললেন, “বেহেশতী রাজ্যের বিষয়ে যে সব আলেম শিক্ষা পেয়েছেন তারা সবাই এমন একজন গৃহসে'র মত যিনি তাঁর ভাণ্ডার থেকে নতুন ও পুরানো জিনিস বের করেন।”"},{"heading":"নিজের গ্রামে হযরত ঈসা মসীহের অসম্মান","v":53,"ve":53,"vl":"53","bn":"শিক্ষা দেবার জন্য এই সব গল্প বলা শেষ করে ঈসা সেখান থেকে চলে গেলেন।"},{"v":54,"ve":54,"vl":"54","bn":"তারপর নিজের গ্রামে গিয়ে তিনি মজলিস-খানায় লোকদের শিক্ষা দিতে লাগলেন। তাঁর কথা শুনে লোকে আশ্চর্য হয়ে বলল, “এই জ্ঞান ও এই সব অলৌকিক চিহ্ন-কাজ করবার ক্ষমতা এ কোথা থেকে পেল?"},{"v":55,"ve":55,"vl":"55","bn":"এ কি সেই ছুতার মিস্ত্রীর ছেলে নয়? তার মায়ের নাম কি মরিয়ম নয়? আর তার ভাইয়েরা কি ইয়াকুব, ইউসুফ, শিমোন ও এহুদা নয়?"},{"v":56,"ve":56,"vl":"56","bn":"তার সব বোনেরা কি আমাদের মধ্যে নেই? তাহলে কোথা থেকে সে এই সব পেল?”"},{"v":57,"ve":57,"vl":"57","bn":"এইভাবে ঈসাকে নিয়ে লোকদের মনে বাধা আসতে লাগল। তখন ঈসা তাদের বললেন, “নিজের গ্রাম ও নিজের বাড়ী ছাড়া আর সব জায়গাতেই নবীরা সম্মান পান।”"},{"v":58,"ve":58,"vl":"58","bn":"লোকদের অবিশ্বাসের জন্য তিনি সেখানে বেশী অলৌকিক চিহ্ন-কাজ করলেন না।"}],"14":[{"heading":"হযরত ইয়াহিয়া (আঃ)-এর মৃত্যু","v":1,"ve":1,"vl":"1","bn":"সেই সময়ে ঈসার বিষয় শুনে গালীল প্রদেশের শাসনকর্তা হেরোদ তাঁর কর্মচারীদের বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“ইনি তরিকাবন্দীদাতা ইয়াহিয়া; মৃত্যু থেকে বেঁচে উঠেছেন। সেইজন্যই উনি এই সব অলৌকিক চিহ্ন-কাজ করছেন।”"},{"v":3,"ve":3,"vl":"3","bn":"হেরোদ নিজের ভাই ফিলিপের স্ত্রী হেরোদিয়ার দরুন ইয়াহিয়াকে বেঁধে নিয়ে গিয়ে জেলখানায় রেখেছিলেন,"},{"v":4,"ve":4,"vl":"4","bn":"কারণ ইয়াহিয়া তাঁকে বলতেন, “হেরোদিয়াকে স্ত্রী হিসাবে রাখা আপনার উচিত নয়।”"},{"v":5,"ve":5,"vl":"5","bn":"হেরোদ ইয়াহিয়াকে হত্যা করতে চেয়েছিলেন, কিন্তু তিনি লোকদের ভয় করতেন কারণ লোকে ইয়াহিয়াকে নবী বলে মানত।"},{"v":6,"ve":6,"vl":"6","bn":"হেরোদের জন্মদিনের উৎসবে হেরোদিয়ার মেয়ে উপস্থিত লোকদের সামনে নেচে হেরোদকে সন্তুষ্ট করল।"},{"v":7,"ve":7,"vl":"7","bn":"সেইজন্য হেরোদ কসম খেয়ে বললেন সে যা চাইবে তা-ই তিনি তাকে দেবেন।"},{"v":8,"ve":8,"vl":"8","bn":"মেয়েটি তার মায়ের কাছ থেকে পরামর্শ পেয়ে বলল, “থালায় করে তরিকাবন্দীদাতা ইয়াহিয়ার মাথাটা এখানে আমার কাছে এনে দিন।”"},{"v":9,"ve":9,"vl":"9","bn":"এতে বাদশাহ্‌ হেরোদ দুঃখিত হলেন, কিন্তু যাঁরা তাঁর সংগে খেতে বসেছিলেন তাঁদের সামনে কসম খেয়েছিলেন বলে তিনি তা দিতে হুকুম করলেন।"},{"v":10,"ve":10,"vl":"10","bn":"তিনি লোক পাঠিয়ে জেলখানার মধ্যেই ইয়াহিয়ার মাথা কাটালেন।"},{"v":11,"ve":11,"vl":"11","bn":"পরে মাথাটি থালায় করে এনে মেয়েটিকে দেওয়া হলে পর সে তার মায়ের কাছে তা নিয়ে গেল।"},{"v":12,"ve":12,"vl":"12","bn":"এর পর ইয়াহিয়ার সাহাবীরা এসে তাঁর লাশটা নিয়ে গিয়ে দাফন করলেন এবং সেই খবর ঈসাকে গিয়ে দিলেন।"},{"heading":"পাঁচ হাজার লোককে খাওয়ানো","v":13,"ve":13,"vl":"13","bn":"ইয়াহিয়ার মৃত্যুর খবর শুনে ঈসা একাই সেখান থেকে নৌকায় করে একটা নির্জন জায়গায় চলে গেলেন। লোকেরা সেই কথা শুনে ভিন্ন ভিন্ন গ্রাম থেকে হাঁটা-পথে তাঁর পিছন ধরল।"},{"v":14,"ve":14,"vl":"14","bn":"তিনি নৌকা থেকে নেমে লোকদের ভিড় দেখতে পেলেন আর মমতায় পূর্ণ হয়ে তাদের মধ্যে যারা অসুস্থ ছিল তাদের সুস্থ করলেন।"},{"v":15,"ve":15,"vl":"15","bn":"দিনের শেষে সাহাবীরা তাঁর কাছে এসে বললেন, “জায়গাটা নির্জন, বেলাও গেছে। লোকদের বিদায় করে দিন যেন তারা গ্রামে গিয়ে নিজেদের জন্য খাবার কিনতে পারে।”"},{"v":16,"ve":16,"vl":"16","bn":"ঈসা তাঁদের বললেন, “ওদের যাবার দরকার নেই, তোমরাই ওদের খেতে দাও।”"},{"v":17,"ve":17,"vl":"17","bn":"সাহাবীরা তাঁকে বললেন, “আমাদের এখানে পাঁচখানা রুটি আর দু’টা মাছ ছাড়া আর কিছুই নেই।”"},{"v":18,"ve":19,"vl":"18-19","bn":"তিনি বললেন, “ওগুলো আমার কাছে আন।” পরে তিনি লোকদের ঘাসের উপর বসতে হুকুম করলেন, আর সেই পাঁচখানা রুটি আর দু’টা মাছ নিয়ে আসমানের দিকে তাকিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন। এর পরে তিনি রুটি ভেংগে সাহাবীদের হাতে দিলেন আর সাহাবীরা তা লোকদের দিলেন। তারা প্রত্যেকে পেট ভরে খেল।"},{"v":20,"ve":20,"vl":"20","bn":"খাওয়ার পরে যে টুকরাগুলো পড়ে রইল সাহাবীরা তা তুলে নিলেন, আর তাতে বারোটা টুকরি পূর্ণ হল।"},{"v":21,"ve":21,"vl":"21","bn":"যারা খেয়েছিল তাদের মধ্যে স্ত্রীলোক ও ছোট ছেলেমেয়ে ছাড়া কমবেশী পাঁচ হাজার পুরুষ ছিল।"},{"heading":"পানির উপর দিয়ে হাঁটা","v":22,"ve":22,"vl":"22","bn":"এর পরে ঈসা সাহাবীদের তাগাদা দিলেন যেন তাঁরা নৌকায় উঠে তাঁর আগে অন্য পারে যান, আর এদিকে তিনি লোকদের বিদায় করলেন।"},{"v":23,"ve":23,"vl":"23","bn":"লোকদের বিদায় করে মুনাজাত করবার জন্য তিনি একা পাহাড়ে উঠে গেলেন। যখন সন্ধ্যা ঘনিয়ে আসল তখনও তিনি সেখানে একাই রইলেন।"},{"v":24,"ve":24,"vl":"24","bn":"ততক্ষণে সাহাবীদের নৌকাখানা ডাংগা থেকে অনেকটা দূরে গিয়ে পড়েছিল এবং বাতাস উল্টাদিকে থাকাতে ঢেউয়ে ভীষণভাবে দুলছিল।"},{"v":25,"ve":25,"vl":"25","bn":"শেষ রাতে ঈসা সাগরের উপর দিয়ে হেঁটে সাহাবীদের কাছে আসছিলেন।"},{"v":26,"ve":26,"vl":"26","bn":"সাহাবীরা একজনকে সাগরের উপর হাঁটতে দেখে ভীষণ ভয় পেয়ে বললেন, “ভূত, ভূত,” আর তার পরেই চিৎকার করে উঠলেন।"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা তখনই তাঁদের বললেন, “এ তো আমি; ভয় কোরো না, সাহস কর।”"},{"v":28,"ve":28,"vl":"28","bn":"পিতর তাঁকে বললেন, “হুজুর, যদি আপনিই হন তবে পানির উপর দিয়ে আপনার কাছে যেতে আমাকে হুকুম দিন।”"},{"v":29,"ve":29,"vl":"29","bn":"ঈসা বললেন, “এস।” তখন পিতর নৌকা থেকে নেমে পানির উপর দিয়ে হেঁটে ঈসার কাছে চললেন।"},{"v":30,"ve":30,"vl":"30","bn":"কিন্তু জোর বাতাস দেখে তিনি ভয় পেয়ে ডুবে যেতে লাগলেন এবং চিৎকার করে বললেন, “হুজুর, আমাকে বাঁচান।”"},{"v":31,"ve":31,"vl":"31","bn":"ঈসা তখনই হাত বাড়িয়ে তাঁকে ধরলেন এবং বললেন, “অল্প ঈমানদার, কেন সন্দেহ করলে?”"},{"v":32,"ve":33,"vl":"32-33","bn":"ঈসা আর পিতর নৌকায় উঠলে পর বাতাস থেমে গেল। যাঁরা নৌকার মধ্যে ছিলেন তাঁরা ঈসাকে সেজদা করে বললেন, “সত্যিই আপনি ইব্‌নুল্লাহ্‌।”"},{"v":34,"ve":34,"vl":"34","bn":"পরে তাঁরা সাগর পার হয়ে গিনেষরৎ এলাকায় এসে নামলেন।"},{"v":35,"ve":35,"vl":"35","bn":"সেখানকার লোকেরা ঈসাকে চিনতে পেরে এলাকার সব জায়গায় খবর পাঠাল।"},{"v":36,"ve":36,"vl":"36","bn":"তাতে লোকেরা অসুস্থদের ঈসার কাছে আনল এবং তাঁকে অনুরোধ করল যেন সেই অসুস্থরা তাঁর চাদরের কিনারাটা কেবল ছুঁতে পারে; আর যত লোক তা ছুঁলো তারা সবাই সুস্থ হল।"}],"15":[{"heading":"চলতি নিয়ম","v":1,"ve":1,"vl":"1","bn":"জেরুজালেম থেকে কয়েকজন ফরীশী ও আলেম ঈসার কাছে এসে বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“পুরানো দিনের আলেমদের দেওয়া যে নিয়ম চলে আসছে আপনার সাহাবীরা তা মেনে চলে না কেন? খাওয়ার আগে তারা হাত ধোয় না।”"},{"v":3,"ve":3,"vl":"3","bn":"জবাবে ঈসা বললেন, “যে নিয়ম চলে আসছে তার জন্য আপনারাই বা কেন আল্লাহ্‌র হুকুম অমান্য করেন?"},{"v":4,"ve":4,"vl":"4","bn":"আল্লাহ্‌ বলেছেন, ‘মা-বাবাকে সম্মান কোরো’ এবং ‘যার কথায় মা-বাবার প্রতি অসম্মান থাকে তাকে অবশ্যই হত্যা করতে হবে।’"},{"v":5,"ve":5,"vl":"5","bn":"কিন্তু আপনারা বলে থাকেন, যদি কেউ তার মা কিংবা বাবাকে বলে, ‘আমার যে জিনিসের দ্বারা তোমার সাহায্য হতে পারত, তা আল্লাহ্‌র কাছে দেওয়া হয়েছে,’"},{"v":6,"ve":6,"vl":"6","bn":"তবে পিতা-মাতাকে তার আর সম্মান করবার দরকার নেই। আপনাদের এই সব চলতি নিয়মের জন্য আপনারা আল্লাহ্‌র কালাম বাতিল করেছেন।"},{"v":7,"ve":7,"vl":"7","bn":"ভণ্ডেরা! আপনাদের সম্বন্ধে ইশাইয়া নবী ঠিক কথাই বলেছিলেন যে,"},{"v":8,"ve":8,"vl":"8","bn":"এই লোকেরা মুখেই আমাকে সম্মান করে, কিন্তু তাদের দিল আমার কাছ থেকে দূরে থাকে।"},{"v":9,"ve":9,"vl":"9","bn":"তারা মিথ্যাই আমার এবাদত করে; তাদের দেওয়া শিক্ষা মানুষের তৈরী কতগুলো নিয়ম মাত্র।"},{"heading":"কিভাবে লোকে নাপাক হয়","v":10,"ve":10,"vl":"10","bn":"পরে ঈসা লোকদের ডেকে বললেন, “আমার কথা শুনুন এবং বুঝুন।"},{"v":11,"ve":11,"vl":"11","bn":"মুখের ভিতরে যা যায় তা মানুষকে নাপাক করে না, কিন্তু মুখের ভিতর থেকে যা বের হয়ে আসে তা-ই মানুষকে নাপাক করে।”"},{"v":12,"ve":12,"vl":"12","bn":"তখন তাঁর সাহাবীরা এসে তাঁকে বললেন, “ফরীশীরা আপনার এই কথা শুনে যে অপমান বোধ করেছেন, তা কি আপনি জানেন?”"},{"v":13,"ve":13,"vl":"13","bn":"জবাবে তিনি বললেন, “যে চারা আমার বেহেশতী পিতা লাগান নি তার প্রত্যেকটাকে উপ্‌ড়ে ফেলা হবে। তাদের কথা ছেড়ে দাও।"},{"v":14,"ve":14,"vl":"14","bn":"অন্ধদের পথ দেখাবার কথা তাঁদেরই, কিন্তু তাঁরা নিজেরাই অন্ধ। অন্ধ অন্ধকে পথ দেখাতে গেলে দু’জনই গর্তে পড়ে।”"},{"v":15,"ve":15,"vl":"15","bn":"তখন পিতর ঈসাকে বললেন, “আপনি যে দৃষ্টান্ত দিলেন তা আমাদের বুঝিয়ে দিন।”"},{"v":16,"ve":17,"vl":"16-17","bn":"ঈসা বললেন, “তোমরা কি এখনও অবুঝ রয়েছ? তোমরা কি বোঝ না যে, যা কিছু মুখের মধ্যে যায় তা পেটের মধ্যে ঢোকে এবং শেষে বের হয়ে যায়?"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু যা মুখের ভিতর থেকে বের হয়ে আসে তা অন্তর থেকে আসে, আর সেগুলোই মানুষকে নাপাক করে।"},{"v":19,"ve":19,"vl":"19","bn":"অন্তর থেকেই খারাপ চিন্তা, খুন, সব রকম জেনা, চুরি, মিথ্যা সাক্ষ্য ও নিন্দা বের হয়ে আসে।"},{"v":20,"ve":20,"vl":"20","bn":"এই সবই মানুষকে নাপাক করে, কিন্তু হাত না ধুয়ে খেলে মানুষ নাপাক হয় না।”"},{"heading":"অ-ইহুদী স্ত্রীলোকের বিশ্বাস","v":21,"ve":21,"vl":"21","bn":"পরে ঈসা সেই জায়গা ছেড়ে টায়ার ও সিডন এলাকায় চলে গেলেন।"},{"v":22,"ve":22,"vl":"22","bn":"সেখানকার একজন কেনানীয় স্ত্রীলোক এসে চিৎকার করে বলতে লাগল, “হে হুজুর, দাউদের বংশধর, আমাকে দয়া করুন। ভূতে ধরবার দরুন আমার মেয়েটি ভীষণ কষ্ট পাচ্ছে।”"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা কিন্তু তাকে একটা কথাও বললেন না। তখন তাঁর সাহাবীরা এসে তাঁকে অনুরোধ করে বললেন, “ওকে বিদায় করে দিন, কারণ ও আমাদের পিছনে পিছনে চিৎকার করছে।”"},{"v":24,"ve":24,"vl":"24","bn":"জবাবে ঈসা বললেন, “আমাকে কেবল বনি-ইসরাইলদের হারানো ভেড়াদের কাছেই পাঠানো হয়েছে।”"},{"v":25,"ve":25,"vl":"25","bn":"সেই স্ত্রীলোকটি কিন্তু ঈসার কাছে এসে তাঁর সামনে উবুড় হয়ে পড়ে বলল, “হুজুর, আমার এই উপকারটা করুন।”"},{"v":26,"ve":26,"vl":"26","bn":"ঈসা বললেন, “ছেলেমেয়েদের খাবার নিয়ে কুকুরের সামনে ফেলা ভাল নয়।”"},{"v":27,"ve":27,"vl":"27","bn":"সে বলল, “ঠিক কথা, হুজুর; তবুও মালিকের টেবিল থেকে খাবারের যে সব টুকরা পড়ে তা কুকুরেই খায়।”"},{"v":28,"ve":28,"vl":"28","bn":"তখন ঈসা তাকে বললেন, “সত্যিই তোমার বিশ্বাস খুব বেশী। তুমি যেমন চাও তেমনই হোক।” আর তখনই তার মেয়েটি সুস্থ হয়ে গেল।"},{"heading":"চার হাজার লোককে খাওয়ানো","v":29,"ve":29,"vl":"29","bn":"পরে ঈসা সেই জায়গা ছেড়ে গালীল সাগরের পার দিয়ে চললেন এবং একটা পাহাড়ে উঠে সেখানে বসলেন।"},{"v":30,"ve":30,"vl":"30","bn":"তখন লোকেরা খোঁড়া, অন্ধ, নুলা, বোবা এবং আরও অনেককে সংগে নিয়ে তাঁর কাছে আসল। তারা ঐ সব লোকদের তাঁর পায়ের কাছে রাখল আর তিনি তাদের সুস্থ করলেন।"},{"v":31,"ve":31,"vl":"31","bn":"লোকেরা যখন দেখল বোবা কথা বলছে, নুলা সুস্থ হচ্ছে, খোঁড়া চলাফেরা করছে এবং অন্ধ দেখতে পাচ্ছে, তখন তারা আশ্চর্য হল এবং বনি-ইসরাইলদের আল্লাহ্‌র প্রশংসা করতে লাগল।"},{"v":32,"ve":32,"vl":"32","bn":"এর পর ঈসা তাঁর সাহাবীদের ডেকে বললেন, “এই লোকদের জন্য আমার মমতা হচ্ছে, কারণ আজ তিন দিন হল এরা আমার সংগে সংগে আছে, আর এদের কাছে কোন খাবার নেই। এই অবস্থায় আমি এদের বিদায় দিতে চাই না; হয়তো বা তারা পথে অজ্ঞান হয়ে পড়বে।”"},{"v":33,"ve":33,"vl":"33","bn":"সাহাবীরা তাঁকে বললেন, “এই নির্জন জায়গায় এত লোককে খাওয়াবার মত রুটি আমরা কোথায় পাব?”"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা তাঁদের বললেন, “তোমাদের কাছে কয়টা রুটি আছে?” সাহাবীরা বললেন, “সাতটা রুটি আর কয়েকটা ছোট মাছ আছে।”"},{"v":35,"ve":36,"vl":"35-36","bn":"লোকদের মাটিতে বসতে হুকুম দিয়ে ঈসা সেই সাতটা রুটি আর মাছগুলো নিলেন। পরে তিনি আল্লাহ্‌কে শুকরিয়া জানিয়ে সেগুলো ভাঙ্গলেন ও সাহাবীদের হাতে দিলেন, আর সাহাবীরা তা লোকদের দিলেন।"},{"v":37,"ve":37,"vl":"37","bn":"লোকেরা সবাই পেট ভরে খেল, আর যে টুকরাগুলো পড়ে রইল সাহাবীরা তা তুলে নিয়ে সাতটা টুকরি পূর্ণ করলেন।"},{"v":38,"ve":38,"vl":"38","bn":"যারা খেয়েছিল তাদের মধ্যে স্ত্রীলোক ও ছোট ছেলেমেয়ে ছাড়া চার হাজার পুরুষ ছিল।"},{"v":39,"ve":39,"vl":"39","bn":"এর পর ঈসা লোকদের বিদায় দিয়ে নৌকায় উঠে মগদন এলাকায় গেলেন।"}],"16":[{"heading":"লোকেরা চিহ্ন দেখতে চায়","v":1,"ve":1,"vl":"1","bn":"পরে কয়েকজন ফরীশী ও সদ্দূকী ঈসাকে পরীক্ষা করবার জন্য তাঁর কাছে আসলেন এবং বেহেশত থেকে কোন চিহ্ন দেখাতে বললেন।"},{"v":2,"ve":2,"vl":"2","bn":"ঈসা জবাবে তাঁদের বললেন, “সন্ধ্যা হলে আপনারা বলে থাকেন, ‘দিনটা পরিষ্কার হবে কারণ আকাশ লাল হয়েছে।’"},{"v":3,"ve":3,"vl":"3","bn":"আর সকালবেলায় বলেন, ‘আজ ঝড় হবে কারণ আকাশ লাল ও অন্ধকার হয়েছে।’ আকাশের অবস্থা আপনারা ঠিক ভাবেই বিচার করতে জানেন, অথচ সময়ের চিহ্ন বুঝতে পারেন না।"},{"v":4,"ve":4,"vl":"4","bn":"এই কালের দুষ্ট ও বেঈমান লোকেরা চিহ্নের খোঁজ করে, কিন্তু ইউনুস নবীর চিহ্ন ছাড়া আর কোন চিহ্নই তাদের দেখানো হবে না।” এর পরে ঈসা তাঁদের ছেড়ে চলে গেলেন।"},{"heading":"সাহাবীদের সাবধান করা","v":5,"ve":5,"vl":"5","bn":"সাগরের অন্য পারে যাবার সময় সাহাবীরা রুটি নিতে ভুলে গেলেন।"},{"v":6,"ve":6,"vl":"6","bn":"ঈসা তাঁদের বললেন, “তোমরা সতর্ক থাক, ফরীশী ও সদ্দূকীদের খামি থেকে সাবধান হও।”"},{"v":7,"ve":7,"vl":"7","bn":"এতে সাহাবীরা নিজেদের মধ্যে বলাবলি করতে লাগলেন, “আমরা রুটি আনি নি বলে উনি এই কথা বলছেন।”"},{"v":8,"ve":8,"vl":"8","bn":"এই কথা বুঝতে পেরে ঈসা বললেন, “অল্প বিশ্বাসীরা, তোমরা নিজেদের মধ্যে কেন বলাবলি করছ যে, তোমাদের রুটি নেই?"},{"v":9,"ve":9,"vl":"9","bn":"তোমরা কি এখনও বোঝ না বা মনেও কি পড়ে না, সেই পাঁচ হাজার লোকের জন্য পাঁচখানা রুটির কথা, আর তার পরে কত টুকরি তোমরা তুলে নিয়েছিলে?"},{"v":10,"ve":10,"vl":"10","bn":"কিংবা সেই চার হাজার লোকের জন্য সাতখানা রুটির কথা, আর কত টুকরি তোমরা তুলে নিয়েছিলে?"},{"v":11,"ve":11,"vl":"11","bn":"আমি যে তোমাদের কাছে রুটির কথা বলি নি তা তোমরা কেন বোঝ না? ফরীশী ও সদ্দূকীদের খামি থেকে তোমরা সাবধান হও।”"},{"v":12,"ve":12,"vl":"12","bn":"তখন সাহাবীরা বুঝতে পারলেন যে, তিনি রুটির খামি থেকে তাঁদের সাবধান হতে বলেন নি, কিন্তু ফরীশী ও সদ্দূকীদের শিক্ষা থেকে সাবধান হতে বলেছেন।"},{"heading":"হযরত ঈসা কে?","v":13,"ve":13,"vl":"13","bn":"পরে ঈসা যখন সিজারিয়া-ফিলিপি এলাকায় গেলেন তখন সাহাবীদের জিজ্ঞাসা করলেন, “ইব্‌ন্তেআদম কে, এই বিষয়ে লোকে কি বলে?”"},{"v":14,"ve":14,"vl":"14","bn":"তাঁরা বললেন, “কেউ কেউ বলে আপনি তরিকাবন্দীদাতা ইয়াহিয়া; কেউ কেউ বলে ইলিয়াস নবী; আবার কেউ কেউ বলে ইয়ারমিয়া নবী বা নবীদের মধ্যে একজন।”"},{"v":15,"ve":15,"vl":"15","bn":"তখন তিনি তাঁদের বললেন, “কিন্তু তোমরা কি বল, আমি কে?”"},{"v":16,"ve":16,"vl":"16","bn":"শিমোন্তপিতর বললেন, “আপনি সেই মসীহ্‌, জীবন্ত আল্লাহ্‌র পুত্র।”"},{"v":17,"ve":17,"vl":"17","bn":"জবাবে ঈসা তাঁকে বললেন, “শিমোন ইব্‌নে ইউনুস, ধন্য তুমি, কারণ কোন মানুষ তোমার কাছে এটা প্রকাশ করে নি; আমার বেহেশতী পিতাই প্রকাশ করেছেন।"},{"v":18,"ve":18,"vl":"18","bn":"আমি তোমাকে বলছি, তুমি পিতর, আর এই পাথরের উপরেই আমি আমার জামাত গড়ে তুলব। দোজখের কোন শক্তিই তার উপর জয়লাভ করতে পারবে না।"},{"v":19,"ve":19,"vl":"19","bn":"আমি তোমাকে বেহেশতী রাজ্যের চাবিগুলো দেব, আর তুমি এই দুনিয়াতে যা বাঁধবে তা বেহেশতেও বেঁধে রাখা হবে এবং যা খুলবে তা বেহেশতেও খুলে দেওয়া হবে।”"},{"v":20,"ve":20,"vl":"20","bn":"এর পরে তিনি তাঁর সাহাবীদের সাবধান করে দিলেন যেন তাঁরা কাউকে না বলেন যে, তিনিই মসীহ্‌।"},{"heading":"নিজের মৃত্যুর বিষয়ে হযরত ঈসা মসীহ্‌","v":21,"ve":21,"vl":"21","bn":"সেই সময় থেকে ঈসা তাঁর সাহাবীদের জানাতে লাগলেন যে, তাঁকে জেরুজালেমে যেতে হবে এবং বৃদ্ধ নেতাদের, প্রধান ইমামদের ও আলেমদের হাতে অনেক দুঃখভোগ করতে হবে। পরে তাঁকে হত্যা করা হবে এবং তৃতীয় দিনে মৃত্যু থেকে জীবিত হয়ে উঠতে হবে।"},{"v":22,"ve":22,"vl":"22","bn":"তখন পিতর তাঁকে একপাশে নিয়ে গিয়ে অনুযোগ করে বললেন, “হুজুর, এ দূর হোক। আপনার উপর কখনও এমন হবে না।”"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা ফিরে পিতরকে বললেন, “আমার কাছ থেকে দূর হও, শয়তান। তুমি আমার পথের বাধা। যা আল্লাহ্‌র তা তুমি ভাবছ না কিন্তু যা মানুষের তা-ই ভাবছ।”"},{"v":24,"ve":24,"vl":"24","bn":"এর পরে ঈসা তাঁর সাহাবীদের বললেন, “যদি কেউ আমার পথে আসতে চায় তবে সে নিজের ইচ্ছামত না চলুক; নিজের ক্রুশ বয়ে নিয়ে সে আমার পিছনে আসুক।"},{"v":25,"ve":25,"vl":"25","bn":"যে কেউ তাঁর নিজের জন্য বেঁচে থাকতে চায় সে তার সত্যিকারের জীবন হারাবে; কিন্তু যে কেউ আমার জন্য তার প্রাণ হারায় সে তার সত্যিকারের জীবন রক্ষা করবে।"},{"v":26,"ve":26,"vl":"26","bn":"যদি কেউ সমস্ত দুনিয়া লাভ করে তার বিনিময়ে তার সত্যিকারের জীবন হারায় তবে তার কি লাভ হল? সত্যিকারের জীবন ফিরে পাবার জন্য তার দেবার মত কি আছে?"},{"v":27,"ve":27,"vl":"27","bn":"ইব্‌ন্তেআদম তাঁর ফেরেশতাদের সংগে নিয়ে তাঁর পিতার মহিমায় আসছেন। তখন তিনি প্রত্যেক লোককে তার কাজ অনুসারে ফল দেবেন।"},{"v":28,"ve":28,"vl":"28","bn":"আমি তোমাদের সত্যিই বলছি, এখানে এমন কয়েকজন আছে যাদের কাছে ইব্‌ন্তেআদম বাদশাহ্‌ হিসাবে দেখা না দেওয়া পর্যন্ত তারা কোনমতেই মারা যাবে না।”"}],"17":[{"heading":"হযরত ঈসা মসীহের নূরানী চেহারা","v":1,"ve":1,"vl":"1","bn":"এর ছয় দিন পরে ঈসা কেবল পিতর, ইয়াকুব এবং ইয়াকুবের ভাই ইউহোন্নাকে সংগে নিয়ে একটা উঁচু পাহাড়ে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁদের সামনে ঈসার চেহারা বদলে গেল। তাঁর মুখ সূর্যের মত উজ্জ্বল এবং"},{"v":3,"ve":3,"vl":"3","bn":"তাঁর কাপড় আলোর মত সাদা হয়ে গেল। তাঁরা নবী মূসা এবং নবী ইলিয়াসকে ঈসার সংগে কথা বলতে দেখলেন।"},{"v":4,"ve":4,"vl":"4","bn":"তখন পিতর ঈসাকে বললেন, “হুজুর, ভালই হয়েছে যে, আমরা এখানে আছি। আপনি যদি চান তবে আমি এখানে তিনটা কুঁড়ে-ঘর তৈরী করব- একটা আপনার, একটা মূসার ও একটা ইলিয়াসের জন্য।”"},{"v":5,"ve":5,"vl":"5","bn":"পিতর যখন কথা বলছিলেন তখন একটা উজ্জ্বল মেঘ তাঁদের ঢেকে ফেলল। সেই মেঘ থেকে এই কথা শোনা গেল, “ইনিই আমার প্রিয় পুত্র, এঁর উপর আমি খুবই সন্তুষ্ট। তোমরা এঁর কথা শোন।”"},{"v":6,"ve":6,"vl":"6","bn":"এই কথা শুনে সাহাবীরা খুব ভয় পেয়ে মাটিতে উবুড় হয়ে পড়লেন।"},{"v":7,"ve":7,"vl":"7","bn":"তখন ঈসা এসে তাঁদের ছুঁয়ে বললেন, “ওঠো, ভয় কোরো না।”"},{"v":8,"ve":8,"vl":"8","bn":"তখন তাঁরা উপরের দিকে তাকিয়ে কেবল ঈসা ছাড়া আর কাউকে দেখতে পেলেন না।"},{"v":9,"ve":9,"vl":"9","bn":"যখন তাঁরা সেই পাহাড় থেকে নেমে আসছিলেন তখন ঈসা তাঁদের এই হুকুম দিলেন, “তোমরা যা দেখলে, ইব্‌ন্তেআদম মৃত্যু থেকে জীবিত হয়ে না ওঠা পর্যন্ত তা কাউকে বোলো না।”"},{"v":10,"ve":10,"vl":"10","bn":"সাহাবীরা তাঁকে জিজ্ঞাসা করলেন, “তাহলে আলেমেরা কেন বলেন যে, প্রথমে ইলিয়াস নবীর আসা দরকার?”"},{"v":11,"ve":11,"vl":"11","bn":"ঈসা তাঁদের জবাব দিলেন, “সত্যিই ইলিয়াস আসবেন এবং সব কিছু আগের অবস্থায় ফিরিয়ে আনবেন।"},{"v":12,"ve":12,"vl":"12","bn":"কিন্তু আমি তোমাদের বলছি, ইলিয়াস এসেছিলেন আর লোকে তাঁকে চিনতে পারে নি। লোকেরা তাঁর উপর যা ইচ্ছা তা-ই করেছে। এইভাবে ইব্‌ন্তেআদমকেও লোকদের হাতে কষ্টভোগ করতে হবে।”"},{"v":13,"ve":13,"vl":"13","bn":"তখন সাহাবীরা বুঝতে পারলেন যে, তিনি তাঁদের কাছে তরিকাবন্দীদাতা ইয়াহিয়ার বিষয় বলছেন।"},{"heading":"ভূতে পাওয়া ছেলেটি সুস্থ হল","v":14,"ve":14,"vl":"14","bn":"ঈসা ও তাঁর সাহাবীরা যখন লোকদের কাছে ফিরে আসলেন তখন একজন লোক এসে ঈসার সামনে হাঁটু পেতে বসে বলল,"},{"v":15,"ve":15,"vl":"15","bn":"“হুজুর, আপনি আমার ছেলেটির উপর দয়া করুন। সে মৃগী রোগে খুব কষ্ট পাচ্ছে। প্রায়ই সে আগুনে এবং পানিতে পড়ে যায়।"},{"v":16,"ve":16,"vl":"16","bn":"আমি তাকে আপনার সাহাবীদের কাছে এনেছিলাম কিন্তু তাঁরা তাকে ভাল করতে পারলেন না।”"},{"v":17,"ve":17,"vl":"17","bn":"জবাবে ঈসা বললেন, “বেঈমান ও দুষ্ট লোকেরা! আর কতকাল আমি তোমাদের সংগে সংগে থাকব? কতদিন তোমাদের সহ্য করব? ছেলেটিকে এখানে আমার কাছে আন।”"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা সেই ভূতকে ধমক দিলে পর সে ছেলেটির মধ্য থেকে বের হয়ে গেল, আর ছেলেটি তখনই সুস্থ হল।"},{"v":19,"ve":19,"vl":"19","bn":"এর পর সাহাবীরা গোপনে ঈসার কাছে এসে বললেন, “আমরা কেন সেই ভূতকে ছাড়াতে পারলাম না?”"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা তাঁদের বললেন, “তোমাদের অল্প বিশ্বাসের জন্যই পারলে না। আমি তোমাদের সত্যিই বলছি, যদি একটা সরিষা দানার মত বিশ্বাসও তোমাদের থাকে তবে তোমরা এই পাহাড়কে বলবে, ‘এখান থেকে সরে ওখানে যাও,’ আর তাতে ওটা সরে যাবে। তোমাদের পক্ষে কিছুই অসম্ভব হবে না।"},{"v":21,"ve":21,"vl":"21","bn":"মুনাজাত ও রোজা ছাড়া এই রকম ভূত আর কিছুতে বের হয় না।"},{"v":22,"ve":22,"vl":"22","bn":"পরে গালীল দেশের মধ্য দিয়ে যাবার সময় ঈসা তাঁর সাহাবীদের বললেন, “ইব্‌ন্তেআদমকে লোকদের হাতে ধরিয়ে দেওয়া হবে।"},{"v":23,"ve":23,"vl":"23","bn":"লোকেরা তাঁকে হত্যা করবে, আর তৃতীয় দিনে তিনি মৃত্যু থেকে জীবিত হয়ে উঠবেন।” এতে সাহাবীরা খুব দুঃখিত হলেন।"},{"heading":"মাছের মুখে রূপার টাকা","v":24,"ve":24,"vl":"24","bn":"পরে ঈসা ও তাঁর সাহাবীরা যখন কফরনাহূমে গেলেন তখন বায়তুল-মোকাদ্দসের খাজনা-আদায়কারীরা পিতরের কাছে এসে বললেন, “আপনাদের ওস্তাদ কি বায়তুল-মোকাদ্দসের খাজনা দেন না?”"},{"v":25,"ve":25,"vl":"25","bn":"পিতর বললেন “জ্বী, দেন।” এর পর পিতর ঘরে এসে কিছু বলবার আগেই ঈসা তাঁকে বললেন, “শিমোন, তোমার কি মনে হয়? এই দুনিয়ার বাদশাহ্‌রা কাদের কাছ থেকে কর্‌ বা খাজনা আদায় করে থাকেন? নিজের দেশের লোকদের কাছ থেকে, না বিদেশীদের কাছ থেকে?”"},{"v":26,"ve":26,"vl":"26","bn":"পিতর বললেন, “বিদেশীদের কাছ থেকে।” তখন ঈসা তাঁকে বললেন, “তাহলে তো নিজের দেশের লোকেরা রেহাই পেয়ে গেছে।"},{"v":27,"ve":27,"vl":"27","bn":"কিন্তু আমাদের ব্যবহারে খাজনা-আদায়কারীরা যেন অপমান বোধ না করে এইজন্য তুমি সাগরে গিয়ে বড়শী ফেল, আর প্রথমে যে মাছটা উঠবে তার মুখ খুললে একটা রূপার টাকা পাবে। ওটা নিয়ে গিয়ে তোমার আর আমার খাজনা দিয়ে এস।”"}],"18":[{"heading":"বড় কে?","v":1,"ve":1,"vl":"1","bn":"সেই সময়ে সাহাবীরা ঈসার কাছে এসে বললেন, “বেহেশতী রাজ্যের মধ্যে সবচেয়ে বড় কে?”"},{"v":2,"ve":2,"vl":"2","bn":"তখন ঈসা একটা শিশুকে ডেকে তাঁদের মধ্যে দাঁড় করিয়ে বললেন,"},{"v":3,"ve":3,"vl":"3","bn":"“আমি তোমাদের সত্যিই বলছি, যদি তোমরা মন ফিরিয়ে শিশুদের মত না হও তবে কোনমতেই বেহেশতী রাজ্যে ঢুকতে পারবে না।"},{"v":4,"ve":4,"vl":"4","bn":"যে কেউ এই শিশুর মত নিজেকে নম্র করে সে-ই বেহেশতী রাজ্যের মধ্যে সবচেয়ে বড়।"},{"v":5,"ve":5,"vl":"5","bn":"আর যে কেউ এর মত কোন শিশুকে আমার নামে গ্রহণ করে সে আমাকেই গ্রহণ করে।"},{"heading":"গুনাহের পথে নিয়ে যাওয়া","v":6,"ve":6,"vl":"6","bn":"“আমার উপর ঈমানদার এই ছোটদের মধ্যে কাউকে যদি কেউ গুনাহের পথে নিয়ে যায় তবে তার গলায় একটা বড় পাথর বেঁধে তাকে সাগরের গভীর পানিতে ডুবিয়ে দেওয়া বরং তার পক্ষে ভাল।"},{"v":7,"ve":7,"vl":"7","bn":"ঘৃণ্য দুনিয়া! গুনাহের পথে নিয়ে যাবার জন্য কত উসকানিই না তোমার মধ্যে আছে! অবশ্য সেই সব উসকানি আসবেই; তবুও ঘৃণ্য সেই লোক, যার মধ্য দিয়ে সেই উসকানি আসে!"},{"v":8,"ve":8,"vl":"8","bn":"“তোমার হাত কিংবা পা যদি তোমাকে গুনাহের পথে টানে তবে তা কেটে ফেলে দাও। দুই হাত ও দুই পা নিয়ে চিরকালের আগুনে পড়বার চেয়ে বরং নুলা বা খোঁড়া হয়ে জীবনে ঢোকা তোমার পক্ষে ভাল।"},{"v":9,"ve":9,"vl":"9","bn":"তোমার চোখ যদি তোমাকে গুনাহের পথে টানে তবে তা উপ্‌ড়ে ফেলে দাও। দুই চোখ নিয়ে জাহান্নামের আগুনে পড়বার চেয়ে বরং কানা হয়ে জীবনে ঢোকা তোমার পক্ষে ভাল।"},{"v":10,"ve":10,"vl":"10","bn":"“দেখো, তোমরা যেন এই ছোটদের মধ্যে একজনকেও তুচ্ছ না কর। আমি তোমাদের বলছি, বেহেশতে তাদের ফেরেশতারা সব সময় আমার বেহেশতী পিতার মুখ দেখছেন।"},{"v":11,"ve":11,"vl":"11","bn":"“যা হারিয়ে গেছে তা উদ্ধার করবার জন্য ইব্‌ন্তেআদম এসেছেন।"},{"v":12,"ve":12,"vl":"12","bn":"তোমরা কি মনে কর? ধর, একজন লোকের একশোটা ভেড়া আছে। সেগুলোর মধ্যে যদি একটা ভুল পথে চলে যায় তবে সে কি নিরানব্বইটা পাহাড়ের ধারে রেখে সেই ভেড়াটা খুঁজতে যায় না?"},{"v":13,"ve":13,"vl":"13","bn":"আমি তোমাদের সত্যিই বলছি, যদি সে সেটা পায় তবে যে নিরানব্বইটা ভুল পথে যায় নি, তাদের চেয়ে যেটা ভুল পথে চলে গিয়েছিল তার জন্য সে আরও বেশী আনন্দ করে।"},{"v":14,"ve":14,"vl":"14","bn":"ঠিক সেইভাবে, তোমাদের বেহেশতী পিতার ইচ্ছা নয় যে, এই ছোটদের মধ্যে একজনও নষ্ট হয়।"},{"heading":"দোষী ভাইয়ের প্রতি কর্তব্য","v":15,"ve":15,"vl":"15","bn":"“তোমার ভাই যদি তোমার বিরুদ্ধে অন্যায় করে তবে তার কাছে গিয়ে যখন আর কেউ থাকবে না তখন তার দোষ দেখিয়ে দিয়ো। যদি সে তোমার কথা শোনে তবে তুমি তো তোমার ভাইকে ফিরে পেলে।"},{"v":16,"ve":16,"vl":"16","bn":"কিন্তু যদি সে না শোনে তবে অন্য দু’একজনকে তোমার সংগে নিয়ে যেয়ো, যেন দুই বা তিনজন সাক্ষীর কথায় এই সব বিষয় সত্য বলে প্রমাণিত হয়।"},{"v":17,"ve":17,"vl":"17","bn":"যদি সে তাদের কথা না শোনে তবে জামাতকে বোলো। সে যদি জামাতের কথাও না শোনে তবে সে তোমার কাছে অ-ইহুদী বা খাজনা-আদায়কারীর মত হোক।"},{"v":18,"ve":18,"vl":"18","bn":"“আমি তোমাদের সত্যিই বলছি, তোমরা দুনিয়াতে যা বাঁধবে তা বেহেশতেও বেঁধে রাখা হবে, আর যা খুলবে তা বেহেশতেও খুলে দেওয়া হবে।"},{"v":19,"ve":19,"vl":"19","bn":"“আমি তোমাদের আরও বলছি, তোমাদের মধ্যে দু’জন যদি একমত হয়ে কোন বিষয়ে মুনাজাত করে তবে আমার বেহেশতী পিতা তোমাদের জন্য তা করবেন,"},{"v":20,"ve":20,"vl":"20","bn":"কারণ যেখানে দুই বা তিনজন আমার নামে জমায়েত হয় সেখানে আমি তাদের মধ্যে উপস্থিত থাকি।”"},{"heading":"মাফের বিষয়ে শিক্ষা","v":21,"ve":21,"vl":"21","bn":"তখন পিতর এসে ঈসাকে বললেন, “হুজুর, আমার ভাই আমার বিরুদ্ধে অন্যায় করলে আমি কতবার তাকে মাফ করব? সাত বার কি?”"},{"v":22,"ve":22,"vl":"22","bn":"ঈসা তাঁকে বললেন, “কেবল সাত বার নয়, কিন্তু আমি তোমাকে সত্তর গুণ সাত বার পর্যন্ত মাফ করতে বলি।"},{"v":23,"ve":23,"vl":"23","bn":"“দেখ, বেহেশতী রাজ্য এমন একজন বাদশাহ্‌র মত যিনি তাঁর কর্মচারীদের কাছে হিসাব চাইলেন।"},{"v":24,"ve":24,"vl":"24","bn":"তিনি যখন হিসাব নিতে শুরু করলেন তখন তাদের মধ্য থেকে এমন একজন কর্মচারীকে আনা হল, বাদশাহ্‌র কাছে যার লক্ষ লক্ষ টাকা ঋণ ছিল।"},{"v":25,"ve":25,"vl":"25","bn":"তার ঋণ শোধ করবার ক্ষমতা ছিল না। তখন সেই মালিক হুকুম করলেন যেন সেই লোককে এবং তার স্ত্রী ও ছেলেমেয়েকে আর তার যা কিছু আছে সমস্ত বিক্রি করে পাওনা আদায় করা হয়।"},{"v":26,"ve":26,"vl":"26","bn":"তাতে সেই কর্মচারী মাটিতে পড়ে মালিকের পা ধরে বলল, ‘হুজুর, আমার উপর ধৈর্য ধরুন, আপনাকে আমি সমস্তই শোধ করে দেব।’"},{"v":27,"ve":27,"vl":"27","bn":"তখন মালিক মমতা করে সেই কর্মচারীকে ছেড়ে দিলেন এবং তার ঋণ মাফ করে দিলেন।"},{"v":28,"ve":28,"vl":"28","bn":"“পরে সেই কর্মচারী বাইরে গিয়ে তার একজন সংগী-কর্মচারীকে দেখতে পেল। তার কাছে সেই সংগী-কর্মচারীটির প্রায় একশো টাকা ঋণ ছিল। সেই কর্মচারী তার সংগীর গলা টিপে ধরে বলল, ‘তুই যে টাকা ধার করেছিস্‌ তা শোধ কর্‌।’"},{"v":29,"ve":29,"vl":"29","bn":"“সংগী-কর্মচারীটি তখন তার পায়ে পড়ে তাকে অনুরোধ করে বলল, ‘আমার উপর ধৈর্য ধর, আমি সব শোধ করে দেব।’"},{"v":30,"ve":30,"vl":"30","bn":"কিন্তু সে রাজী হল না বরং ঋণ শোধ না করা পর্যন্ত তাকে জেলখানায় আটক রাখল।"},{"v":31,"ve":31,"vl":"31","bn":"“এই সব ঘটনা দেখে তার অন্য সংগী-কর্মচারীরা খুব দুঃখিত হল। তারা গিয়ে তাদের মালিকের কাছে সব কথা জানাল।"},{"v":32,"ve":32,"vl":"32","bn":"তখন মালিক সেই কর্মচারীকে ডেকে বললেন, ‘দুষ্ট কর্মচারী! তুমি আমাকে অনুরোধ করেছিলে বলে আমি তোমার সব ঋণ মাফ করেছিলাম।"},{"v":33,"ve":33,"vl":"33","bn":"আমি যেমন তোমাকে দয়া করেছিলাম তেমনি তোমার সংগী-কর্মচারীকে দয়া করা কি তোমার উচিত ছিল না?’"},{"v":34,"ve":34,"vl":"34","bn":"পরে তার মালিক রাগ করে তার সমস্ত ঋণ শোধ না করা পর্যন্ত তাকে কষ্ট দেবার জন্য জেলখানার লোকদের হাতে তুলে দিলেন।"},{"v":35,"ve":35,"vl":"35","bn":"“ঠিক সেইভাবে, তোমরা প্রত্যেকে যদি তোমাদের ভাইকে অন্তর দিয়ে মাফ না কর তবে আমার বেহেশতী পিতাও তোমাদের উপর এই রকম করবেন।”"}],"19":[{"heading":"তালাক দেবার বিষয়ে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"এই সব কথা বলা শেষ করে ঈসা গালীল প্রদেশ ছেড়ে জর্ডান নদীর অন্য পারে এহুদিয়া প্রদেশে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"অনেক লোক তাঁর পিছনে পিছনে গেল আর তিনি সেখানে তাদের সুস্থ করলেন।"},{"v":3,"ve":3,"vl":"3","bn":"তখন কয়েকজন ফরীশী ঈসাকে পরীক্ষা করবার জন্য তাঁর কাছে এসে বললেন, “মূসার শরীয়ত মতে যে কোন কারণে স্ত্রীকে তালাক দেওয়া কি কারও পক্ষে উচিত?”"},{"v":4,"ve":4,"vl":"4","bn":"জবাবে ঈসা বললেন, “আপনারা কি পড়েন নি, সৃষ্টিকর্তা প্রথমে তাঁদের পুরুষ ও স্ত্রীলোক করে সৃষ্টি করেছিলেন আর বলেছিলেন,"},{"v":5,"ve":5,"vl":"5","bn":"‘এইজন্যই মানুষ পিতা-মাতাকে ছেড়ে তার স্ত্রীর সংগে এক হয়ে থাকবে আর তারা দু’জন একশরীর হবে’?"},{"v":6,"ve":6,"vl":"6","bn":"এইজন্য তারা আর দুই নয়, কিন্তু একশরীর। তাই আল্লাহ্‌ যা একসংগে যোগ করেছেন মানুষ তা আলাদা না করুক।”"},{"v":7,"ve":7,"vl":"7","bn":"তখন ফরীশীরা তাঁকে বললেন, “তাহলে নবী মূসা কেন তালাক-নামা দিয়ে স্ত্রীকে তালাক দিতে হুকুম দিয়েছেন?”"},{"v":8,"ve":8,"vl":"8","bn":"ঈসা তাদের বললেন, “আপনাদের মন কঠিন বলেই স্ত্রীকে তালাক দিতে মূসা আপনাদের অনুমতি দিয়েছেন। কিন্তু প্রথম থেকে এই রকম ছিল না।"},{"v":9,"ve":9,"vl":"9","bn":"আমি আপনাদের বলছি, যে কেউ জেনার দোষ ছাড়া অন্য কোন কারণে স্ত্রীকে তালাক দিয়ে অন্যকে বিয়ে করে সে জেনা করে।”"},{"v":10,"ve":10,"vl":"10","bn":"তখন তাঁর সাহাবীরা তাঁকে বললেন, “স্বামী-স্ত্রীর সম্বন্ধ যদি এই রকমেরই হয় তাহলে তো বিয়ে না করাই ভাল।”"},{"v":11,"ve":11,"vl":"11","bn":"ঈসা তাঁদের বললেন, “সবাই এই কথা মেনে নিতে পারে না; কেবল যাদের সেই ক্ষমতা দেওয়া হয়েছে তারাই তা মেনে নিতে পারে।"},{"v":12,"ve":12,"vl":"12","bn":"কেউ কেউ খোজা হয়ে জন্মগ্রহণ করে, সেইজন্য তারা বিয়ে করে না। আর কাউকে কাউকে মানুষেই খোজা করে, সেইজন্য তারা বিয়ে করে না। আবার এমন কেউ কেউ আছে যারা বেহেশতী রাজ্যের জন্য বিয়ে করবে না বলে মন স্থির করে। যে এই কথা মেনে নিতে পারে সে মেনে নিক।”"},{"heading":"হযরত ঈসা মসীহ্‌ ও ছেলেমেয়েরা","v":13,"ve":13,"vl":"13","bn":"পরে লোকেরা ছোট ছোট ছেলেমেয়েদের ঈসার কাছে নিয়ে আসল যেন তিনি তাদের মাথার উপর হাত রেখে মুনাজাত করেন। কিন্তু সাহাবীরা তাদের বকুনি দিতে লাগলেন।"},{"v":14,"ve":14,"vl":"14","bn":"তখন ঈসা বললেন, “ছেলেমেয়েদের আমার কাছে আসতে দাও, বাধা দিয়ো না; কারণ বেহেশতী রাজ্য এদের মত লোকদেরই।”"},{"v":15,"ve":15,"vl":"15","bn":"ছেলেমেয়েদের মাথার উপর হাত রেখে মুনাজাত করবার পর ঈসা সেখান থেকে চলে গেলেন।"},{"heading":"একজন ধনী যুবক","v":16,"ve":16,"vl":"16","bn":"পরে একজন যুবক এসে ঈসাকে বলল, “হুজুর, অনন্ত জীবন পাবার জন্য আমাকে ভাল কি করতে হবে?”"},{"v":17,"ve":17,"vl":"17","bn":"ঈসা তাকে বললেন, “ভালোর বিষয়ে কেন আমাকে জিজ্ঞাসা করছ? ভাল মাত্র একজনই আছেন। যদি তুমি অনন্ত জীবন পেতে চাও তবে তাঁর সব হুকুম পালন কর।”"},{"v":18,"ve":18,"vl":"18","bn":"সেই যুবকটি বলল, “কোন্‌ কোন্‌ হুকুম?” ঈসা বললেন, “খুন কোরো না, জেনা কোরো না, চুরি কোরো না, মিথ্যা সাক্ষ্য দিয়ো না,"},{"v":19,"ve":19,"vl":"19","bn":"পিতা-মাতাকে সম্মান কোরো আর তোমার প্রতিবেশীকে নিজের মত মহব্বত কোরো।”"},{"v":20,"ve":20,"vl":"20","bn":"সেই যুবকটি ঈসাকে বলল, “আমি এগুলো সবই পালন করে আসছি, তবে আমাকে আর কি করতে হবে?”"},{"v":21,"ve":21,"vl":"21","bn":"ঈসা তাকে বললেন, “যদি তুমি পুরোপুরি খাঁটি হতে চাও তবে গিয়ে তোমার সমস্ত সম্পত্তি বিক্রি করে গরীবদের দান কর। তাতে তুমি বেহেশতে ধন পাবে। তারপর এসে আমার উম্মত হও।”"},{"v":22,"ve":22,"vl":"22","bn":"এই কথা শুনে যুবকটি খুব দুঃখিত হয়ে চলে গেল, কারণ তার অনেক ধন-সম্পত্তি ছিল।"},{"v":23,"ve":23,"vl":"23","bn":"তখন ঈসা তাঁর সাহাবীদের বললেন, “আমি তোমাদের সত্যিই বলছি, ধনী লোকের পক্ষে বেহেশতী রাজ্যে ঢোকা কঠিন হবে।"},{"v":24,"ve":24,"vl":"24","bn":"আমি আবার তোমাদের বলছি, ধনী লোকের পক্ষে আল্লাহ্‌র রাজ্যে ঢুকবার চেয়ে বরং সূচের ফুটা দিয়ে উটের ঢোকা সহজ।”"},{"v":25,"ve":25,"vl":"25","bn":"এই কথা শুনে সাহাবীরা আশ্চর্য হয়ে বললেন, “তাহলে কে নাজাত পেতে পারে?”"},{"v":26,"ve":26,"vl":"26","bn":"ঈসা সাহাবীদের দিকে তাকিয়ে বললেন, “মানুষের পক্ষে এটা অসম্ভব বটে, কিন্তু আল্লাহ্‌র পক্ষে সবই সম্ভব।”"},{"v":27,"ve":27,"vl":"27","bn":"তখন পিতর তাঁকে বললেন, “দেখুন, আমরা সব কিছু ছেড়ে আপনার সাহাবী হয়েছি; আমরা কি পাব?”"},{"v":28,"ve":28,"vl":"28","bn":"ঈসা তাঁদের বললেন, “আমি তোমাদের সত্যিই বলছি, তোমরা যারা আমার সাহাবী হয়েছ, নতুন সৃষ্টিতে যখন ইব্‌ন্তেআদম তাঁর সম্মানের সিংহাসনে বসবেন তখন তোমরাও বারোটা সিংহাসনে বসবে এবং ইসরাইলের বারো বংশের বিচার করবে।"},{"v":29,"ve":29,"vl":"29","bn":"আর যে কেউ আমার জন্য বাড়ী-ঘর, ভাই-বোন, মা-বাবা, ছেলে-মেয়ে কিংবা জায়গা-জমি ছেড়ে দিয়েছে, সে তার একশো গুণ বেশী পাবে আর অনন্ত জীবনও পাবে।"},{"v":30,"ve":30,"vl":"30","bn":"যারা প্রথম সারিতে আছে তাদের মধ্যে অনেকে শেষে পড়বে, আর যারা শেষের সারিতে আছে তাদের মধ্যে অনেকে প্রথম হবে।"}],"20":[{"heading":"আংগুর ক্ষেতের মজুরেরা","v":1,"ve":1,"vl":"1","bn":"“বেহেশতী রাজ্য একজন গৃহসে'র মত। তিনি একদিন সকালবেলায় ক্ষেতের কাজে মজুর লাগাবার জন্য বাইরে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তিনি মজুরদের সংগে ঠিক করলেন যে, দিনে এক দীনার করে দেবেন। এর পর তিনি তাদের তাঁর আংগুর ক্ষেতে পাঠিয়ে দিলেন।"},{"v":3,"ve":3,"vl":"3","bn":"প্রায় ন’টার সময় আবার তিনি বাইরে গেলেন এবং বাজারে আরও কয়েকজন বিনা কাজে দাঁড়িয়ে থাকতে দেখলেন।"},{"v":4,"ve":4,"vl":"4","bn":"তিনি তাদের বললেন, ‘তোমরাও আমার আংগুর ক্ষেতে কাজ করতে যাও। আমি তোমাদের উপযুক্ত মজুরি দেব।’"},{"v":5,"ve":5,"vl":"5","bn":"তাতে সেই লোকেরাও কাজ করতে গেল। “সেই গৃহস' আবার প্রায় বারোটায় এবং তিনটায় বাইরে গিয়ে ঐ একই রকম করলেন।"},{"v":6,"ve":6,"vl":"6","bn":"প্রায় পাঁচটার সময় বাইরে গিয়ে অন্য কয়েকজনকে দাঁড়িয়ে থাকতে দেখে তিনি তাদের বললেন, ‘তোমরা কাজ না করে সারাদিন এখানে দাঁড়িয়ে আছ কেন?’"},{"v":7,"ve":7,"vl":"7","bn":"“তারা তাঁকে বলল, ‘কেউ আমাদের কাজে লাগায় নি।’ “তিনি সেই লোকদের বললেন, ‘তোমরাও আমার আংগুর ক্ষেতের কাজে যাও।’"},{"v":8,"ve":8,"vl":"8","bn":"“পরে সন্ধ্যা হলে আংগুর ক্ষেতের মালিক তাঁর কর্মচারীকে বললেন, ‘মজুরদের ডেকে শেষ জন থেকে শুরু করে প্রথম জন পর্যন্ত প্রত্যেককে মজুরি দাও।’"},{"v":9,"ve":9,"vl":"9","bn":"“বিকাল পাঁচটার সময় যে মজুরদের কাজে লাগানো হয়েছিল তারা এসে প্রত্যেকে এক এক দীনার করে নিয়ে গেল।"},{"v":10,"ve":10,"vl":"10","bn":"এতে যাদের প্রথমে কাজে লাগানো হয়েছিল তারা বেশী পাবে বলে মনে করল, কিন্তু তারাও প্রত্যেকে এক এক দীনার করেই পেল।"},{"v":11,"ve":11,"vl":"11","bn":"তাতে তারা সেই মালিকের বিরুদ্ধে বিরক্তি প্রকাশ করে বলতে লাগল,"},{"v":12,"ve":12,"vl":"12","bn":"‘আমরা সারা দিন রোদে পুড়ে কাজ করেছি। কিন্তু যাদের শেষে কাজে লাগানো হয়েছিল তারা মাত্র এক ঘণ্টা কাজ করেছে, অথচ তাদের আপনি আমাদের সমান মজুরি দিলেন।’"},{"v":13,"ve":13,"vl":"13","bn":"“তখন মালিক তাদের মধ্যে একজনকে বললেন, ‘বন্ধু, আমি তোমার উপর তো অন্যায় করি নি। তুমি কি এক দীনারে কাজ করতে রাজী হও নি?"},{"v":14,"ve":14,"vl":"14","bn":"তোমার পাওনা নিয়ে চলে যাও। তোমাকে যেমন দিয়েছি, এই শেষের জনকেও তেমনই দিতে আমার ইচ্ছা।"},{"v":15,"ve":15,"vl":"15","bn":"যা আমার নিজের, তা আমার খুশীমত ব্যবহার করবার অধিকার কি আমার নেই? নাকি আমি দয়ালু বলে তোমার চোখ টাটাচ্ছে?’ ”"},{"v":16,"ve":16,"vl":"16","bn":"গল্পের শেষে ঈসা বললেন, “এইভাবেই শেষে যারা তারা প্রথম হবে, আর প্রথম যারা তারা শেষে পড়বে।”"},{"heading":"আবার তাঁর মৃত্যুর কথা","v":17,"ve":17,"vl":"17","bn":"পরে ঈসা জেরুজালেমে যাবার পথে তাঁর বারোজন সাহাবীকে এক পাশে ডেকে নিয়ে গিয়ে বললেন,"},{"v":18,"ve":18,"vl":"18","bn":"“দেখ, আমরা জেরুজালেমে যাচ্ছি। সেখানে ইব্‌ন্তেআদমকে প্রধান ইমামদের ও আলেমদের হাতে ধরিয়ে দেওয়া হবে।"},{"v":19,"ve":19,"vl":"19","bn":"তাঁরা তাঁর বিচার করে তাঁকে মৃত্যুর উপযুক্ত বলে স্থির করবেন। তাঁরা তাঁকে ঠাট্টা-বিদ্রূপ করবার জন্য এবং চাবুক মারবার ও ক্রুশের উপরে হত্যা করবার জন্য অ-ইহুদীদের হাতে দেবেন; পরে তৃতীয় দিনে তিনি মৃত্যু থেকে জীবিত হয়ে উঠবেন।”"},{"heading":"সন্তানদের জন্য মায়ের অনুরোধ","v":20,"ve":20,"vl":"20","bn":"পরে সিবদিয়ের দুই ছেলেকে তাঁদের মা সংগে করে নিয়ে ঈসার কাছে আসলেন এবং তাঁর কাছে কিছু চাইবার উদ্দেশ্যে তাঁর সামনে উবুড় হয়ে পড়লেন।"},{"v":21,"ve":21,"vl":"21","bn":"ঈসা তাঁকে বললেন, “আপনি কি চান?” তিনি বললেন, “আপনি এই হুকুম দিন যেন আপনার রাজ্যে আমার এই দুই ছেলের একজন আপনার ডান পাশে আর একজন বাঁ পাশে বসতে পায়।”"},{"v":22,"ve":22,"vl":"22","bn":"জবাবে ঈসা বললেন, “তোমরা কি চাইছ তা জান না। যে দুঃখের পেয়ালায় আমি খেতে যাচ্ছি তাতে কি তোমরা খেতে পার?” তাঁরা তাঁকে বললেন, “পারি।”"},{"v":23,"ve":23,"vl":"23","bn":"তখন ঈসা তাঁদের বললেন, “সত্যিই তোমরা আমার পেয়ালায় খাবে, কিন্তু আমার ডানে বা বাঁয়ে বসতে দেবার অধিকার আমার নেই। আমার পিতা যাদের জন্য তা ঠিক করে রেখেছেন তারাই তা পাবে।”"},{"v":24,"ve":24,"vl":"24","bn":"এই সব কথা শুনে বাকী দশজন সাহাবী সেই দুই ভাইয়ের উপর বিরক্ত হলেন।"},{"v":25,"ve":25,"vl":"25","bn":"তখন ঈসা সাহাবীদের ডেকে বললেন, “তোমরা এই কথা জান যে, অ-ইহুদীদের মধ্যে শাসনকর্তারা তাদের প্রভু হয় এবং নেতারা তাদের উপর হুকুম চালায়।"},{"v":26,"ve":26,"vl":"26","bn":"কিন্তু তোমাদের মধ্যে তা হওয়া উচিত নয়। তোমাদের মধ্যে যে বড় হতে চায় তাকে তোমাদের সেবাকারী হতে হবে,"},{"v":27,"ve":27,"vl":"27","bn":"আর যে প্রথম হতে চায় তাকে তোমাদের গোলাম হতে হবে।"},{"v":28,"ve":28,"vl":"28","bn":"“মনে রেখো, ইব্‌নে-আদম সেবা পেতে আসেন নি বরং সেবা করতে এসেছেন এবং অনেক লোকের মুক্তির মূল্য হিসাবে তাদের প্রাণের পরিবর্তে নিজের প্রাণ দিতে এসেছেন।”"},{"heading":"হযরত ঈসা মসীহ্‌ ও দু’জন অন্ধ","v":29,"ve":29,"vl":"29","bn":"ঈসা ও তাঁর সাহাবীরা জেরিকো শহর ছেড়ে যাবার সময় অনেক লোক তাঁর পিছনে পিছনে চলল।"},{"v":30,"ve":30,"vl":"30","bn":"পথের ধারে দু’জন অন্ধ লোক বসে ছিল। ঈসা সেই পথ দিয়ে যাচ্ছেন শুনে তারা চিৎকার করে বলল, “হুজুর, দাউদের বংশধর, আমাদের দয়া করুন।”"},{"v":31,"ve":31,"vl":"31","bn":"তারা যেন চুপ করে সেইজন্য লোকেরা তাদের ধমক দিল। কিন্তু তারা আরও চিৎকার করে বলল, “হুজুর, দাউদের বংশধর, আমাদের দয়া করুন।”"},{"v":32,"ve":32,"vl":"32","bn":"তখন ঈসা দাঁড়ালেন এবং তাদের ডেকে বললেন, “তোমরা কি চাও? আমি তোমাদের জন্য কি করব?”"},{"v":33,"ve":33,"vl":"33","bn":"তারা তাঁকে বলল, “হুজুর, আমাদের চোখ খুলে দিন।”"},{"v":34,"ve":34,"vl":"34","bn":"তখন ঈসা মমতায় পূর্ণ হয়ে তাদের চোখ ছুঁলেন, আর তখনই তারা দেখতে পেল এবং তাঁর পিছনে পিছনে চলল।"}],"21":[{"heading":"জেরুজালেমে প্রবেশ","v":1,"ve":1,"vl":"1","bn":"ঈসা ও তাঁর সাহাবীরা জেরুজালেমের কাছাকাছি পৌঁছে জৈতুন পাহাড়ের উপরে বৈৎফগী গ্রামের কাছে আসলেন। তখন ঈসা দু’জন সাহাবীকে এই বলে পাঠিয়ে দিলেন,"},{"v":2,"ve":2,"vl":"2","bn":"“তোমরা ঐ সামনের গ্রামে যাও। সেখানে গেলেই দেখতে পাবে একটা গাধা বাঁধা আছে এবং একটা বাচ্চাও তার সংগে আছে। সেই দু’টা খুলে আমার কাছে নিয়ে এস।"},{"v":3,"ve":3,"vl":"3","bn":"কেউ যদি কিছু বলে তবে বোলো, ‘হুজুরের দরকার আছে।’ তাতে তখনই সে তাদের ছেড়ে দেবে।”"},{"v":4,"ve":4,"vl":"4","bn":"এটা হল যেন নবীর মধ্য দিয়ে এই যে কথা বলা হয়েছিল তা পূর্ণ হয়:"},{"v":5,"ve":5,"vl":"5","bn":"“তোমরা সিয়োন্তকন্যাকে বল, তোমার বাদশাহ্‌ তোমার কাছে আসছেন। তিনি নম্র। তিনি গাধার উপরে, গাধীর বাচ্চার উপরে চড়ে আসছেন।”"},{"v":6,"ve":6,"vl":"6","bn":"ঈসা সেই সাহাবীদের যেমন হুকুম দিয়েছিলেন তাঁরা গিয়ে তেমনি করলেন।"},{"v":7,"ve":7,"vl":"7","bn":"তাঁরা সেই গাধা ও গাধীর বাচ্চাটা এনে তাদের উপর নিজেদের গায়ের চাদর পেতে দিলে পর ঈসা বসলেন।"},{"v":8,"ve":8,"vl":"8","bn":"অনেক লোক পথের উপরে তাদের গায়ের চাদর বিছিয়ে দিল। অন্যেরা গাছের ডাল কেটে নিয়ে পথের উপরে ছড়াল।"},{"v":9,"ve":9,"vl":"9","bn":"যারা ঈসার সামনে ও পিছনে যাচ্ছিল তারা চিৎকার করে বলতে লাগল, “মারহাবা, দাউদের বংশধর! মাবুদের নামে যিনি আসছেন তাঁর প্রশংসা হোক। বেহেশতেও মারহাবা!”"},{"v":10,"ve":10,"vl":"10","bn":"ঈসা জেরুজালেমে ঢুকলে পর শহরের সমস্ত জায়গায় হুলস'ূল পড়ে গেল। সবাই জিজ্ঞাসা করতে লাগল, “ইনি কে?”"},{"v":11,"ve":11,"vl":"11","bn":"লোকেরা বলল, “উনি গালীলের নাসরত গ্রামের ঈসা নবী।”"},{"heading":"পবিত্র বায়তুল-মোকাদ্দসে হযরত ঈসা মসীহ্‌","v":12,"ve":12,"vl":"12","bn":"পরে ঈসা বায়তুল-মোকাদ্দসে ঢুকলেন এবং সেখানে যারা কেনা-বেচা করছিল তাদের সবাইকে তাড়িয়ে দিলেন। তিনি টাকা বদল করে দেবার লোকদের টেবিল এবং যারা কবুতর বিক্রি করছিল তাদের বসবার জায়গা উল্টে দিয়ে বললেন,"},{"v":13,"ve":13,"vl":"13","bn":"“পাক-কিতাবে আল্লাহ্‌ বলেছেন, ‘আমার ঘরকে এবাদত-ঘর বলা হবে,’ কিন্তু তোমরা এটাকে ডাকাতের আড্ডাখানা করে তুলছ।”"},{"v":14,"ve":14,"vl":"14","bn":"এর পরে অন্ধ ও খোঁড়া লোকেরা বায়তুল-মোকাদ্দসে ঈসার কাছে আসল, আর তিনি তাদের সুস্থ করলেন।"},{"v":15,"ve":15,"vl":"15","bn":"তিনি যে সব অলৌকিক চিহ্ন-কাজ করছিলেন প্রধান ইমামেরা ও আলেমেরা তা দেখলেন। তাঁরা বায়তুল-মোকাদ্দসের মধ্যে ছেলেমেয়েদের চিৎকার করে বলতে শুনলেন, “মারহাবা, দাউদের বংশধর!”"},{"v":16,"ve":16,"vl":"16","bn":"এই সব দেখে-শুনে তারা বিরক্ত হয়ে ঈসাকে বললেন, “ওরা যা বলছে তা তুমি শুনতে পাচ্ছ?” তিনি তাঁদের বললেন, “জ্বী, পাচ্ছি। পাক-কিতাবে আপনারা কি কখনও পড়েন নি: ছোট ছেলেমেয়ে এবং শিশুদের কথার মধ্যে তুমি নিজের জন্য প্রশংসার ব্যবস্থা করেছ?”"},{"v":17,"ve":17,"vl":"17","bn":"এর পরে ঈসা তাঁদের ছেড়ে শহরের বাইরে বেথানিয়া গ্রামে চলে গেলেন এবং সেখানেই রাতটা কাটালেন।"},{"heading":"ডুমুর গাছটি","v":18,"ve":18,"vl":"18","bn":"পরদিন সকালে শহরে ফিরে আসবার সময় ঈসার খিদে পেল।"},{"v":19,"ve":19,"vl":"19","bn":"পথের পাশে একটা ডুমুর গাছ দেখে তিনি গাছটার কাছে গেলেন, কিন্তু তাতে পাতা ছাড়া আর কিছুই দেখতে পেলেন না। তখন তিনি গাছটাকে বললেন, “আর কখনও তোমার মধ্যে ফল না ধরুক।” আর তখনই ডুমুর গাছটা শুকিয়ে গেল।"},{"v":20,"ve":20,"vl":"20","bn":"সাহাবীরা তা দেখে আশ্চর্য হয়ে বললেন, “ডুমুর গাছটা এত তাড়াতাড়ি কেমন করে শুকিয়ে গেল?”"},{"v":21,"ve":21,"vl":"21","bn":"জবাবে ঈসা তাঁদের বললেন, “আমি তোমাদের সত্যিই বলছি, তোমরা সন্দেহ না করে যদি বিশ্বাস কর তবে ডুমুর গাছের উপরে আমি যা করেছি তোমরাও তা করতে পারবে। কেবল তা নয়, কিন্তু যদি এই পাহাড়কে বল, ‘উঠে সাগরে গিয়ে পড়,’ তবে তাও হবে।"},{"v":22,"ve":22,"vl":"22","bn":"তোমরা যদি বিশ্বাস করে মুনাজাত কর তবে তোমরা যা চাইবে তা-ই পাবে।”"},{"heading":"হযরত ঈসা মসীহ্‌ ও ধর্ম-নেতারা","v":23,"ve":23,"vl":"23","bn":"পরে ঈসা আবার বায়তুল-মোকাদ্দসে গেলেন। যখন তিনি সেখানে শিক্ষা দিচ্ছিলেন তখন প্রধান ইমামেরা ও ইহুদীদের বৃদ্ধ নেতারা তাঁর কাছে এসে বললেন, “তুমি কোন্‌ অধিকারে এই সব করছ? এই অধিকার তোমাকে কে দিয়েছে?”"},{"v":24,"ve":24,"vl":"24","bn":"ঈসা তাঁদের বললেন, “আমিও আপনাদের একটা কথা জিজ্ঞাসা করব। আপনারা যদি আমাকে তার জবাব দিতে পারেন তবে আমিও আপনাদের বলব আমি কোন্‌ অধিকারে এই সব করছি।"},{"v":25,"ve":25,"vl":"25","bn":"বলুন দেখি, তরিকাবন্দী দেবার অধিকার ইয়াহিয়া কোথা থেকে পেয়েছিলেন? আল্লাহ্‌র কাছ থেকে, না মানুষের কাছ থেকে?” তখন তাঁরা নিজেদের মধ্যে এই আলোচনা করলেন, “আমরা যদি বলি, ‘আল্লাহ্‌র কাছ থেকে,’ তাহলে সে আমাদের বলবে, ‘তবে কেন আপনারা ইয়াহিয়াকে বিশ্বাস করেন নি?’"},{"v":26,"ve":26,"vl":"26","bn":"আবার যদি বলি, ‘মানুষের কাছ থেকে,’ তবে লোকদের কাছ থেকে আমাদের ভয় আছে, কারণ ইয়াহিয়াকে সবাই নবী বলে মনে করে।”"},{"v":27,"ve":27,"vl":"27","bn":"এইজন্য জবাবে তাঁরা ঈসাকে বললেন, “আমরা জানি না।” তখন ঈসা তাঁদের বললেন, “তবে আমিও আপনাদের বলব না আমি কোন্‌ অধিকারে এই সব করছি।”"},{"heading":"দুই ছেলের গল্প","v":28,"ve":28,"vl":"28","bn":"তারপর ঈসা বললেন, “আচ্ছা, আপনারা কি মনে করেন? ধরুন, একজন লোকের দু’টি ছেলে ছিল। লোকটি তাঁর বড় ছেলের কাছে গিয়ে বলল, ‘আজ তুমি আংগুর ক্ষেতে গিয়ে কাজ কর।’"},{"v":29,"ve":29,"vl":"29","bn":"জবাবে ছেলেটি বলল, ‘আমি যাব না।’ কিন্তু পরে সে মন ফিরিয়ে কাজে গেল।"},{"v":30,"ve":30,"vl":"30","bn":"লোকটি পরে অন্য ছেলেটির কাছে গিয়ে সেই একই কথা বলল। অন্য ছেলেটি জবাবে বলল, ‘আমি যাচ্ছি,’ কিন্তু গেল না।"},{"v":31,"ve":31,"vl":"31","bn":"এই দু’জনের মধ্যে কে পিতার ইচ্ছা পালন করল?” তখন ধর্ম-নেতারা জবাব দিলেন, “প্রথম জন।” ঈসা তাঁদের বললেন, “আমি আপনাদের সত্যিই বলছি, খাজনা-আদায়কারীরা এবং বেশ্যারা আপনাদের আগে আল্লাহ্‌র রাজ্যে ঢুকছে,"},{"v":32,"ve":32,"vl":"32","bn":"কারণ ইয়াহিয়া আল্লাহ্‌র ইচ্ছামত চলবার পথ দেখাবার জন্য আপনাদের কাছে এসেছিলেন, আর আপনারা তাঁর কথায় ঈমান আনেন নি। কিন্তু খাজনা-আদায়কারীরা এবং বেশ্যারা তাঁর কথায় ঈমান এনেছিল। এ দেখেও আপনারা তওবা করে তাঁর কথায় ঈমান আনেন নি।"},{"heading":"আংগুর ক্ষেতের চাষীদের গল্প","v":33,"ve":33,"vl":"33","bn":"“আর একটা দৃষ্টান্ত দিই, শুনুন। একজন গৃহস' একটা আংগুর ক্ষেত করে তার চারদিকে বেড়া দিলেন। পরে সেই ক্ষেতের মধ্যে আংগুর-রস করবার জন্য গর্ত খুঁড়লেন এবং একটা উঁচু পাহারা-ঘর তৈরী করলেন। এর পরে তিনি কয়েকজন চাষীর কাছে সেই আংগুর ক্ষেতটা ইজারা দিয়ে বিদেশে চলে গেলেন।"},{"v":34,"ve":34,"vl":"34","bn":"যখন ফল পাকবার সময় হয়ে আসল তখন তিনি সেই ফলের ভাগ নিয়ে আসবার জন্য তাঁর গোলামদের সেই চাষীদের কাছে পাঠিয়ে দিলেন।"},{"v":35,"ve":35,"vl":"35","bn":"চাষীরা তাঁর গোলামদের একজনকে ধরে মারল, একজনকে খুন করল এবং অন্য আর একজনকে পাথর মারল।"},{"v":36,"ve":36,"vl":"36","bn":"এর পর তিনি প্রথম বারের চেয়ে আরও বেশী গোলাম পাঠিয়ে দিলেন, কিন্তু চাষীরা সেই গোলামদের সংগে একই রকমের ব্যবহার করল।"},{"v":37,"ve":37,"vl":"37","bn":"আংগুর ক্ষেতের মালিক শেষে নিজের ছেলেকেই তাদের কাছে পাঠালেন। তিনি ভাবলেন, তারা অন্ততঃ তাঁর ছেলেকে সম্মান করবে।"},{"v":38,"ve":38,"vl":"38","bn":"কিন্তু সেই চাষীরা ছেলেকে দেখে নিজেদের মধ্যে বলাবলি করল, ‘এ-ই পরে সম্পত্তির মালিক হবে। চল, আমরা ওকে মেরে ফেলি,"},{"v":39,"ve":39,"vl":"39","bn":"তাতে আমরাই সম্পত্তির মালিক হব।’ এই বলে তারা সেই ছেলেকে ধরে আংগুর ক্ষেত থেকে বাইরে নিয়ে গিয়ে মেরে ফেলল।"},{"v":40,"ve":40,"vl":"40","bn":"তাহলে বলুন দেখি, আংগুর ক্ষেতের মালিক যখন নিজে আসবেন তখন তিনি সেই চাষীদের নিয়ে কি করবেন?”"},{"v":41,"ve":41,"vl":"41","bn":"সেই ধর্ম-নেতারা ঈসাকে বললেন, “তিনি সেই দুষ্ট লোকদের একেবারে ধ্বংস করবেন এবং যে চাষীরা তাঁকে সময়মত ফলের ভাগ দেবে তাদের কাছেই সেই আংগুর ক্ষেতটা ইজারা দেবেন।”"},{"v":42,"ve":42,"vl":"42","bn":"তখন ঈসা তাঁদের বললেন, “আপনারা কি পাক-কিতাবের মধ্যে কখনও পড়েন নি, ‘রাজমিস্ত্রিরা যে পাথরটা বাতিল করে দিয়েছিল, সেটাই সবচেয়ে দরকারী পাথর হয়ে উঠল; মাবুদই এটা করলেন, আর তা আমাদের চোখে খুব আশ্চর্য লাগে’?"},{"v":43,"ve":43,"vl":"43","bn":"এইজন্য আপনাদের বলছি, আল্লাহ্‌র রাজ্য আপনাদের কাছ থেকে নিয়ে নেওয়া হবে এবং এমন লোকদের দেওয়া হবে যাদের জীবনে সেই রাজ্যের উপযুক্ত ফল দেখা যাবে।"},{"v":44,"ve":44,"vl":"44","bn":"যে সেই পাথরের উপরে পড়বে সে ভেংগে টুকরা টুকরা হয়ে যাবে এবং সেই পাথর যার উপরে পড়বে সে চুরমার হয়ে যাবে।”"},{"v":45,"ve":45,"vl":"45","bn":"প্রধান ইমামেরা এবং ফরীশীরা ঈসার শিক্ষা-ভরা গল্পগুলো শুনে বুঝতে পারলেন তিনি তাঁদের কথাই বলছেন।"},{"v":46,"ve":46,"vl":"46","bn":"তখন তাঁরা তাঁকে ধরতে চাইলেন, কিন্তু লোকদের ভয়ে তা করলেন না, কারণ লোকে ঈসাকে নবী বলে মনে করত।"}],"22":[{"heading":"বিয়ের মেজবানীর গল্প","v":1,"ve":1,"vl":"1","bn":"শিক্ষা দেবার জন্য ঈসা আবার সেই ধর্ম-নেতাদের কাছে এই গল্পটা বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“বেহেশতী রাজ্য এমন একজন বাদশাহ্‌র মত যিনি তাঁর ছেলের বিয়ের মেজবানী প্রস্তুত করলেন।"},{"v":3,"ve":3,"vl":"3","bn":"যে লোকেরা সেই ভোজে দাওয়াত পেয়েছিল, তাদের ডাকবার জন্য তিনি তাঁর গোলামদের পাঠিয়ে দিলেন, কিন্তু তারা আসতে চাইল না।"},{"v":4,"ve":4,"vl":"4","bn":"তখন তিনি আবার অন্য গোলামদের দিয়ে যে লোকদের দাওয়াত করা হয়েছিল, তাদের বলে পাঠালেন, ‘দেখুন, আমি আমার বলদ ও মোটাসোটা বাছুরগুলো জবাই করে মেজবানী প্রস্তুত করেছি। এখন সবই প্রস্তুত, আপনারা ভোজে আসুন।’"},{"v":5,"ve":5,"vl":"5","bn":"“যে লোকেরা দাওয়াত পেয়েছিল, তারা কিন্তু সেই গোলামদের কথা না শুনে একজন তার নিজের ক্ষেতে ও আর একজন তার নিজের কাজে চলে গেল।"},{"v":6,"ve":6,"vl":"6","bn":"বাকী সবাই বাদশাহ্‌র গোলামদের ধরে অপমান করল ও হত্যা করল।"},{"v":7,"ve":7,"vl":"7","bn":"তখন বাদশাহ্‌ খুব রেগে গেলেন এবং সৈন্য পাঠিয়ে তিনি সেই খুনীদের ধ্বংস করলেন আর তাদের শহর পুড়িয়ে দিলেন।"},{"v":8,"ve":8,"vl":"8","bn":"পরে তিনি তাঁর গোলামদের বললেন, ‘মেজবানী প্রস্তুত, কিন্তু যাদের দাওয়াত করা হয়েছিল তারা এর যোগ্য নয়।"},{"v":9,"ve":9,"vl":"9","bn":"তোমরা বরং রাস্তার মোড়ে মোড়ে যাও, আর যত জনের দেখা পাও সবাইকে বিয়ের ভোজে ডেকে আন।’"},{"v":10,"ve":10,"vl":"10","bn":"তখন সেই গোলামেরা বাইরে রাস্তায় রাস্তায় গিয়ে ভাল-মন্দ যাদের পেল সবাইকে ডেকে আনল। তাতে বিয়ে-বাড়ী সেই মেহমানে ভরে গেল।"},{"v":11,"ve":11,"vl":"11","bn":"“এর পর বাদশাহ্‌ মেহমানদের দেখবার জন্য ভিতরে এসে দেখলেন,"},{"v":12,"ve":12,"vl":"12","bn":"একজন লোক বিয়ের কাপড় না পরেই সেখানে এসেছে। বাদশাহ্‌ তাকে জিজ্ঞাসা করলেন, ‘বন্ধু, বিয়ের কাপড় ছাড়া কেমন করে এখানে ঢুকলে?’ সে এর কোন জবাব দিতে পারল না।"},{"v":13,"ve":13,"vl":"13","bn":"তখন বাদশাহ্‌ চাকরদের বললেন, ‘এর হাত-পা বেঁধে বাইরের অন্ধকারে ফেলে দাও। সেই জায়গায় লোকে কান্নাকাটি করবে ও যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবে।’ ”"},{"v":14,"ve":14,"vl":"14","bn":"গল্পের শেষে ঈসা বললেন, “এইজন্য বলি, অনেক লোককে ডাকা হয়েছে কিন্তু অল্প লোককে বেছে নেওয়া হয়েছে।”"},{"heading":"খাজনা দেওয়া কি উচিত?","v":15,"ve":15,"vl":"15","bn":"তখন ফরীশীরা চলে গেলেন এবং কেমন করে ঈসাকে তাঁর কথার ফাঁদে ফেলা যায় সেই পরামর্শ করতে লাগলেন।"},{"v":16,"ve":16,"vl":"16","bn":"তারা হেরোদের দলের কয়েকজন লোকের সংগে নিজেদের কয়েকজন শাগরেদকে ঈসার কাছে পাঠালেন। তারা তাঁকে বলল, “হুজুর, আমরা জানি আপনি একজন সৎ লোক। আল্লাহ্‌র পথের বিষয়ে আপনি সত্যভাবে শিক্ষা দিয়ে থাকেন। লোকে কি মনে করবে না করবে তাতে আপনার কিছু যায় আসে না, কারণ আপনি কারও মুখ চেয়ে কিছু করেন না।"},{"v":17,"ve":17,"vl":"17","bn":"তাহলে আপনি বলুন, মূসার শরীয়ত অনুসারে রোম-সম্রাটকে কি খাজনা দেওয়া উচিত? আপনার কি মনে হয়?”"},{"v":18,"ve":18,"vl":"18","bn":"তাদের খারাপ উদ্দেশ্য বুঝতে পেরে ঈসা বললেন, “ভণ্ডেরা, কেন আমাকে পরীক্ষা করছ?"},{"v":19,"ve":19,"vl":"19","bn":"যে টাকায় খাজনা দেবে তার একটা আমাকে দেখাও।” তারা একটা দীনার ঈসার কাছে আনল।"},{"v":20,"ve":20,"vl":"20","bn":"তখন ঈসা তাদের বললেন, “এর উপরে এই ছবি ও নাম কার?”"},{"v":21,"ve":21,"vl":"21","bn":"তারা বলল, “রোম-সম্রাটের।” ঈসা তাদের বললেন, “তবে যা সম্রাটের তা সম্রাটকে দাও, আর যা আল্লাহ্‌র তা আল্লাহ্‌কে দাও।”"},{"v":22,"ve":22,"vl":"22","bn":"এই কথা শুনে তারা আশ্চর্য হল এবং তাঁকে ছেড়ে চলে গেল।"},{"heading":"জীবিত হয়ে উঠবার বিষয়ে","v":23,"ve":23,"vl":"23","bn":"সেই একই দিনে কয়েকজন সদ্দূকী ঈসার কাছে আসলেন। সদ্দূকীদের মতে মৃতদের জীবিত হয়ে ওঠা বলে কিছু নেই।"},{"v":24,"ve":24,"vl":"24","bn":"এইজন্য তাঁরা ঈসাকে জিজ্ঞাসা করলেন, “হুজুর, মূসা বলেছেন, যদি কোন লোক সন্তানহীন অবস্থায় মারা যায় তবে তার ভাই তার স্ত্রীকে বিয়ে করে ভাইয়ের হয়ে তার বংশ রক্ষা করবে।"},{"v":25,"ve":25,"vl":"25","bn":"আমাদের এখানে সাত ভাই ছিল। প্রথম জন বিয়ে করে মারা গেল এবং সন্তান না থাকাতে সে তার ভাইয়ের জন্য নিজের স্ত্রীকে রেখে গেল।"},{"v":26,"ve":26,"vl":"26","bn":"এইভাবে দ্বিতীয়, তৃতীয় ও সপ্তম ভাই পর্যন্ত সেই স্ত্রীকে বিয়ে করল।"},{"v":27,"ve":27,"vl":"27","bn":"শেষে সেই স্ত্রীলোকটিও মারা গেল।"},{"v":28,"ve":28,"vl":"28","bn":"তাহলে মৃতেরা যখন জীবিত হয়ে উঠবে তখন ঐ সাত ভাইয়ের মধ্যে এই স্ত্রীলোকটি কার স্ত্রী হবে? তারা সবাই তো তাকে বিয়ে করেছিল।”"},{"v":29,"ve":29,"vl":"29","bn":"ঈসা তাঁদের বললেন, “আপনারা ভুল করছেন, কারণ আপনারা পাক-কিতাবও জানেন না, আল্লাহ্‌র শক্তির বিষয়েও জানেন না।"},{"v":30,"ve":30,"vl":"30","bn":"মৃতেরা জীবিত হয়ে উঠবার পরে বিয়ে করবে না এবং তাদের বিয়ে দেওয়াও হবে না; তারা ফেরেশতাদের মত হবে।"},{"v":31,"ve":31,"vl":"31","bn":"মৃতদের জীবিত হয়ে উঠবার বিষয়ে আল্লাহ্‌ যে কথা আপনাদের বলেছেন সেই কথা কি আপনারা পাক-কিতাবে পড়েন নি?"},{"v":32,"ve":32,"vl":"32","bn":"তাতে লেখা আছে, ‘আমি ইব্রাহিমের আল্লাহ্‌, ইসহাকের আল্লাহ্‌ এবং ইয়াকুবের আল্লাহ্‌।’ কিন্তু আল্লাহ্‌ তো মৃতদের আল্লাহ্‌ নন, তিনি জীবিতদেরই আল্লাহ্‌।”"},{"v":33,"ve":33,"vl":"33","bn":"এই কথা শুনে লোকেরা তাঁর শিক্ষায় আশ্চর্য হল।"},{"heading":"সবচেয়ে বড় হুকুম","v":34,"ve":34,"vl":"34","bn":"ঈসা সদ্দূকীদের মুখ বন্ধ করে দিয়েছেন শুনে ফরীশীরা একত্র হলেন।"},{"v":35,"ve":35,"vl":"35","bn":"তাঁদের মধ্যে একজন আলেম ঈসাকে পরীক্ষা করবার জন্য জিজ্ঞাসা করলেন,"},{"v":36,"ve":36,"vl":"36","bn":"“হুজুর, তৌরাত শরীফের মধ্যে সবচেয়ে বড় হুকুম কোন্‌টা?”"},{"v":37,"ve":38,"vl":"37-38","bn":"ঈসা তাঁকে বললেন, “সবচেয়ে বড় এবং সবচেয়ে দরকারী হুকুম হল, ‘তোমরা প্রত্যেকে তোমাদের সমস্ত দিল, সমস্ত প্রাণ ও সমস্ত মন দিয়ে তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবে।’"},{"v":39,"ve":39,"vl":"39","bn":"তার পরের দরকারী হুকুমটা প্রথমটারই মত- ‘তোমার প্রতিবেশীকে নিজের মত মহব্বত করবে।’"},{"v":40,"ve":40,"vl":"40","bn":"সম্পূর্ণ তৌরাত শরীফ এবং নবীদের সমস্ত কিতাব এই দু’টি হুকুমের উপরেই ভরসা করে আছে।”"},{"heading":"আলেমদের কাছে হযরত ঈসা মসীহের প্রশ্ন","v":41,"ve":41,"vl":"41","bn":"ফরীশীরা তখনও একসংগে ছিলেন, এমন সময় ঈসা তাদের জিজ্ঞাসা করলেন,"},{"v":42,"ve":42,"vl":"42","bn":"“আপনারা মসীহের বিষয়ে কি মনে করেন? তিনি কার বংশধর?” তাঁরা ঈসাকে বললেন, “দাউদের বংশধর।”"},{"v":43,"ve":43,"vl":"43","bn":"তখন ঈসা তাঁদের বললেন, “তবে দাউদ কেমন করে মসীহ্‌কে পাক-রূহের পরিচালনায় প্রভু বলে ডেকেছিলেন? তিনি বলেছিলেন,"},{"v":44,"ve":44,"vl":"44","bn":"‘মাবুদ আমার প্রভুকে বললেন, যতক্ষণ না আমি তোমার শত্রুদের তোমার পায়ের তলায় রাখি, ততক্ষণ তুমি আমার ডানদিকে বস।’"},{"v":45,"ve":45,"vl":"45","bn":"তাহলে দাউদ যখন মসীহ্‌কে প্রভু বলে ডেকেছেন তখন মসীহ্‌ কেমন করে দাউদের বংশধর হতে পারেন?”"},{"v":46,"ve":46,"vl":"46","bn":"এর জবাবে কেউ এক কথাও তাঁকে বলতে পারল না এবং সেই দিন থেকে কেউ তাঁকে আর কিছু জিজ্ঞাসা করতেও সাহস করল না।"}],"23":[{"heading":"ধর্ম-নেতাদের বিরুদ্ধে হযরত ঈসা মসীহের কথা","v":1,"ve":1,"vl":"1","bn":"পরে ঈসা লোকদের কাছে ও তাঁর সাহাবীদের কাছে বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“শরীয়ত শিক্ষা দেবার ব্যাপারে আলেমেরা ও ফরীশীরা মূসা নবীর জায়গায় আছেন।"},{"v":3,"ve":3,"vl":"3","bn":"এইজন্য তাঁরা যা কিছু করতে বলেন তা কোরো এবং যা পালন করবার হুকুম দেন তা পালন কোরো। কিন্তু তাঁরা যা করেন তোমরা তা কোরো না, কারণ তাঁরা মুখে যা বলেন কাজে তা করেন না।"},{"v":4,"ve":4,"vl":"4","bn":"তাঁরা ভারী ভারী বোঝা বেঁধে মানুষের কাঁধে চাপিয়ে দেন, কিন্তু সেগুলো সরাবার জন্য নিজেরা একটা আংগুলও নাড়াতে চান না।"},{"v":5,"ve":5,"vl":"5","bn":"লোকদের দেখাবার জন্যই তাঁরা সব কাজ করেন। পাক-কিতাবের আয়াত-লেখা তাবিজ তাঁরা বড় করে তৈরী করেন আর নিজেদের ধার্মিক দেখাবার জন্য চাদরের কোণায় কোণায় লম্বা থোপ্‌না লাগান।"},{"v":6,"ve":6,"vl":"6","bn":"মেজবানীর সময় সম্মানের জায়গায় এবং মজলিস-খানায় প্রধান প্রধান আসনে তাঁরা বসতে ভালবাসেন।"},{"v":7,"ve":7,"vl":"7","bn":"তাঁরা হাটে-বাজারে সম্মান খুঁজে বেড়ান আর চান যেন লোকেরা তাঁদের ওস্তাদ বলে ডাকে।"},{"v":8,"ve":8,"vl":"8","bn":"“কেউ তোমাদের ওস্তাদ বলে ডাকুক তা চেয়ো না, কারণ তোমাদের ওস্তাদ বলতে কেবল একজনই আছেন, আর তোমরা সবাই ভাই ভাই।"},{"v":9,"ve":9,"vl":"9","bn":"এই দুনিয়াতে কাউকেই পিতা বলে ডেকো না, কারণ তোমাদের একজনই পিতা আর তিনি বেহেশতে আছেন।"},{"v":10,"ve":10,"vl":"10","bn":"কেউ তোমাদের নেতা বলে ডাকুক তা চেয়ো না, কারণ তোমাদের নেতা বলতে কেবল একজনই আছেন, তিনি মসীহ্‌।"},{"v":11,"ve":11,"vl":"11","bn":"তোমাদের মধ্যে যে সবচেয়ে বড় সে তোমাদের সেবাকারী হোক।"},{"v":12,"ve":12,"vl":"12","bn":"যে কেউ নিজেকে উঁচু করে তাকে নীচু করা হবে এবং যে কেউ নিজেকে নীচু করে তাকে উঁচু করা হবে।"},{"v":13,"ve":13,"vl":"13","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! আপনারা লোকদের সামনে বেহেশতী রাজ্যের দরজা বন্ধ করে রাখেন। তাতে নিজেরাও ঢোকেন না আর যারা ঢুকতে চেষ্টা করছে তাদেরও ঢুকতে দেন না।"},{"v":14,"ve":14,"vl":"14","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! এক দিকে আপনারা লোকদের দেখাবার জন্য লম্বা লম্বা মুনাজাত করেন, অন্য দিকে বিধবাদের সম্পত্তি দখল করেন। এইজন্য আপনাদের অনেক বেশী শাস্তি হবে।"},{"v":15,"ve":15,"vl":"15","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! একটি মাত্র লোককে আপনাদের ধর্ম-মতে আনবার জন্য আপনারা দুনিয়ার কোথায় না যান। আর সে যখন আপনাদের ধর্ম-মতে আসে তখন আপনারা নিজেদের চেয়ে তাকে অনেক বেশী করে জাহান্নামী করে তোলেন।"},{"v":16,"ve":16,"vl":"16","bn":"“ঘৃণ্য আপনারা! আপনারা নিজেরা অন্ধ অথচ অন্যদের পথ দেখান। আপনারা বলে থাকেন, বায়তুল-মোকাদ্দসের নামে কেউ কসম খেলে তাতে কিছু হয় না, কিন্তু যদি কেউ বায়তুল-মোকাদ্দসের সোনার নামে কসম খায় তবে সে সেই কসমে বাঁধা পড়ে।"},{"v":17,"ve":17,"vl":"17","bn":"মূর্খ ও অন্ধের দল, কোন্‌টা বড়? সোনা, না সেই বায়তুল-মোকাদ্দস যা সেই সোনাকে পবিত্র করে?"},{"v":18,"ve":18,"vl":"18","bn":"আপনারা আবার এই কথাও বলে থাকেন, কোরবানগাহের নামে কেউ কসম খেলে কিছুই হয় না, কিন্তু যদি কেউ সেই কোরবানগাহের উপরে যে দান আছে তার নামে কসম খায় তবে সে সেই কসমে বাঁধা পড়ে।"},{"v":19,"ve":19,"vl":"19","bn":"অন্ধের দল, কোন্‌টা বড়? সেই দান, না সেই কোরবানগাহ্‌ যা সেই দানকে পবিত্র করে?"},{"v":20,"ve":20,"vl":"20","bn":"এইজন্য কোরবানগাহের নামে যে কসম খায় সে সেই কোরবানগাহ্‌ এবং তার উপরের সব কিছুর নামেই কসম খায়।"},{"v":21,"ve":21,"vl":"21","bn":"আর বায়তুল-মোকাদ্দসের নামে যে কসম খায় সে বায়তুল-মোকাদ্দস এবং তার ভিতরে যিনি থাকেন তাঁরই নামে কসম খায়।"},{"v":22,"ve":22,"vl":"22","bn":"যে বেহেশতের নামে কসম খায় সে আল্লাহ্‌র সিংহাসন এবং যিনি তার উপর বসে আছেন তাঁরই নামে কসম খায়।"},{"v":23,"ve":23,"vl":"23","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! আপনারা পুদিনা, মৌরি আর জিরার দশ ভাগের এক ভাগ আল্লাহ্‌কে ঠিকমতই দিয়ে থাকেন; কিন্তু ন্যায়, দয়া এবং বিশ্বস্ততা, যা মূসার শরীয়তের আরও দরকারী বিষয় তা আপনারা বাদ দিয়েছেন। আগেরগুলো পালন করবার সংগে সংগে পরেরগুলোও পালন করা আপনাদের উচিত।"},{"v":24,"ve":24,"vl":"24","bn":"আপনারা নিজেরা অন্ধ অথচ অন্যদের পথ দেখান। একটা ছোট মাছিও আপনারা ছাঁকেন অথচ উট গিলে ফেলেন।"},{"v":25,"ve":25,"vl":"25","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! আপনারা থালা-পেয়ালার বাইরের দিকটা পরিষ্কার করে থাকেন, কিন্তু সেগুলো জুলুমের জিনিস আর লোভের ফল দিয়ে পূর্ণ।"},{"v":26,"ve":26,"vl":"26","bn":"অন্ধ ফরীশীরা, আগে সেগুলোর ভিতরের দিকটা পরিষ্কার করুন, তাতে তার বাইরের দিকটাও পরিষ্কার হবে।"},{"v":27,"ve":27,"vl":"27","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! আপনারা চুনকাম করা কবরের মত, যার বাইরের দিকটা সুন্দর কিন্তু ভিতরটা মরা মানুষের হাড়-গোড় ও সব রকম ময়লায় ভরা।"},{"v":28,"ve":28,"vl":"28","bn":"ঠিক সেইভাবে, বাইরে আপনারা লোকদের চোখে ধার্মিক কিন্তু ভিতরে ভণ্ডামী ও গুনাহে পূর্ণ।"},{"v":29,"ve":29,"vl":"29","bn":"“ভণ্ড আলেম ও ফরীশীরা, ঘৃণ্য আপনারা! আপনারা নবীদের কবর নতুন করে গাঁথেন এবং আল্লাহ্‌ভক্ত লোকদের কবর সাজান।"},{"v":30,"ve":30,"vl":"30","bn":"আপনারা বলেন, ‘আমরা যদি আমাদের পূর্বপুরুষদের সময় বেঁচে থাকতাম তবে নবীদের খুন করবার জন্য তাঁদের সংগে যোগ দিতাম না।’"},{"v":31,"ve":31,"vl":"31","bn":"এতে আপনারা নিজেদের বিরুদ্ধে এই সাক্ষ্য দিচ্ছেন যে, নবীদের যারা খুন করেছে আপনারা তাদেরই বংশধর।"},{"v":32,"ve":32,"vl":"32","bn":"তাহলে আপনাদের পূর্বপুরুষেরা যা শুরু করে গেছেন তার বাকী অংশ আপনারা শেষ করুন।"},{"v":33,"ve":33,"vl":"33","bn":"“সাপের দল আর সাপের বংশধরেরা! কেমন করে আপনারা জাহান্নামের আজাব থেকে রক্ষা পাবেন?"},{"v":34,"ve":34,"vl":"34","bn":"এইজন্যই আমি আপনাদের কাছে নবী, জ্ঞানী লোক এবং আলেমদের পাঠাচ্ছি। আপনারা তাঁদের মধ্যে কয়েকজনকে খুন করবেন ও কয়েকজনকে ক্রুশের উপরে হত্যা করবেন। কয়েকজনকে আপনাদের মজলিস-খানায় চাবুক মারবেন এবং এক গ্রাম থেকে অন্য গ্রামে তাড়া করে বেড়াবেন।"},{"v":35,"ve":35,"vl":"35","bn":"এইজন্য নির্দোষ হাবিলের খুন থেকে শুরু করে আপনারা যে বরখিয়ের ছেলে জাকারিয়াকে পবিত্র স্থান আর কোরবানগাহের মাঝখানে খুন করেছিলেন, সেই জাকারিয়ার খুন পর্যন্ত দুনিয়াতে যত নির্দোষ লোক খুন হয়েছে আপনারা সেই সমস্ত রক্তের দায়ী হবেন।"},{"v":36,"ve":36,"vl":"36","bn":"আমি আপনাদের সত্যিই বলছি, এই কালের লোকেরাই সেই সমস্ত রক্তের দায়ী হবে।"},{"heading":"জেরুজালেমের জন্য দুঃখ প্রকাশ","v":37,"ve":37,"vl":"37","bn":"“জেরুজালেম! হায় জেরুজালেম! তুমি নবীদের খুন করে থাক এবং তোমার কাছে যাদের পাঠানো হয় তাদের পাথর মেরে থাক। মুরগী যেমন বাচ্চাদের তার ডানার নীচে জড়ো করে তেমনি আমি তোমার লোকদের কতবার আমার কাছে জড়ো করতে চেয়েছি, কিন্তু তারা রাজী হয় নি।"},{"v":38,"ve":38,"vl":"38","bn":"হে জেরুজালেমের লোকেরা, তোমাদের বাড়ী তোমাদের সামনে খালি হয়ে পড়ে থাকবে।"},{"v":39,"ve":39,"vl":"39","bn":"আমি তোমাদের বলছি, যে পর্যন্ত না তোমরা বলবে, ‘যিনি মাবুদের নামে আসছেন তাঁর প্রশংসা হোক,’ সেই পর্যন্ত আর তোমরা আমাকে দেখতে পাবে না।”"}],"24":[{"heading":"কেয়ামতের আলামত","v":1,"ve":1,"vl":"1","bn":"ঈসা বায়তুল-মোকাদ্দস থেকে বের হয়ে চলে যাচ্ছিলেন, এমন সময় তাঁর সাহাবীরা তাঁকে বায়তুল-মোকাদ্দসের দালানগুলো দেখাবার জন্য তাঁর কাছে আসলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন ঈসা তাঁদের বললেন, “তোমরা তো এই সব দেখছ, কিন্তু আমি তোমাদের সত্যিই বলছি, এখানে একটা পাথরের উপরে আর একটা পাথর থাকবে না; সমস্তই ভেংগে ফেলা হবে।”"},{"v":3,"ve":3,"vl":"3","bn":"পরে ঈসা যখন জৈতুন পাহাড়ে বসে ছিলেন তখন সাহাবীরা গোপনে তাঁর কাছে এসে বললেন, “আমাদের বলুন, কখন এই সব হবে এবং কি রকম চিহ্নের দ্বারা বুঝা যাবে আপনার আসবার সময় ও কেয়ামতের সময় হয়েছে?”"},{"v":4,"ve":4,"vl":"4","bn":"জবাবে ঈসা তাঁদের বললেন, “দেখো, কেউ যেন তোমাদের না ঠকায়,"},{"v":5,"ve":5,"vl":"5","bn":"কারণ অনেকেই আমার নাম নিয়ে এসে বলবে, ‘আমিই মসীহ্‌,’ এবং অনেক লোককে ঠকাবে।"},{"v":6,"ve":6,"vl":"6","bn":"তোমাদের কানে যুদ্ধের আওয়াজ আসবে আর যুদ্ধের খবরাখবরও তোমরা শুনতে পাবে। কিন্তু সাবধান! এতে ভয় পেয়ো না, কারণ এই সব হবেই; কিন্তু তখনও শেষ নয়।"},{"v":7,"ve":7,"vl":"7","bn":"এক জাতি অন্য জাতির বিরুদ্ধে এবং এক রাজ্য অন্য রাজ্যের বিরুদ্ধে যুদ্ধ করবে। অনেক জায়গায় দুর্ভিক্ষ ও ভূমিকমপ হবে।"},{"v":8,"ve":8,"vl":"8","bn":"কিন্তু এই সব কেবল যন্ত্রণার শুরু।"},{"v":9,"ve":9,"vl":"9","bn":"“সেই সময়ে লোকে তোমাদের কষ্ট দেবার জন্য ধরিয়ে দেবে এবং তোমাদের খুন করবে। আমার জন্য সব লোকেরা তোমাদের ঘৃণা করবে।"},{"v":10,"ve":10,"vl":"10","bn":"সেই সময়ে অনেকেই পিছিয়ে যাবে এবং একে অন্যকে ধরিয়ে দেবে ও ঘৃণা করবে।"},{"v":11,"ve":11,"vl":"11","bn":"অনেক ভণ্ড নবী এসে অনেককে ঠকাবে।"},{"v":12,"ve":12,"vl":"12","bn":"দুষ্টতা বেড়ে যাবে বলে অনেকের মহব্বত খুব কমে যাবে।"},{"v":13,"ve":13,"vl":"13","bn":"কিন্তু যে শেষ পর্যন্ত স্থির থাকবে সে উদ্ধার পাবে।"},{"v":14,"ve":14,"vl":"14","bn":"সমস্ত জাতির কাছে সাক্ষ্য দেবার জন্য বেহেশতী রাজ্যের সুসংবাদ সারা দুনিয়াতে তবলিগ করা হবে এবং তার পরেই শেষ সময় উপস্থিত হবে।"},{"heading":"কেয়ামতের দিনের ভীষণ কষ্ট","v":15,"ve":15,"vl":"15","bn":"“দানিয়াল নবীর মধ্য দিয়ে যে সর্বনাশা ঘৃণার জিনিসের কথা বলা হয়েছিল তা তোমরা পবিত্র জায়গায় রাখা হয়েছে দেখতে পাবে। (যে পড়ে সে বুঝুক।)"},{"v":16,"ve":16,"vl":"16","bn":"সেই সময় যারা এহুদিয়াতে থাকবে তারা পাহাড়ী এলাকায় পালিয়ে যাক।"},{"v":17,"ve":17,"vl":"17","bn":"যে ছাদের উপরে থাকবে সে ঘর থেকে জিনিসপত্র নেবার জন্য নীচে না নামুক।"},{"v":18,"ve":18,"vl":"18","bn":"ক্ষেতের মধ্যে যে থাকবে সে তার গায়ের চাদর নেবার জন্য না ফিরুক।"},{"v":19,"ve":19,"vl":"19","bn":"তখন যারা গর্ভবতী আর যারা সন্তানকে বুকের দুধ খাওয়ায় তাদের অবস্থা কি ভীষণই না হবে!"},{"v":20,"ve":20,"vl":"20","bn":"মুনাজাত কর যেন শীতকালে বা বিশ্রামবারে তোমাদের পালাতে না হয়।"},{"v":21,"ve":21,"vl":"21","bn":"তখন এমন মহাকষ্ট হবে যা দুনিয়ার শুরু থেকে এই সময় পর্যন্ত কখনও হয় নি এবং হবেও না।"},{"v":22,"ve":22,"vl":"22","bn":"সেই কষ্টের দিনগুলো যদি আল্লাহ্‌ কমিয়ে না দিতেন তবে কেউই বাঁচত না। কিন্তু তাঁর বাছাই করা বান্দাদের জন্য আল্লাহ্‌ সেই দিনগুলো কমিয়ে দেবেন।"},{"v":23,"ve":23,"vl":"23","bn":"“সেই সময়ে যদি কেউ তোমাদের বলে, ‘দেখ, মসীহ্‌ এখানে’ কিংবা ‘দেখ,মসীহ্‌ ওখানে,’ তবে তা বিশ্বাস কোরো না;"},{"v":24,"ve":24,"vl":"24","bn":"কারণ তখন অনেক ভণ্ড মসীহ্‌ ও ভণ্ড নবী আসবে এবং বড় বড় চিহ্ন-কাজ ও কুদরতি দেখাবে যাতে সম্ভব হলে আল্লাহ্‌র বাছাই করা বান্দাদেরও তারা ঠকাতে পারে।"},{"v":25,"ve":25,"vl":"25","bn":"দেখ, আমি আগেই তোমাদের এই সব বলে রাখলাম।"},{"v":26,"ve":26,"vl":"26","bn":"“সেইজন্য লোকে যদি তোমাদের বলে, ‘তিনি মরুভূমিতে আছেন,’ তোমরা বাইরে যেয়ো না। যদি বলে, ‘তিনি ভিতরের ঘরে আছেন,’ বিশ্বাস কোরো না।"},{"v":27,"ve":27,"vl":"27","bn":"বিদ্যুৎ যেমন পূর্ব দিকে দেখা দিয়ে পশ্চিম দিক পর্যন্ত চম্‌কে যায় ইব্‌ন্তেআদমের আসা সেইভাবেই হবে।"},{"v":28,"ve":28,"vl":"28","bn":"যেখানে লাশ থাকবে সেখানেই শকুন এসে একসংগে জড়ো হবে।"},{"heading":"হযরত ঈসা মসীহ্‌ যেভাবে আসবেন","v":29,"ve":29,"vl":"29","bn":"“সেই সময়কার কষ্টের ঠিক পরেই সূর্য অন্ধকার হয়ে যাবে, চাঁদ আর আলো দেবে না, তারাগুলো আসমান থেকে খসে পড়ে যাবে এবং চাঁদ-সূর্য-তারা আর স্থির থাকবে না।"},{"v":30,"ve":30,"vl":"30","bn":"এমন সময় আসমানে ইব্‌ন্তেআদমের চিহ্ন দেখা দেবে। তখন দুনিয়ার সমস্ত লোক দুঃখে বুক চাপড়াবে। তারা ইব্‌ন্তেআদমকে শক্তি ও মহিমার সংগে মেঘে করে আসতে দেখবে।"},{"v":31,"ve":31,"vl":"31","bn":"জোরে জোরে শিংগা বেজে উঠবে আর সংগে সংগে ইব্‌ন্তেআদম তাঁর ফেরেশতাদের পাঠিয়ে দেবেন। সেই ফেরেশতারা দুনিয়ার এক দিক থেকে অন্য দিক পর্যন্ত চার দিক থেকে তাঁর বাছাই করা বান্দাদের একসংগে জমায়েত করবেন।"},{"v":32,"ve":32,"vl":"32","bn":"“ডুমুর গাছ দেখে শিক্ষা লাভ কর। যখন তার ডালপালা নরম হয়ে তাতে পাতা বের হয় তখন তোমরা জানতে পার যে, গরমকাল কাছে এসেছে।"},{"v":33,"ve":33,"vl":"33","bn":"সেইভাবে তোমরা এই সব ঘটনা দেখলে পর বুঝতে পারবে যে, ইব্‌ন্তেআদম কাছে এসে গেছেন, এমন কি, দরজায় উপস্থিত।"},{"v":34,"ve":34,"vl":"34","bn":"আমি তোমাদের সত্যি বলছি, যখন এই সব হবে তখনও এই কালের কিছু লোক বেঁচে থাকবে।"},{"v":35,"ve":35,"vl":"35","bn":"আসমান ও জমীন শেষ হবে, কিন্তু আমার কথা চিরদিন থাকবে।"},{"heading":"হযরত ঈসা মসীহ্‌ কখন আসবেন","v":36,"ve":36,"vl":"36","bn":"“সেই দিন ও সেই সময়ের কথা কেউই জানে না, বেহেশতের ফেরেশতারাও না, পুত্রও না; কেবল পিতাই জানেন।"},{"v":37,"ve":37,"vl":"37","bn":"“নবী নূহের সময়ে যে অবস্থা হয়েছিল ইব্‌ন্তেআদমের আসবার সময়ে ঠিক সেই অবস্থাই হবে।"},{"v":38,"ve":38,"vl":"38","bn":"বন্যার আগের দিনগুলোতে নূহ্‌ জাহাজে না ঢোকা পর্যন্ত লোকে খাওয়া-দাওয়া করেছে, বিয়ে করেছে এবং বিয়ে দিয়েছে।"},{"v":39,"ve":39,"vl":"39","bn":"যে পর্যন্ত না বন্যা এসে তাদের সবাইকে ভাসিয়ে নিয়ে গেল সেই পর্যন্ত তারা কিছুই বুঝতে পারল না। ইব্‌ন্তেআদমের আসাও ঠিক সেই রকমই হবে।"},{"v":40,"ve":40,"vl":"40","bn":"তখন দু’জন লোক মাঠে থাকবে; একজনকে নেওয়া হবে এবং অন্যজনকে ফেলে যাওয়া হবে।"},{"v":41,"ve":41,"vl":"41","bn":"দু’জন স্ত্রীলোক জাঁতা ঘুরাবে; একজনকে নেওয়া হবে, অন্যজনকে ফেলে যাওয়া হবে।"},{"v":42,"ve":42,"vl":"42","bn":"“তাই বলি, তোমরা সতর্ক থাক, কারণ তোমাদের প্রভু কোন্‌ দিন আসবেন তা তোমরা জান না।"},{"v":43,"ve":43,"vl":"43","bn":"তবে তোমরা এই কথা জেনো, ঘরের কর্তা যদি জানতেন কোন্‌ সময় চোর আসবে তাহলে তিনি জেগেই থাকতেন, নিজের ঘরে তিনি চোরকে ঢুকতে দিতেন না।"},{"v":44,"ve":44,"vl":"44","bn":"সেইজন্য তোমরাও প্রস্তুত থাক, কারণ যে সময়ের কথা তোমরা চিন্তাও করবে না সেই সময়েই ইব্‌ন্তেআদম আসবেন।"},{"heading":"বিশ্বস্ত হওয়ার উপদেশ","v":45,"ve":45,"vl":"45","bn":"“সেই বিশ্বস্ত ও বুদ্ধিমান গোলাম কে, যাকে তার মালিক তাঁর অন্যান্য গোলামদের ঠিক সময়ে খাবার দেবার ভার দিয়েছেন?"},{"v":46,"ve":46,"vl":"46","bn":"ধন্য সেই গোলাম, যাকে তার মালিক এসে বিশ্বস্তভাবে কাজ করতে দেখবেন।"},{"v":47,"ve":47,"vl":"47","bn":"আমি তোমাদের সত্যি বলছি, তিনি সেই গোলামকেই তাঁর সমস্ত বিষয়-সম্পত্তির ভার দেবেন।"},{"v":48,"ve":48,"vl":"48","bn":"কিন্তু ধর, সেই গোলাম দুষ্ট, আর সে মনে মনে বলল, ‘আমার মালিক আসতে দেরি করছেন।’"},{"v":49,"ve":49,"vl":"49","bn":"সেই সুযোগে সে তার সংগী-গোলামদের মারধর করতে লাগল এবং মাতালদের সংগে খাওয়া-দাওয়া করে মদ খেতে লাগল।"},{"v":50,"ve":50,"vl":"50","bn":"কিন্তু যেদিন ও যে সময়ের কথা সেই গোলাম চিন্তাও করবে না, জানবেও না, সেই দিন ও সেই সময়েই তার মালিক এসে হাজির হবেন।"},{"v":51,"ve":51,"vl":"51","bn":"তখন তিনি তাকে কেটে দু’টুকরা করে ভণ্ডদের মধ্যে তার স্থান ঠিক করবেন। সেখানে লোকে কান্নাকাটি করবে ও যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবে।"}],"25":[{"heading":"দশজন মেয়ের গল্প","v":1,"ve":1,"vl":"1","bn":"“সেই সময়ে বেহেশতী রাজ্য এমন দশজন মেয়ের মত হবে যারা বান্ধবীর বরকে এগিয়ে আনবার জন্য বাতি নিয়ে বাইরে গেল।"},{"v":2,"ve":2,"vl":"2","bn":"তাদের মধ্যে পাঁচজন ছিল বুদ্ধিমতি।"},{"v":3,"ve":3,"vl":"3","bn":"বুদ্ধিহীন মেয়েরা তাদের বাতি নিল বটে কিন্তু সংগে করে তেল নিল না।"},{"v":4,"ve":4,"vl":"4","bn":"বুদ্ধিমতি মেয়েরা তাদের বাতির সংগে পাত্রে করে তেলও নিল।"},{"v":5,"ve":5,"vl":"5","bn":"বর আসতে দেরি হওয়াতে তারা ঢুলতে ঢুলতে সবাই ঘুমিয়ে পড়ল।"},{"v":6,"ve":6,"vl":"6","bn":"“পরে মাঝ রাতে চিৎকার শোনা গেল, ‘ঐ দেখ, বর আসছেন! বরকে এগিয়ে আনতে বের হও।’"},{"v":7,"ve":7,"vl":"7","bn":"তখন সেই মেয়েরা উঠে তাদের বাতি ঠিক করল।"},{"v":8,"ve":8,"vl":"8","bn":"বুদ্ধিহীন মেয়েরা বুদ্ধিমতিদের বলল, ‘তোমাদের তেল থেকে আমাদের কিছু দাও, কারণ আমাদের বাতি নিভে যাচ্ছে।’"},{"v":9,"ve":9,"vl":"9","bn":"তখন সেই বুদ্ধিমতি মেয়েরা জবাবে বলল, ‘না, তেল যা আছে তাতে হয়তো আমাদের ও তোমাদের কুলাবে না। তোমরা বরং দোকানদারদের কাছে গিয়ে নিজেদের জন্য তেল কিনে নাও।’"},{"v":10,"ve":10,"vl":"10","bn":"সেই বুদ্ধিহীন মেয়েরা যখন তেল কিনতে গেল তখনই বর এসে পড়লেন। তখন যে মেয়েরা প্রস্তুত ছিল তারা বরের সংগে বিয়ে বাড়ীতে গেল। তারা সবাই ভিতরে গেলে পর দরজা বন্ধ করে দেওয়া হল।"},{"v":11,"ve":11,"vl":"11","bn":"“পরে সেই বুদ্ধিহীন মেয়েরা এসে বলল, ‘দেখুন, দরজাটা খুলে দিন।’"},{"v":12,"ve":12,"vl":"12","bn":"জবাবে বর বললেন, ‘সত্যি বলছি, আমি তোমাদের চিনি না।’ ”"},{"v":13,"ve":13,"vl":"13","bn":"গল্পের শেষে ঈসা বললেন, “এইজন্য সতর্ক থাক, কারণ সেই দিন বা সেই সময়ের কথা তোমরা জান না।"},{"heading":"তিনজন গোলামের গল্প","v":14,"ve":14,"vl":"14","bn":"“বেহেশতী রাজ্য এমন একজন লোকের মত যিনি বিদেশে যাবার আগে তাঁর গোলামদের ডেকে তাঁর সমস্ত সম্পত্তির ভার তাদের হাতে দিয়ে গেলেন।"},{"v":15,"ve":15,"vl":"15","bn":"সেই গোলামদের ক্ষমতা অনুসারে তিনি একজনকে পাঁচ হাজার, একজনকে দু’হাজার ও একজনকে এক হাজার টাকা দিলেন।"},{"v":16,"ve":16,"vl":"16","bn":"যে পাঁচ হাজার টাকা পেল সে তা দিয়ে ব্যবসা করে আরও পাঁচ হাজার টাকা লাভ করল।"},{"v":17,"ve":17,"vl":"17","bn":"যে দু’হাজার টাকা পেল সে-ও একইভাবে আরও দু’হাজার টাকা লাভ করল।"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু যে এক হাজার টাকা পেল সে মাটিতে গর্ত খুঁড়ে তার মালিকের টাকাগুলো লুকিয়ে রাখল।"},{"v":19,"ve":19,"vl":"19","bn":"“অনেক দিন পরে সেই মালিক এসে গোলামদের কাছ থেকে হিসাব চাইলেন।"},{"v":20,"ve":20,"vl":"20","bn":"যে পাঁচ হাজার টাকা পেয়েছিল সে আরও পাঁচ হাজার টাকা নিয়ে এসে বলল, ‘আপনি আমাকে পাঁচ হাজার টাকা দিয়েছিলেন।"},{"v":21,"ve":21,"vl":"21","bn":"দেখুন, আমি আরও পাঁচ হাজার টাকা লাভ করেছি।’ তখন তার মালিক তাকে বললেন, ‘শাবাশ! তুমি ভাল ও বিশ্বস্ত গোলাম। তুমি অল্প বিষয়ে বিশ্বস্ত বলে আমি তোমাকে অনেক বিষয়ের ভার দেব। এস, আমার আনন্দের ভাগী হও।’"},{"v":22,"ve":22,"vl":"22","bn":"“যে দু’হাজার টাকা পেয়েছিল সে এসে বলল, ‘আপনি আমাকে দু’হাজার টাকা দিয়েছিলেন। দেখুন, আমি আরও দু’হাজার টাকা লাভ করেছি।’"},{"v":23,"ve":23,"vl":"23","bn":"তখন তার মালিক তাকে বললেন, ‘শাবাশ! তুমি ভাল ও বিশ্বস্ত গোলাম। তুমি অল্প বিষয়ে বিশ্বস্ত বলে আমি তোমাকে অনেক বিষয়ের ভার দেব। এস, আমার আনন্দের ভাগী হও।’"},{"v":24,"ve":24,"vl":"24","bn":"“কিন্তু যে এক হাজার টাকা পেয়েছিল সে এসে বলল, ‘দেখুন, আমি জানতাম আপনি ভয়ানক কঠিন লোক। আপনি যেখানে বীজ বোনেন নি সেখান থেকে কাটেন এবং যেখানে ছড়ান নি সেখান থেকে কুড়ান।"},{"v":25,"ve":25,"vl":"25","bn":"এইজন্য আমি ভয়ে ভয়ে বাইরে গিয়ে মাটিতে আপনার টাকা লুকিয়ে রেখেছিলাম। এই দেখুন, আপনার জিনিস আপনারই আছে।’"},{"v":26,"ve":26,"vl":"26","bn":"জবাবে তার মালিক তাকে বললেন, ‘দুষ্ট ও অলস গোলাম! তুমি তো জানতে যেখানে আমি বুনি নি সেখানে কাটি আর যেখানে ছড়াই নি সেখানে কুড়াই।"},{"v":27,"ve":27,"vl":"27","bn":"তাহলে মহাজনদের কাছে আমার টাকা জমা রাখ নি কেন? তা করলে তো আমি এসে টাকাটাও পেতাম এবং সংগে কিছু সুদও পেতাম।’"},{"v":28,"ve":28,"vl":"28","bn":"তারপর তিনি অন্যদের বললেন, ‘তোমরা ওর কাছ থেকে টাকাগুলো নিয়ে যার দশ হাজার টাকা আছে তাকে দাও।"},{"v":29,"ve":29,"vl":"29","bn":"যার আছে তাকে আরও দেওয়া হবে আর তাতে তার অনেক হবে। কিন্তু যার নেই তার যা আছে তা-ও তার কাছ থেকে নিয়ে নেওয়া হবে।"},{"v":30,"ve":30,"vl":"30","bn":"ঐ অপদার্থ গোলামকে তোমরা বাইরের অন্ধকারে ফেলে দাও; সেখানে লোকে কান্নাকাটি করবে আর যন্ত্রণায় দাঁতে দাঁত ঘষতে থাকবে।’"},{"heading":"সমস্ত জাতির বিচার","v":31,"ve":31,"vl":"31","bn":"“ইব্‌ন্তেআদম সমস্ত ফেরেশতাদের সংগে নিয়ে যখন নিজের মহিমায় আসবেন তখন তিনি বাদশাহ্‌ হিসাবে তাঁর সিংহাসনে মহিমার সংগে বসবেন।"},{"v":32,"ve":32,"vl":"32","bn":"সেই সময় সমস্ত জাতির লোকদের তাঁর সামনে একসংগে জমায়েত করা হবে। রাখাল যেমন ভেড়া আর ছাগল আলাদা করে তেমনি তিনি সব লোকদের দু’ভাগে আলাদা করবেন।"},{"v":33,"ve":33,"vl":"33","bn":"তিনি নিজের ডান দিকে ভেড়াদের আর বাঁ দিকে ছাগলদের রাখবেন।"},{"v":34,"ve":34,"vl":"34","bn":"“এর পরে বাদশাহ্‌ তাঁর ডান দিকের লোকদের বলবেন, ‘তোমরা যারা আমার পিতার দোয়া পেয়েছ, এস। দুনিয়ার শুরুতে যে রাজ্য তোমাদের জন্য প্রস্তুত করে রাখা হয়েছে তার অধিকারী হও।"},{"v":35,"ve":35,"vl":"35","bn":"যখন আমার খিদে পেয়েছিল তখন তোমরা আমাকে খেতে দিয়েছিলে; যখন পিপাসা পেয়েছিল তখন পানি দিয়েছিলে; যখন মেহমান হয়েছিলাম তখন আশ্রয় দিয়েছিলে;"},{"v":36,"ve":36,"vl":"36","bn":"যখন খালি গায়ে ছিলাম তখন কাপড় পরিয়েছিলে; যখন অসুস্থ হয়েছিলাম তখন আমার দেখাশোনা করেছিলে; আর যখন আমি জেলখানায় বন্দী অবস্থায় ছিলাম তখন আমাকে দেখতে গিয়েছিলে।’"},{"v":37,"ve":37,"vl":"37","bn":"“তখন সেই আল্লাহ্‌ভক্ত লোকেরা জবাবে তাঁকে বলবে, ‘প্রভু, আপনার খিদে পেয়েছে দেখে কখন আপনাকে খেতে দিয়েছিলাম বা পিপাসা পেয়েছে দেখে পানি দিয়েছিলাম?"},{"v":38,"ve":38,"vl":"38","bn":"কখনই বা আপনাকে মেহমান হিসাবে আশ্রয় দিয়েছিলাম, কিংবা খালি গায়ে দেখে কাপড় পরিয়েছিলাম?"},{"v":39,"ve":39,"vl":"39","bn":"আর কখনই বা আপনাকে অসুস্থ বা জেলখানায় আছেন জেনে আপনার কাছে গিয়েছিলাম?’"},{"v":40,"ve":40,"vl":"40","bn":"“এর জবাবে বাদশাহ্‌ তখন তাদের বলবেন, ‘আমি তোমাদের সত্যিই বলছি, আমার এই ভাইদের মধ্যে সামান্য কোন একজনের জন্য যখন তা করেছিলে তখন আমারই জন্য তা করেছিলে।’"},{"v":41,"ve":41,"vl":"41","bn":"“পরে তিনি তাঁর বাঁ দিকের লোকদের বলবেন, ‘ওহে বদদোয়াপ্রাপ্ত লোকেরা, আমার কাছ থেকে তোমরা দূর হও। ইবলিস এবং তার ফেরেশতাদের জন্য যে চিরকালের আগুন প্রস্তুত করা হয়েছে তার মধ্যে যাও।"},{"v":42,"ve":42,"vl":"42","bn":"যখন আমার খিদে পেয়েছিল তখন তোমরা আমাকে খেতে দাও নি; যখন পিপাসা পেয়েছিল তখন পানি দাও নি;"},{"v":43,"ve":43,"vl":"43","bn":"যখন মেহমান হয়েছিলাম তখন আশ্রয় দাও নি; যখন খালি গায়ে ছিলাম তখন আমাকে কাপড় পরাও নি; যখন অসুস্থ হয়েছিলাম এবং জেলখানায় বন্দী অবস্থায় ছিলাম তখন আমাকে দেখতে যাও নি।’"},{"v":44,"ve":44,"vl":"44","bn":"“তখন তারা তাঁকে বলবে, ‘প্রভু, কখন আপনার খিদে বা পিপাসা পেয়েছে দেখে, কিংবা মেহমান হয়েছেন দেখে, কিংবা খালি গায়ে দেখে, কিংবা অসুস্থ বা জেলখানায় আছেন জেনে সাহায্য করি নি?’"},{"v":45,"ve":45,"vl":"45","bn":"“জবাবে তিনি তাদের বলবেন, ‘আমি তোমাদের সত্যিই বলছি, তোমরা যখন এই সামান্য লোকদের মধ্যে কোন একজনের জন্য তা কর নি তখন তা আমার জন্যই কর নি।’ ”"},{"v":46,"ve":46,"vl":"46","bn":"তারপর ঈসা বললেন, “এই লোকেরা অনন্ত শাস্তি পেতে যাবে, কিন্তু ঐ আল্লাহ্‌ভক্ত লোকেরা অনন্ত জীবন ভোগ করতে যাবে।”"}],"26":[{"heading":"হযরত ঈসা মসীহ্‌কে হত্যা করবার ষড়যন্ত্র","v":1,"ve":1,"vl":"1","bn":"এই সব কথার শেষে ঈসা তাঁর সাহাবীদের বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“তোমরা তো জান আর দুই দিন পরেই উদ্ধার-ঈদ, আর ইব্‌ন্তেআদমকে ক্রুশের উপরে হত্যা করবার জন্য ধরিয়ে দেওয়া হবে।”"},{"v":3,"ve":4,"vl":"3-4","bn":"সেই সময়ে মহা-ইমাম কাইয়াফার বাড়ীতে প্রধান ইমামেরা ও ইহুদীদের বৃদ্ধ নেতারা একত্র হলেন এবং ঈসাকে গোপনে ধরে এনে হত্যা করবার ষড়যন্ত্র করলেন।"},{"v":5,"ve":5,"vl":"5","bn":"তবে তাঁরা বললেন, “ঈদের সময়ে নয়; তাতে লোকদের মধ্যে হয়তো গোলমাল শুরু হবে।”"},{"heading":"হযরত ঈসা মসীহের মাথায় আতর ঢালা","v":6,"ve":6,"vl":"6","bn":"ঈসা যখন বেথানিয়াতে চর্মরোগী শিমোনের বাড়ীতে ছিলেন তখন একজন স্ত্রীলোক তাঁর কাছে আসল।"},{"v":7,"ve":7,"vl":"7","bn":"সেই স্ত্রীলোকটি একটা সাদা পাথরের পাত্রে করে খুব দামী আতর এনেছিল। ঈসা যখন খেতে বসলেন তখন সে তাঁর মাথায় সেই আতর ঢেলে দিল।"},{"v":8,"ve":8,"vl":"8","bn":"সাহাবীরা তা দেখে বিরক্ত হয়ে বললেন, “এই দামী জিনিসটা কেন নষ্ট করা হচ্ছে?"},{"v":9,"ve":9,"vl":"9","bn":"এটা তো অনেক দামে বিক্রি করে টাকাটা গরীবদের দেওয়া যেত।”"},{"v":10,"ve":10,"vl":"10","bn":"ঈসা এই কথা বুঝতে পেরে সাহাবীদের বললেন, “তোমরা এই স্ত্রীলোকটিকে দুঃখ দিচ্ছ কেন? সে তো আমার প্রতি ভাল কাজই করেছে।"},{"v":11,"ve":11,"vl":"11","bn":"গরীবেরা তো সব সময় তোমাদের মধ্যে আছে, কিন্তু আমাকে তোমরা সব সময় পাবে না।"},{"v":12,"ve":12,"vl":"12","bn":"সে আমার গায়ের উপর এই আতর ঢেলে দিয়ে আমাকে কবরের জন্য প্রস্তুত করেছে।"},{"v":13,"ve":13,"vl":"13","bn":"আমি তোমাদের সত্যিই বলছি, দুনিয়ার যে কোন জায়গায় সুসংবাদ তবলিগ করা হবে সেখানে এই স্ত্রীলোকটির কথা মনে করিয়ে দেবার জন্য তার এই কাজের কথাও বলা হবে।”"},{"heading":"ত্রিশটা টাকার লোভে","v":14,"ve":14,"vl":"14","bn":"তখন সেই বারোজন সাহাবীদের মধ্যে এহুদা ইষ্কারিয়োৎ নামে সাহাবীটি প্রধান ইমামদের কাছে গিয়ে বলল,"},{"v":15,"ve":15,"vl":"15","bn":"“ঈসাকে আপনাদের হাতে ধরিয়ে দিলে আপনারা আমাকে কি দেবেন?” প্রধান ইমামেরা ত্রিশটা রূপার টাকা গুণে তাকে দিলেন।"},{"v":16,"ve":16,"vl":"16","bn":"তার পর থেকেই এহুদা ঈসাকে ধরিয়ে দেবার জন্য সুযোগ খুঁজতে লাগল।"},{"heading":"শেষ উদ্ধার-ঈদের মেজবানী","v":17,"ve":17,"vl":"17","bn":"খামিহীন রুটির ঈদের প্রথম দিনে সাহাবীরা ঈসার কাছে এসে বললেন, “আপনার জন্য উদ্ধার-ঈদের মেজবানী আমাদের কোথায় প্রস্তুত করতে বলেন?”"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা বললেন, “শহরের মধ্যে গিয়ে ঐ লোককে বল যে, হুজুর বলছেন, ‘আমার সময় কাছে এসে গেছে। আমার সাহাবীদের সংগে আমি তোমার বাড়ীতেই উদ্ধার-ঈদ পালন করব।’ ”"},{"v":19,"ve":19,"vl":"19","bn":"ঈসা সাহাবীদের যে হুকুম দিয়েছিলেন সাহাবীরা সেইভাবেই উদ্ধার-ঈদের মেজবানী প্রস্তুত করলেন।"},{"v":20,"ve":20,"vl":"20","bn":"পরে সন্ধ্যা হলে ঈসা সেই বারোজন সাহাবীকে নিয়ে খেতে বসলেন।"},{"v":21,"ve":21,"vl":"21","bn":"খাবার সময়ে তিনি বললেন, “আমি তোমাদের সত্যিই বলছি, তোমাদের মধ্যে একজন আমাকে শত্রুদের হাতে ধরিয়ে দেবে।”"},{"v":22,"ve":22,"vl":"22","bn":"এতে সাহাবীরা খুব দুঃখিত হয়ে একজনের পর একজন ঈসাকে জিজ্ঞাসা করতে লাগলেন, “সে কি আমি, হুজুর?”"},{"v":23,"ve":23,"vl":"23","bn":"জবাবে তিনি তাঁদের বললেন, “যে আমার সংগে পাত্রের মধ্যে হাত দিচ্ছে সে-ই আমাকে ধরিয়ে দেবে।"},{"v":24,"ve":24,"vl":"24","bn":"ইব্‌ন্তেআদমের বিষয়ে পাক-কিতাবে যেভাবে লেখা আছে ঠিক সেইভাবে তিনি মারা যাবেন বটে, কিন্তু হায় সেই লোক, যে ইব্‌ন্তেআদমকে শত্রুদের হাতে ধরিয়ে দেয়! সেই মানুষের জন্ম না হলেই বরং তার পক্ষে ভাল হত।”"},{"v":25,"ve":25,"vl":"25","bn":"যে ঈসাকে শত্রুদের হাতে ধরিয়ে দিতে যাচ্ছিল সেই এহুদা বলল, “হুজুর, সে কি আমি?” ঈসা তাকে বললেন, “তুমি ঠিক কথাই বললে।”"},{"v":26,"ve":26,"vl":"26","bn":"খাওয়া-দাওয়া চলছে, এমন সময় ঈসা রুটি নিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন। পরে তিনি সেই রুটি টুকরা টুকরা করলেন এবং সাহাবীদের দিয়ে বললেন, “এই নাও, খাও; এ আমার শরীর।”"},{"v":27,"ve":27,"vl":"27","bn":"এর পরে তিনি পেয়ালা নিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন ও সেটা সাহাবীদের দিয়ে বললেন, “পেয়ালার এই আংগুর-রস তোমরা সবাই খাও,"},{"v":28,"ve":28,"vl":"28","bn":"কারণ এ আমার রক্ত যা অনেকের গুনাহের ক্ষমার জন্য দেওয়া হবে। মানুষের জন্য আল্লাহ্‌র নতুন ব্যবস্থা আমার এই রক্তের দ্বারাই বহাল করা হবে।"},{"v":29,"ve":29,"vl":"29","bn":"আমি তোমাদের বলছি, এখন থেকে যতদিন আমি আমার পিতার রাজ্যে তোমাদের সংগে আংগুর ফলের রস নতুন ভাবে না খাই ততদিন পর্যন্ত আমি আর তা খাব না।”"},{"v":30,"ve":30,"vl":"30","bn":"পরে তাঁরা একটা কাওয়ালী গেয়ে বের হয়ে জৈতুন পাহাড়ে গেলেন।"},{"heading":"হযরত পিতরের অস্বীকার করবার কথা","v":31,"ve":31,"vl":"31","bn":"পরে ঈসা তাঁর সাহাবীদের বললেন, “আজ রাতে আমাকে নিয়ে তোমাদের সকলের মনে বাধা আসবে। পাক-কিতাবে লেখা আছে, ‘আমি রাখালকে মেরে ফেলব, তাতে পালের মেষগুলো ছড়িয়ে পড়বে।’"},{"v":32,"ve":32,"vl":"32","bn":"কিন্তু আমাকে মৃত্যু থেকে জীবিত করা হলে পর আমি তোমাদের আগেই গালীলে যাব।”"},{"v":33,"ve":33,"vl":"33","bn":"তখন পিতর তাঁকে বললেন, “আপনাকে নিয়ে সবার মনে বাধা আসলেও আমার মনে কখনও বাধা আসবে না।”"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা তাঁকে বললেন, “কিন্তু আমি তোমাকে সত্যিই বলছি, আজ শেষ রাতে মোরগ ডাকবার আগেই তুমি তিন বার বলবে যে, তুমি আমাকে চেনো না।”"},{"v":35,"ve":35,"vl":"35","bn":"পিতর ঈসাকে বললেন, “আমাকে যদি আপনার সংগে মরতেও হয় তবুও আমি কখনও বলব না, আমি আপনাকে চিনি না।” অন্য সাহাবীরা সবাই সেই একই কথা বললেন।"},{"heading":"গেৎশিমানী বাগানে","v":36,"ve":36,"vl":"36","bn":"পরে ঈসা সাহাবীদের সংগে গেৎশিমানী নামে একটা জায়গায় গেলেন এবং সাহাবীদের বললেন, “আমি ওখানে গিয়ে যতক্ষণ মুনাজাত করি ততক্ষণ তোমরা এখানে বসে থাক।”"},{"v":37,"ve":37,"vl":"37","bn":"এই বলে তিনি পিতর আর সিবদিয়ের দুই ছেলেকে সংগে নিয়ে গেলেন। তাঁর মন দুঃখে ও কষ্টে ভরে উঠতে লাগল।"},{"v":38,"ve":38,"vl":"38","bn":"তিনি তাঁদের বললেন, “দুঃখে যেন আমার প্রাণ বেরিয়ে যাচ্ছে। তোমরা এখানেই থাক আর আমার সংগে জেগে থাক।”"},{"v":39,"ve":39,"vl":"39","bn":"পরে তিনি কিছু দূরে গিয়ে মাটিতে উবুড় হয়ে পড়লেন এবং মুনাজাত করে বললেন, “আমার পিতা, যদি সম্ভব হয় তবে এই দুঃখের পেয়ালা আমার কাছ থেকে দূরে যাক। তবুও আমার ইচ্ছামত না হোক, তোমার ইচ্ছামতই হোক।”"},{"v":40,"ve":40,"vl":"40","bn":"এর পরে তিনি সাহাবীদের কাছে এসে দেখলেন তাঁরা ঘুমিয়ে পড়েছেন। তিনি পিতরকে বললেন, “এ কি! আমার সংগে এক ঘণ্টাও কি তোমরা জেগে থাকতে পারলে না?"},{"v":41,"ve":41,"vl":"41","bn":"জেগে থাক ও মুনাজাত কর যেন পরীক্ষায় না পড়। দিলে ইচ্ছা আছে বটে, কিন্তু শরীর দুর্বল।”"},{"v":42,"ve":42,"vl":"42","bn":"তিনি ফিরে গিয়ে দ্বিতীয় বার মুনাজাত করে বললেন, “পিতা আমার, আমি গ্রহণ না করলে যদি এই দুঃখের পেয়ালা দূর না হয় তবে তোমার ইচ্ছাই পূর্ণ হোক।”"},{"v":43,"ve":43,"vl":"43","bn":"তিনি ফিরে এসে দেখলেন তাঁরা আবার ঘুমিয়ে পড়েছেন, কারণ তাঁদের চোখ ঘুমে ভারী হয়ে গিয়েছিল।"},{"v":44,"ve":44,"vl":"44","bn":"তিনি আবার তাঁদের ছেড়ে গিয়ে তৃতীয় বার সেই একই কথা বলে মুনাজাত করলেন।"},{"v":45,"ve":45,"vl":"45","bn":"পরে তিনি সাহাবীদের কাছে এসে বললেন, “এখনও তোমরা ঘুমা\"ছ আর বিশ্রাম করছ? দেখ, সময় এসে পড়েছে, ইব্‌ন্তেআদমকে গুনাহ্‌গারদের হাতে ধরিয়ে দেওয়া হবে।"},{"v":46,"ve":46,"vl":"46","bn":"ওঠো, চল, আমরা যাই। দেখ, যে আমাকে শত্রুদের হাতে ধরিয়ে দেবে সে এসে পড়েছে।”"},{"heading":"শত্রুদের হাতে হযরত ঈসা মসীহ্‌","v":47,"ve":47,"vl":"47","bn":"ঈসা তখনও কথা বলছেন, এমন সময় এহুদা সেখানে আসল। সে সেই বারোজন সাহাবীদের মধ্যে একজন ছিল। তার সংগে অনেক লোক ছোরা ও লাঠি নিয়ে আসল। প্রধান ইমামেরা ও বৃদ্ধ নেতারা এদের পাঠিয়েছিলেন।"},{"v":48,"ve":48,"vl":"48","bn":"ঈসাকে শত্রুদের হাতে যে ধরিয়ে দিয়েছিল সেই এহুদা ঐ লোকদের সংগে একটা চিহ্ন ঠিক করেছিল; সে বলেছিল, “যাকে আমি চুমু দেব সে-ই সেই লোক; তোমরা তাকে ধরবে।”"},{"v":49,"ve":49,"vl":"49","bn":"তাই এহুদা সোজা ঈসার কাছে গিয়ে বলল, “আস্‌সালামু আলাইকুম, হুজুর।” এই কথা বলেই সে ঈসাকে চুমু দিল।"},{"v":50,"ve":50,"vl":"50","bn":"ঈসা তাকে বললেন, “বন্ধু, যা করতে এসেছ, কর।” সংগে সংগেই লোকেরা এসে ঈসাকে ধরল।"},{"v":51,"ve":51,"vl":"51","bn":"যাঁরা ঈসার সংগে ছিলেন তাঁদের মধ্যে একজন তাঁর ছোরা বের করলেন এবং তার আঘাতে মহা-ইমামের গোলামের একটা কান কেটে ফেললেন।"},{"v":52,"ve":52,"vl":"52","bn":"তখন ঈসা তাঁকে বললেন, “তোমার ছোরা খাপে রাখ। ছোরা যারা ধরে তারা ছোরার আঘাতেই মরে।"},{"v":53,"ve":53,"vl":"53","bn":"তুমি কি মনে কর যে, আমি আমার পিতাকে ডাকলে তিনি এখনই আমাকে হাজার হাজার ফেরেশতা পাঠিয়ে দেবেন না? কিন্তু তাহলে পাক-কিতাবের কথা কিভাবে পূর্ণ হবে?"},{"v":54,"ve":54,"vl":"54","bn":"কিতাবে তো লেখা আছে এই সব এভাবেই ঘটবে।”"},{"v":55,"ve":55,"vl":"55","bn":"পরে ঈসা লোকদের বললেন, “আমি কি ডাকাত যে, আপনারা ছোরা ও লাঠি নিয়ে আমাকে ধরতে এসেছেন? আমি প্রত্যেক দিনই বায়তুল-মোকাদ্দসে বসে শিক্ষা দিতাম, আর তখন তো আপনারা আমাকে ধরেন নি।"},{"v":56,"ve":56,"vl":"56","bn":"কিন্তু এই সব ঘটল যাতে পাক-কিতাবে নবীরা যা লিখেছেন তা পূর্ণ হয়।” সাহাবীরা সবাই তখন ঈসাকে ফেলে পালিয়ে গেলেন।"},{"heading":"মহাসভার সামনে হযরত ঈসা মসীহ্‌","v":57,"ve":57,"vl":"57","bn":"যারা ঈসাকে ধরেছিল তারা তাকে মহা-ইমাম কাইয়াফার কাছে নিয়ে গেল। সেখানে আলেমেরা ও বৃদ্ধ নেতারা একসংগে জমায়েত হয়েছিলেন।"},{"v":58,"ve":58,"vl":"58","bn":"পিতর দূরে থেকে ঈসার পিছনে পিছনে মহা-ইমামের উঠান পর্যন্ত গেলেন এবং শেষে কি হয় তা দেখবার জন্য ভিতরে ঢুকে রক্ষীদের সংগে বসলেন।"},{"v":59,"ve":59,"vl":"59","bn":"ঈসাকে হত্যা করবার উদ্দেশ্যে প্রধান ইমামেরা এবং মহাসভার সমস্ত লোকেরা মিথ্যা সাক্ষ্যের খোঁজ করছিলেন।"},{"v":60,"ve":60,"vl":"60","bn":"অনেক মিথ্যা সাক্ষী উপস্থিতও হয়েছিল, তবুও তাঁরা ঠিকমত কোন সাক্ষ্যই পেলেন না। শেষে দু’জন লোক এগিয়ে এসে বলল,"},{"v":61,"ve":61,"vl":"61","bn":"“এই লোকটা বলেছিল, সে আল্লাহ্‌র ঘরটা ভেংগে ফেলে তিন দিনের মধ্যে আবার তা তৈরী করে দিতে পারে।”"},{"v":62,"ve":62,"vl":"62","bn":"তখন মহা-ইমাম উঠে দাঁড়িয়ে ঈসাকে বললেন, “তুমি কি কোন জবাব দেবে না? এরা তোমার বিরুদ্ধে এই সব কি সাক্ষ্য দিচ্ছে?”"},{"v":63,"ve":63,"vl":"63","bn":"ঈসা কিন্তু চুপ করেই রইলেন। মহা-ইমাম আবার তাঁকে বললেন, “তুমি আল্লাহ্‌র কসম খেয়ে আমাদের বল যে, তুমি সেই মসীহ্‌ ইব্‌নুল্লাহ্‌ কি না।”"},{"v":64,"ve":64,"vl":"64","bn":"তখন ঈসা তাঁকে বললেন, “জ্বী, আপনি ঠিক কথাই বলেছেন। তবে আমি আপনাদের এটাও বলছি, এর পরে আপনারা ইব্‌ন্তেআদমকে সর্বশক্তিমান আল্লাহ্‌র ডান পাশে বসে থাকতে এবং মেঘে করে আসতে দেখবেন।”"},{"v":65,"ve":65,"vl":"65","bn":"তখন মহা-ইমাম তাঁর কাপড় ছিঁড়ে ফেলে বললেন, “এ কুফরী করল। আমাদের আর সাক্ষীর কি দরকার? এখনই তো আপনারা শুনলেন, সে কুফরী করল।"},{"v":66,"ve":66,"vl":"66","bn":"আপনারা কি মনে করেন?” তাঁরা জবাব দিলেন, “এ মৃত্যুর উপযুক্ত।”"},{"v":67,"ve":67,"vl":"67","bn":"তখন লোকেরা ঈসার মুখে থুথু দিল এবং ঘুষি ও চড় মারল।"},{"v":68,"ve":68,"vl":"68","bn":"তারা বলল, “এই মসীহ্‌, বল্‌ তো দেখি, কে তোকে মারল?”"},{"heading":"হযরত পিতরের অস্বীকার","v":69,"ve":69,"vl":"69","bn":"সেই সময় পিতর বাইরের উঠানে বসে ছিলেন। একজন চাকরাণী তাঁর কাছে এসে বলল, “গালীলের ঈসার সংগে তো আপনিও ছিলেন।”"},{"v":70,"ve":70,"vl":"70","bn":"কিন্তু পিতর সকলের সামনে অস্বীকার করে বললেন, “তুমি কি বলছ তা আমি জানি না।”"},{"v":71,"ve":71,"vl":"71","bn":"এর পরে পিতর বাইরে দরজার কাছে গেলেন। তাঁকে দেখে আর একজন চাকরাণী সেখানকার লোকদের বলল, “এই লোকটা নাসরতের ঈসার সংগে ছিল।”"},{"v":72,"ve":72,"vl":"72","bn":"তখন পিতর কসম খেয়ে আবার অস্বীকার করে বললেন, “আমি ঐ লোকটাকে চিনি না।”"},{"v":73,"ve":73,"vl":"73","bn":"যে লোকেরা সেখানে দাঁড়িয়ে ছিল তারা কিছুক্ষণ পরে পিতরকে এসে বলল, “নিশ্চয়ই তুমি ওদের একজন; তোমার ভাষাই তোমাকে ধরিয়ে দিচ্ছে।”"},{"v":74,"ve":74,"vl":"74","bn":"তখন পিতর নিজেকে বদদোয়া দিলেন এবং কসম খেয়ে বলতে লাগলেন, “আমি ঐ লোকটাকে মোটেই চিনি না।” আর তখনই একটা মোরগ ডেকে উঠল।"},{"v":75,"ve":75,"vl":"75","bn":"তখন পিতরের মনে পড়ল ঈসা বলেছিলেন, “মোরগ ডাকবার আগে তুমি তিন বার বলবে যে, তুমি আমাকে চেনো না।” আর পিতর বাইরে গিয়ে খুব কাঁদতে লাগলেন।"}],"27":[{"heading":"পীলাতের সামনে হযরত ঈসা মসীহ্‌","v":1,"ve":1,"vl":"1","bn":"খুব ভোরে প্রধান ইমামেরা ও বৃদ্ধ নেতারা সবাই ঈসাকে হত্যা করবার কথাই ঠিক করলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁরা ঈসাকে বেঁধে নিয়ে গিয়ে রোমীয় প্রধান শাসনকর্তা পীলাতের হাতে দিলেন।"},{"heading":"এহুদার মৃত্যু","v":3,"ve":3,"vl":"3","bn":"ঈসাকে শত্রুদের হাতে যে ধরিয়ে দিয়েছিল সেই এহুদা যখন দেখল ঈসাকে বিচারে দোষী বলে ঠিক করা হয়েছে তখন তার মনে খুব দুঃখ হল। সে প্রধান ইমামদের ও বৃদ্ধ নেতাদের কাছে সেই ত্রিশটা রূপার টাকা ফিরিয়ে দিয়ে বলল,"},{"v":4,"ve":4,"vl":"4","bn":"“আমি নির্দোষীকে মেরে ফেলবার জন্য ধরিয়ে দিয়ে গুনাহ্‌ করেছি।” তাঁরা বললেন, “তাতে আমাদের কি? তুমিই তা বুঝবে।”"},{"v":5,"ve":5,"vl":"5","bn":"তখন এহুদা সেই রূপার টাকাগুলো নিয়ে বায়তুল-মোকাদ্দসের মধ্যে ছুঁড়ে ফেলে দিয়ে চলে গেল এবং গলায় দড়ি দিয়ে মরল।"},{"v":6,"ve":6,"vl":"6","bn":"প্রধান ইমামেরা সেই রূপার টাকাগুলো নিয়ে বললেন, “এই টাকা বায়তুল-মোকাদ্দসের তহবিলে রাখা ঠিক নয়, কারণ এটা রক্তের দাম।”"},{"v":7,"ve":7,"vl":"7","bn":"পরে তাঁরা পরামর্শ করে সেই টাকা দিয়ে বিদেশীদের একটা কবরস্থানের জন্য কুমারের জমি কিনলেন।"},{"v":8,"ve":8,"vl":"8","bn":"সেইজন্য সেই জমিকে আজও ‘রক্তের জমি’ বলা হয়।"},{"v":9,"ve":9,"vl":"9","bn":"এতে নবী ইয়ারমিয়ার মধ্য দিয়ে যে কথা বলা হয়েছিল তা পূর্ণ হল: “তারা ত্রিশটা রূপার টাকা নিল। এই টাকা তাঁর দাম। বনি-ইসরাইলরা তাঁর জন্য এই দাম ঠিক করেছিল।"},{"v":10,"ve":10,"vl":"10","bn":"মাবুদ যেমন আমাকে হুকুম দিয়েছিলেন সেইমতই তারা কুমারের জমির জন্য এই টাকাগুলো দিল।”"},{"heading":"হযরত ঈসা মসীহের বিচার","v":11,"ve":11,"vl":"11","bn":"এদিকে ঈসা তখন প্রধান শাসনকর্তা পীলাতের সামনে দাঁড়িয়ে ছিলেন। শাসনকর্তা তাঁকে জিজ্ঞাসা করলেন, “তুমি কি ইহুদীদের বাদশাহ্‌?” ঈসা জবাব দিলেন, “আপনি ঠিকই বলছেন।”"},{"v":12,"ve":12,"vl":"12","bn":"প্রধান ইমামেরা এবং বৃদ্ধ নেতারা ঈসাকে অনেক দোষ দিলেন কিন্তু তিনি কোন জবাব দিলেন না।"},{"v":13,"ve":13,"vl":"13","bn":"তখন পীলাত ঈসাকে বললেন, “ওরা তোমাকে কত দোষ দিচ্ছে তা কি তুমি শুনতে পাচ্ছ না?”"},{"v":14,"ve":14,"vl":"14","bn":"ঈসা কিন্তু একটা কথারও জবাব দিলেন না। এতে সেই শাসনকর্তা খুব আশ্চর্য হয়ে গেলেন।"},{"v":15,"ve":15,"vl":"15","bn":"প্রত্যেক উদ্ধার-ঈদের সময় প্রধান শাসনকর্তা লোকদের পছন্দ করা একজন কয়েদীকে ছেড়ে দিতেন। এটাই ছিল তাঁর নিয়ম।"},{"v":16,"ve":16,"vl":"16","bn":"সেই সময় বারাব্বা নামে একজন কুখ্যাত কয়েদী ছিল।"},{"v":17,"ve":17,"vl":"17","bn":"লোকেরা একসংগে জমায়েত হলে পর পীলাত তাদের জিজ্ঞাসা করলেন, “তোমরা কি চাও? তোমাদের কাছে আমি কাকে ছেড়ে দেব, বারাব্বাকে, না যাকে মসীহ্‌ বলে সেই ঈসাকে?”"},{"v":18,"ve":18,"vl":"18","bn":"পীলাত জানতেন, লোকেরা হিংসা করেই ঈসাকে ধরিয়ে দিয়েছে।"},{"v":19,"ve":19,"vl":"19","bn":"পীলাত যখন বিচারের আসনে বসে ছিলেন তখন তাঁর স্ত্রী তাঁকে বলে পাঠালেন, “ঐ নির্দোষ লোকটিকে তুমি কিছু কোরো না, কারণ আজ স্বপ্নে আমি তাঁর দরুন অনেক কষ্ট পেয়েছি।”"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু প্রধান ইমামেরা এবং বৃদ্ধ নেতারা লোকদের উস্‌কিয়ে দিলেন যেন তারা বারাব্বাকে চেয়ে নেয় এবং ঈসাকে হত্যা করবার কথা বলে।"},{"v":21,"ve":21,"vl":"21","bn":"পরে প্রধান শাসনকর্তা লোকদের জিজ্ঞাসা করলেন, “এই দু’জনের মধ্যে আমি তোমাদের কাছে কাকে ছেড়ে দেব?” তারা বলল, “বারাব্বাকে।”"},{"v":22,"ve":22,"vl":"22","bn":"তখন পীলাত তাদের বললেন, “তাহলে যাকে মসীহ্‌ বলে সেই ঈসাকে নিয়ে আমি কি করব?” তারা সবাই বলল, “ওকে ক্রুশে দেওয়া হোক।”"},{"v":23,"ve":23,"vl":"23","bn":"পীলাত বললেন, “কেন, সে কি দোষ করেছে?” এতে তারা আরও বেশী চেঁচিয়ে বলতে লাগল, “ওকে ক্রুশে দেওয়া হোক।”"},{"v":24,"ve":24,"vl":"24","bn":"পীলাত যখন দেখলেন তিনি কিছুই করতে পারছেন না বরং আরও গোলমাল হচ্ছে, তখন তিনি পানি নিয়ে লোকদের সামনে হাত ধুয়ে বললেন, “এই লোকের রক্তের জন্য আমি দায়ী নই; তোমরাই তা বুঝবে।”"},{"v":25,"ve":25,"vl":"25","bn":"জবাবে লোকেরা সবাই বলল, “আমরা এবং আমাদের সন্তানেরা ওর রক্তের দায়ী হব।”"},{"v":26,"ve":26,"vl":"26","bn":"তখন পীলাত বারাব্বাকে লোকদের কাছে ছেড়ে দিলেন, কিন্তু ঈসাকে ভীষণভাবে চাবুক মারবার হুকুম দিয়ে ক্রুশের উপরে হত্যা করবার জন্য দিলেন।"},{"heading":"সৈন্যদের ঠাট্টা-তামাশা","v":27,"ve":27,"vl":"27","bn":"তখন প্রধান শাসনকর্তা পীলাতের সৈন্যেরা ঈসাকে নিয়ে তাঁর বাড়ীর ভিতরে গেল এবং সমস্ত সৈন্যদলকে ঈসার চারদিকে জড়ো করল।"},{"v":28,"ve":28,"vl":"28","bn":"তারা ঈসার কাপড়-চোপড় খুলে নিয়ে তাঁকে লাল রংয়ের পোশাক পরাল।"},{"v":29,"ve":29,"vl":"29","bn":"পরে তারা কাঁটা-লতা দিয়ে একটা তাজ গেঁথে তাঁর মাথায় পরিয়ে দিল, আর তাঁর ডান হাতে একটা লাঠি দিল। তার পরে তাঁর সামনে হাঁটু পেতে তাঁকে তামাশা করে বলল, “মারহাবা, ইহুদীদের বাদশাহ্‌!”"},{"v":30,"ve":30,"vl":"30","bn":"তখন তাঁর গায়ে তারা থুথু দিল এবং সেই লাঠি দিয়ে তাঁর মাথায় বারবার আঘাত করল।"},{"v":31,"ve":31,"vl":"31","bn":"তাঁকে তামাশা করবার পর তারা সেই পোশাক খুলে নিল এবং তাঁর নিজের কাপড়-চোপড় পরিয়ে তাঁকে ক্রুশের উপরে হত্যা করবার জন্য নিয়ে চলল।"},{"heading":"ক্রুশের উপরে হযরত ঈসা মসীহ্‌","v":32,"ve":32,"vl":"32","bn":"সেখান থেকে বের হয়ে যাবার সময় সৈন্যেরা কুরীণী শহরের শিমোন নামে একজন লোকের দেখা পেল। সৈন্যেরা তাকে ঈসার ক্রুশ বয়ে নিয়ে যেতে বাধ্য করল।"},{"v":33,"ve":34,"vl":"33-34","bn":"পরে তারা ‘গল্‌গথা,’ অর্থাৎ ‘মাথার খুলির স্থান’ নামে একটা জায়গায় এসে ঈসাকে তেতো মিশানো সিরকা খেতে দিল। তিনি তা মুখে দিয়ে আর খেতে চাইলেন না।"},{"v":35,"ve":35,"vl":"35","bn":"ঈসাকে ক্রুশে দেবার পর সৈন্যেরা গুলিবাঁট করে তাঁর কাপড়-চোপড় নিজেদের মধ্যে ভাগ করে নিল।"},{"v":36,"ve":36,"vl":"36","bn":"পরে তারা সেখানে বসে তাঁকে পাহারা দিতে লাগল।"},{"v":37,"ve":37,"vl":"37","bn":"তারা ক্রুশে ঈসার মাথার উপরের দিকে এই দোষ-নামা লাগিয়ে দিল, “এ ঈসা, ইহুদীদের বাদশাহ্‌।”"},{"v":38,"ve":38,"vl":"38","bn":"তারা দু’জন ডাকাতকেও ঈসার সংগে ক্রুশে দিল, একজনকে ডান দিকে আর অন্যজনকে বাঁ দিকে।"},{"v":39,"ve":39,"vl":"39","bn":"যে সব লোক সেই পথ দিয়ে যাচ্ছিল তারা মাথা নেড়ে ঈসাকে ঠাট্টা করে বলল,"},{"v":40,"ve":40,"vl":"40","bn":"“তুমি না বায়তুল-মোকাদ্দস ভেংগে আবার তিন দিনের মধ্যে তৈরী করতে পার! তাহলে এখন নিজেকে রক্ষা কর। যদি তুমি ইব্‌নুল্লাহ্‌ হও তবে ক্রুশ থেকে নেমে এস।”"},{"v":41,"ve":41,"vl":"41","bn":"প্রধান ইমামেরা ও আলেমেরা এবং বৃদ্ধ নেতারাও তাঁকে ঠাট্টা করে বললেন,"},{"v":42,"ve":42,"vl":"42","bn":"“ও অন্যদের রক্ষা করত, নিজেকে রক্ষা করতে পারে না। ও তো ইসরাইলের বাদশাহ্‌! এখন ক্রুশ থেকে ও নেমে আসুক। তাহলে আমরা ওর উপর ঈমান আনব।"},{"v":43,"ve":43,"vl":"43","bn":"ও আল্লাহ্‌র উপর ভরসা করে; এখন আল্লাহ্‌ যদি ওর উপর খুশী থাকেন তবে ওকে তিনি উদ্ধার করুন। ও তো নিজেকে ইব্‌নুল্লাহ্‌ বলত।”"},{"v":44,"ve":44,"vl":"44","bn":"যে ডাকাতদের তাঁর সংগে ক্রুশে দেওয়া হয়েছিল তারাও সেই একই কথা বলে তাঁকে টিট্‌কারি দিল।"},{"heading":"হযরত ঈসা মসীহের মৃত্যু","v":45,"ve":45,"vl":"45","bn":"সেই দিন দুপুর বারোটা থেকে বেলা তিনটা পর্যন্ত সমস্ত দেশ অন্ধকার হয়ে রইল।"},{"v":46,"ve":46,"vl":"46","bn":"প্রায় তিনটার সময় ঈসা জোরে চিৎকার করে বললেন, “ইলী, ইলী, লামা শবক্তানী,” অর্থাৎ “আল্লাহ্‌ আমার, আল্লাহ্‌ আমার, কেন তুমি আমাকে ত্যাগ করেছ?”"},{"v":47,"ve":47,"vl":"47","bn":"যারা সেখানে দাঁড়িয়ে ছিল তাদের মধ্যে কয়েকজন এই কথা শুনে বলল, “ও নবী ইলিয়াসকে ডাকছে।”"},{"v":48,"ve":48,"vl":"48","bn":"তাদের মধ্যে একজন তখনই দৌড়ে গিয়ে সিরকায় পূর্ণ একটা সপঞ্জ নিল এবং একটা লাঠির মাথায় সেটা লাগিয়ে ঈসাকে খেতে দিল।"},{"v":49,"ve":49,"vl":"49","bn":"অন্যেরা বলল, “থাক্‌, দেখি নবী ইলিয়াস ওকে রক্ষা করতে আসেন কি না।”"},{"v":50,"ve":50,"vl":"50","bn":"ঈসা আবার জোরে চিৎকার করবার পরে প্রাণত্যাগ করলেন।"},{"v":51,"ve":51,"vl":"51","bn":"তখন বায়তুল-মোকাদ্দসের পর্দাটা উপর থেকে নীচ পর্যন্ত চিরে দু’ভাগ হয়ে গেল; আর ভূমিকমপ হল ও বড় বড় পাথর ফেটে গেল।"},{"v":52,"ve":52,"vl":"52","bn":"কতগুলো কবর খুলে গেল এবং আল্লাহ্‌র যে বান্দারা ইন্তেকাল করেছিলেন তাঁদের অনেকের দেহ জীবিত হয়ে উঠল।"},{"v":53,"ve":53,"vl":"53","bn":"তাঁরা কবর থেকে বের হয়ে আসলেন এবং ঈসা মৃত্যু থেকে জীবিত হয়ে উঠলে পর পবিত্র শহরের মধ্যে গেলেন। তাঁরা সেখানে অনেককে দেখা দিলেন।"},{"v":54,"ve":54,"vl":"54","bn":"সেনাপতি ও তাঁর সংগে যারা ঈসাকে পাহারা দিচ্ছিল তারা ভূমিকমপ ও অন্য সব ঘটনা দেখে ভীষণ ভয় পেয়ে বলল, “সত্যিই উনি ইব্‌নুল্লাহ্‌ ছিলেন।”"},{"v":55,"ve":55,"vl":"55","bn":"অনেক স্ত্রীলোকও সেখানে দূরে দাঁড়িয়ে সব কিছু দেখছিলেন। ঈসার সেবা করবার জন্য তাঁরা গালীল থেকে তাঁর সংগে সংগে এসেছিলেন।"},{"v":56,"ve":56,"vl":"56","bn":"তাঁদের মধ্যে ছিলেন মগ্‌দলীনী মরিয়ম, ইয়াকুব ও ইউসুফের মা মরিয়ম এবং সিবদিয়ের ছেলে ইয়াকুব ও ইউহোন্নার মা।"},{"heading":"হযরত ঈসা মসীহের কবর","v":57,"ve":57,"vl":"57","bn":"সন্ধ্যা হলে পর অরিমাথিয়া গ্রামের ইউসুফ নামে একজন ধনী লোক সেখানে আসলেন। ইনি ঈসার উম্মত হয়েছিলেন।"},{"v":58,"ve":58,"vl":"58","bn":"পীলাতের কাছে গিয়ে তিনি ঈসার লাশটা চাইলেন। তখন পীলাত তাঁকে সেই লাশটা দিতে হুকুম দিলেন।"},{"v":59,"ve":59,"vl":"59","bn":"ইউসুফ ঈসার লাশটা নিয়ে গিয়ে পরিষ্কার কাপড়ে জড়ালেন,"},{"v":60,"ve":60,"vl":"60","bn":"আর যে নতুন কবর তিনি নিজের জন্য পাহাড়ের মধ্যে কেটে রেখেছিলেন সেখানে সেই লাশটা দাফন করলেন। পরে সেই কবরের মুখে বড় একটা পাথর গড়িয়ে দিয়ে তিনি চলে গেলেন।"},{"v":61,"ve":61,"vl":"61","bn":"কিন্তু মগ্‌দলীনী মরিয়ম ও সেই অন্য মরিয়ম সেখানে সেই কবরের সামনে বসে রইলেন।"},{"v":62,"ve":62,"vl":"62","bn":"পরের দিন, অর্থাৎ আয়োজন্তদিনের পরের দিন প্রধান ইমামেরা এবং ফরীশীরা পীলাতের কাছে জমায়েত হয়ে বললেন,"},{"v":63,"ve":63,"vl":"63","bn":"“হুজুর, আমাদের মনে পড়েছে, সেই ঠগটা বেঁচে থাকতে বলেছিল, ‘আমি তিন দিন পরে বেঁচে উঠব।’"},{"v":64,"ve":64,"vl":"64","bn":"সেইজন্য হুকুম দিন যেন তিন দিন পর্যন্ত কবরটা পাহারা দেওয়া হয়। না হলে তাঁর সাহাবীরা হয়তো এসে তাঁর লাশটা চুরি করে নিয়ে গিয়ে লোকদের বলবে, ‘তিনি মৃত্যু থেকে বেঁচে উঠেছেন।’ তাহলে প্রথম ছলনার চেয়ে শেষ ছলনাটা আরও খারাপ হবে।”"},{"v":65,"ve":65,"vl":"65","bn":"তখন পীলাত তাঁদের বললেন, “পাহারাদারদের নিয়ে গিয়ে আপনারা যেভাবে পারেন সেইভাবে পাহারা দেবার ব্যবস্থা করুন।”"},{"v":66,"ve":66,"vl":"66","bn":"তখন তাঁরা গিয়ে পাথরের উপরে সীলমোহর করলেন এবং পাহারাদারদের সেখানে রেখে কবরটা কড়াকড়িভাবে পাহারা দেবার ব্যবস্থা করলেন।"}],"28":[{"heading":"মৃত্যুর উপরে জয়লাভ","v":1,"ve":1,"vl":"1","bn":"বিশ্রামবারের পরে সপ্তার প্রথম দিনের খুব ভোরে মগ্‌দলীনী মরিয়ম ও সেই অন্য মরিয়ম কবরটা দেখতে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন হঠাৎ ভীষণ ভূমিকমপ হল, কারণ মাবুদের একজন ফেরেশতা বেহেশত থেকে নেমে আসলেন এবং কবরের মুখ থেকে পাথরখানা সরিয়ে দিয়ে তার উপর বসলেন।"},{"v":3,"ve":3,"vl":"3","bn":"তাঁর চেহারা বিদ্যুতের মত ছিল আর তাঁর কাপড়-চোপড় ছিল ধব্‌ধবে সাদা।"},{"v":4,"ve":4,"vl":"4","bn":"তাঁর ভয়ে পাহারাদারেরা কাঁপতে লাগল এবং মরার মত হয়ে পড়ল।"},{"v":5,"ve":5,"vl":"5","bn":"ফেরেশতা স্ত্রীলোকদের বললেন, “তোমরা ভয় কোরো না, কারণ আমি জানি, যাঁকে ক্রুশের উপর হত্যা করা হয়েছিল তোমরা সেই ঈসাকে খুঁজছ।"},{"v":6,"ve":6,"vl":"6","bn":"তিনি এখানে নেই। তিনি যেমন বলেছিলেন তেমন ভাবেই জীবিত হয়ে উঠেছেন। এস, তিনি যেখানে শুয়ে ছিলেন সেই জায়গাটা দেখ।"},{"v":7,"ve":7,"vl":"7","bn":"তোমরা তাড়াতাড়ি গিয়ে তাঁর সাহাবীদের বল তিনি মৃত্যু থেকে জীবিত হয়ে উঠেছেন এবং তাদের আগে গালীলে যাচ্ছেন। তারা তাঁকে সেখানেই দেখতে পাবে। দেখ, কথাটা আমি তোমাদের জানিয়ে দিলাম।”"},{"v":8,"ve":8,"vl":"8","bn":"সেই স্ত্রীলোকেরা অবশ্য ভয় পেয়েছিলেন, কিন্তু তবুও খুব আনন্দের সংগে তাড়াতাড়ি কবরের কাছ থেকে চলে গেলেন এবং ঈসার সাহাবীদের এই খবর দেবার জন্য দৌড়াতে লাগলেন।"},{"v":9,"ve":9,"vl":"9","bn":"এমন সময় ঈসা হঠাৎ সেই স্ত্রীলোকদের সামনে এসে বললেন, “আস্‌সালামু আলাইকুম।” তখন সেই স্ত্রীলোকেরা তাঁর কাছে গিয়ে পা ধরে তাঁকে সেজদা করলেন।"},{"v":10,"ve":10,"vl":"10","bn":"ঈসা তাঁদের বললেন, “ভয় কোরো না; তোমরা গিয়ে ভাইদের গালীলে যেতে বল। তারা সেখানেই আমাকে দেখতে পাবে।”"},{"v":11,"ve":11,"vl":"11","bn":"সেই স্ত্রীলোকেরা যখন চলে যাচ্ছিলেন তখন সেই পাহারাদারদের কয়েকজন শহরে গেল এবং যা যা ঘটেছিল তা প্রধান ইমামদের জানাল।"},{"v":12,"ve":12,"vl":"12","bn":"তখন ইমামেরা ও বৃদ্ধ নেতারা একত্র হয়ে পরামর্শ করলেন এবং সেই সৈন্যদের অনেক টাকা দিয়ে বললেন,"},{"v":13,"ve":13,"vl":"13","bn":"“তোমরা বোলো, ‘আমরা রাতে যখন ঘুমাচ্ছিলাম তখন তাঁর সাহাবীরা এসে তাঁকে চুরি করে নিয়ে গেছে।’"},{"v":14,"ve":14,"vl":"14","bn":"এই কথা যদি প্রধান শাসনকর্তা শুনতে পান তবে আমরা তাঁকে শান্ত করব এবং শাস্তির হাত থেকে তোমাদের রক্ষা করব।”"},{"v":15,"ve":15,"vl":"15","bn":"তখন পাহারাদারেরা সেই টাকা নিল এবং তাদের যেমন বলা হয়েছিল তেমনই বলল। আজও পর্যন্ত সেই কথা ইহুদীদের মধ্যে ছড়িয়ে আছে।"},{"heading":"হযরত ঈসা মসীহের শেষ হুকুম","v":16,"ve":16,"vl":"16","bn":"ঈসা গালীলের যে পাহাড়ে সাহাবীদের যেতে বলেছিলেন সেই এগারোজন সাহাবী তখন সেই পাহাড়ে গেলেন।"},{"v":17,"ve":17,"vl":"17","bn":"সেখানে ঈসাকে দেখে তাঁরা তাঁকে সেজদা করলেন, কিন্তু কয়েকজন সন্দেহ করলেন।"},{"v":18,"ve":18,"vl":"18","bn":"তখন ঈসা কাছে এসে তাঁদের এই কথা বললেন, “বেহেশতের ও দুনিয়ার সমস্ত ক্ষমতা আমাকে দেওয়া হয়েছে।"},{"v":19,"ve":19,"vl":"19","bn":"এইজন্য তোমরা গিয়ে সমস্ত জাতির লোকদের আমার উম্মত কর। পিতা, পুত্র ও পাক-রূহের নামে তাদের তরিকাবন্দী দাও।"},{"v":20,"ve":20,"vl":"20","bn":"আমি তোমাদের যে সব হুকুম দিয়েছি তা পালন করতে তাদের শিক্ষা দাও। দেখ, যুগের শেষ পর্যন্ত সব সময় আমি তোমাদের সংগে সংগে আছি।” ॥ভব"}]}};
